RUQL_QUESTS = RUQL_QUESTS or {}
RUQL_TITLE_INDEX = RUQL_TITLE_INDEX or {}

RUQL_QUESTS[1]={"Задание Канретада","C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была;.$b$bЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.","Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[2]={"Коготь гиппогрифа Острокогтя","Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы.$b$bСенани Громовое Сердце в приюте Серебряного Ветра несомненно пожелает увидеть этот трофей – доказательство ваших деяний.","Принесите коготь гиппогрифа Острокогтя Сенани Громовое Сердце в Приют Серебряного Ветра.","Да, |3-6(могучий,могучая) |3-6($c), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.","Очень впечатляет, $N... коготь Острокогтя непросто добыть! Тебе везет в охоте!$b$bОстрый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщепленного Дерева. Несомненно, скоро разойдется весть, что именно ты $Gприкончил:прикончила; чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!",nil,nil,nil,nil}
RUQL_QUESTS[5]={"Урчащий живот Трясунчика","Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные темные пирожки с крабами...","Поговорите с шеф-поваром Груалем.","О, посылка от моего брата? Великолепно! Сегодня мне по-настоящему светит удача!","Значит, тебе нужны пирожки с крабами? Что ж, могу испечь...",nil,nil,nil,nil}
RUQL_QUESTS[6]={"Награда за голову Гаррика Тихокрада","Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!$B$BНо будь $Gосторожен:осторожна;, $n. Гаррик собрал разбойничью шайку. До него непросто будет добраться.","Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.","Ты нашел шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?","Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!",nil,nil,nil,nil}
RUQL_QUESTS[7]={"Нападение на лагерь кобольдов","Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.","Уничтожьте 6 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.","Как прошла охота, $N? Ты $Gобнаружил:обнаружила; и $Gуничтожил:уничтожила; этих вредителей?","Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна.$b$bПримите мою благодарность за хорошую работу.",nil,nil,nil,nil}
RUQL_QUESTS[8]={"Выгодная сделка","Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.","Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.","А? Что? Что это?$B$BОтрекшиеся... на аппетит они явно не жалуются. Располагайтесь как дома... да, дайте покой своим усталым косточкам. Меня зовут Ренни, если что-то понадобится – я к вашим услугам.","Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $b$bЧто? Слишком фальшивлю? Не купился?$b$bНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $b$bВозвращайся, когда будет что потратить... бродяга. $b$bИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.",nil,nil,nil,nil}
RUQL_QUESTS[9]={"Поля смерти","Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.$b$bЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.","Убейте 20 дозорных полей по просьбе фермера Сальдена.","А, я вижу, вы вернулись! Надеюсь, вы упорно работали над тем, чтобы очистить наши угодья от дозорных полей. Двадцати еще не набралось?","Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветет.",nil,nil,nil,nil}
RUQL_QUESTS[10]={"Спасение Холстомера","Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?$b$bПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.","Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.","Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?","Юный Холстомер был хорошим гоблином. Будем надеяться, что его кончина не напрасна, и собранные перед смертью сведения не пропали даром.$b$bПохоже, от этих жуков надо ждать неприятностей. Они слишком хитры, но все исследования указывают на то, что эти твари находятся под влиянием третьей стороны! Коли так, беда грозит не только Прибамбасску, но и всей пустыне!",nil,nil,nil,nil}
RUQL_QUESTS[11]={"Награда за гноллов из стаи Речной Лапы","На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.","Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.","Приветствую, $N. Ну, как идет война с гноллами?","О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность, $N.",nil,nil,nil,nil}
RUQL_QUESTS[12]={"Народное ополчение","У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.$b$bОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.","Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.","Быть может, я недостаточно ясно выразился? Прошу прощения. Чтобы доказать, что ты $Gдостоин:достоина; вступить в ряды народного ополчения и служить Свету, ты $Gдолжен:должена; убить 15 звероловов и 15 контрабандистов из Братства Справедливости и вернуться ко мне, когда это будет сделано.","Отличная работа, $N. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело.",nil,nil,nil,nil}
RUQL_QUESTS[13]={"Народное ополчение","Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и Поместья Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.","Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.","Нет времени на разговоры, $N. Погромщики из братства Справедливости лишают жителей Западного края мира и процветания, которого они заслуживают. Удостоверься, что ты $Gубил:убила; как минимум 15 погромщиков и 15 мошенников. Это послужит остальным ясным намеком на то, что разбою здесь места нет.","Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями.",nil,nil,nil,nil}
RUQL_QUESTS[14]={"Народное ополчение","Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.","Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.","$N, сейчас не время для пустой болтовни. Если вы все еще хотите показать себя народному ополчению, вам нужно убить членов Братства, о которых я уведомил вас ранее. Возвращайся ко мне, когда выполнишь свой долг.","Я покинул разоренные земли Лордерона, вернувшись на свою родину... и застал ее в столь же ужасном состоянии. Но для Западного Края еще есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!",nil,nil,nil,nil}
RUQL_QUESTS[15]={"Разведка в руднике Горного эха","$n, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.$B$BОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка штук восемь этих тварей, посмотри, сколько еще осталось, и доложи мне.","Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду.","Ты $Gбыл:была; в руднике? $GГотов:Готова; доложить об успехах?","Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведет. Вот, это твоя награда. Когда будешь $Gготов:готова;, приходи ко мне. Буду рад, если ты согласишься предпринять еще одну вылазку…",nil,nil,nil,nil}
RUQL_QUESTS[16]={"Жажда Джерарда",nil,nil,nil,"Благодарю, $N! Решишь еще со мной поторговаться – заходи.",nil,nil,nil,nil}
RUQL_QUESTS[17]={"В Ульдаман за реактивом","Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми семейками на раскопках Ульдамана. Его можно отыскать в старых туннелях и глубинных, неизведанных зонах. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.$B$BЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!","Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар.","Ты $Gпринес:принесла; грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!","Молодец, $N, ты снова $Gпоказал:показала;, на что $Gспособен:способна;! Эти грибы мне очень пригодятся для исследований!$B$BА теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов...$B$BЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах. В любом случае, благодарю за помощь!",nil,nil,nil,nil}
RUQL_QUESTS[18]={"Братство воров","Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.$B$BНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.","Принесите 8 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.","Ну, $Gдобыл:добыла; мне банданы?","Ага, вижу, ты $Gвернулся:вернулась; не с пустыми руками. Армия Штормграда ценит твою помощь.",nil,nil,nil,nil}
RUQL_QUESTS[19]={"Тарил'зун","Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил'зун. Он уже натворил достаточно дел. Принеси мне его голову!","Принесите маршалу Маррису в Красногорье голову Тарил'зуна.","Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил'зуна!","Тарил'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда, $N.",nil,nil,nil,nil}
RUQL_QUESTS[20]={"Угроза Черной горы","К нам явились орки Черной горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной горы и принеси в доказательство десять иссеченных в бою топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.","Принесите маршалу Маррису в Приозерье 10 иссеченных в бою топоров.","Ты уже $Gохотился:охотилась; на орков, $N? Если так, покажи мне...","Что ж, чем меньше орков, тем лучше. Большое тебе спасибо.",nil,nil,nil,nil}
RUQL_QUESTS[21]={"Схватка у рудника Горного эха","Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. $B$BВремя дорого, $n. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.","Уничтожьте 8 кобольдов-рудокопов и вернитесь к маршалу Макбрайду.","Я знаю, это поганая работа, $N, но ее необходимо выполнить ради безопасности Североземья. Ты $Gготов:готова; предоставить отчет?","Ты снова $Gзаслужил:заслужила; мою похвалу и благодарность армии Штормграда. В руднике еще достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения.",nil,nil,nil,nil}
RUQL_QUESTS[22]={"Пирожок из печени кровоклыка","Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени кровоклыка!","Принесите Сальме Сальден 8 кусков печени кровоклыка, чтобы она могла испечь пирог.","Все что мне нужно для моего знаменитого мясного пирога, это 8 кусков печени кровоклыка!","Замечательные куски, $N! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. Не допускаешь же ты мысли, что $C вроде тебя останется без угощения, а?",nil,nil,nil,nil}
RUQL_QUESTS[23]={"Лапа Топтыжня","Могучий медведь Топтыжень пал от вашей руки!$b$bНа его лапе есть маленький знак полумесяца, который означает, что зверя дрессировали ночные эльфы, натаскивая его на поиск противников, скрывающихся в лесах. Неизвестно, сколько ваших союзников пали жертвой этой твари.$B$BЭту лапу надо отнести Таркану в Приют Серебряного Ветра. Он будет рад узнать, что противник лишился такого серьезного оружия.","Принесите лапу Топтыжня капитану Таркану в приют Серебряного Ветра.","Ах – $N – я только что подумала о тебе! Ну, как прошла охота?","О, лапа Топтыжня! Твои навыки меня впечатлили, |3-6($C). Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости.$b$bТвои предки гордились бы тобой!",nil,nil,nil,nil}
RUQL_QUESTS[24]={"Голова Тенумбры","Некогда стремительная Тенумбра лежит у ваших ног. Вы победили.$b$bЭто легендарное существо было гордостью ночных эльфов. Голова убитого ночного саблезуба – достойный трофей этой охоты и символ поражения Альянса в Ясеневом лесу.$b$bКапитан Гоггат из Дозора Адского Крика непременно будет счастлив получить голову убитого ночного саблезуба.","Принесите голову Тенумбры капитану Гоггату в дозор Адского Крика.","Еще раз привествую тебя, $N! Ты $Gпришел:пришла; показать мне свои охотничьи трофеи?","Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки.$b$bДикий нрав Тенумбры был хорошо известен на заставе. Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным. Благодаря тебе этой угрозы больше не существует.",nil,nil,nil,nil}
RUQL_QUESTS[25]={"Остановка у Каменного Когтя","Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?$B$BСообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на все, что только подойдет поближе... то есть, на все, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса.$B$BНу, $Gготов:готова; принести пользу?","Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Дерева.","Ты уже $Gвернулся:вернулась;? Как там ситуация? Теперь все прояснилось, благодаря тебе?","Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей. По звуку мы сможем найти пригодный наблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса. Да, только если будем сидеть тихо...$b$bПохоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено. Возьми вот это – заслужил.",nil,nil,nil,nil}
RUQL_QUESTS[26]={"Необходимый урок","$n, я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.","Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.",nil,"Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.",nil,nil,nil,nil}
RUQL_QUESTS[27]={"Необходимый урок","$n, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.","Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.",nil,"Мой поклон $Gюному:юной; |3-6($c). Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.",nil,nil,nil,nil}
RUQL_QUESTS[28]={"Испытание озера","Вот твое первое испытание – исследуй глубины озера Элуне'ара и найди безделушку святилища. Она быстро разрушается, так что немедля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $n.","Найдите безделушку святилища в озера Элуне'ара и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.$B$BПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.","Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.","Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$b$bКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты $Gотдал:отдала; дань уважения этому месту.",nil,nil,nil,nil}
RUQL_QUESTS[29]={"Испытание озера","Вот твое первое испытание – исследуй глубины озера Элуне'ара и найди безделушку святилища. Она быстро разрушается, так что немедля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $n.","Найдите безделушку святилища в озера Элуне'ара и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.$B$BПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.","Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.","Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$b$bКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты $Gотдал:отдала; дань уважения этому месту.",nil,nil,nil,nil}
RUQL_QUESTS[30]={"Испытание Морского Льва","Вот твое второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.$B$BПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.","Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.$B$BСложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремула.$B$BОтнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань что на Лунной поляне.","Вы уже собрали кулон воедино и принесли мне, $N? Если вам нужна помощь в поиске частей, спросите местных жителей, возможно, они дадут вам немного информации. Кроме того, это даст вам возможность исследовать эту чудесную и священную поляну.","Ты прошел испытание Морского Льва, $N. Прими мои поздравления.$B$BКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.$B$BЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.",nil,nil,nil,nil}
RUQL_QUESTS[31]={"Водный облик","Ты $Gзавершил:завершила; обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотему в Громовой Утес. Покажи ему свою подвеску и докажи, что ты $Gготов:готова; усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь $Gединым:единой; с водой.$B$BДоброго тебе пути, юный друид. Мы еще встретимся.","Возвращайтесь в Громовой Утес и покажите Тюраку Руническому Тотему подвеску Морского Льва.","До меня дошли слухи о твоем триумфальном возвращении в Громовой Утес, но я все равно хочу увидеть доказательства того, что ты $Gусвоил:усвоила; уроки Лунной поляны, прежде чем стану учить тебя принимать водный облик.$B$BЕсть ли у тебя подвеска Морского Льва?","Великолепно, $N. Твои предки могут гордиться твоими успехами! Ты готов прининять водный облик, и я с радостью научу тебя этому.$B$BПрими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить ее к своему снаряжению защитника Природы и хранителя равновесия.",nil,nil,nil,nil}
RUQL_QUESTS[32]={"Появление силитидов","Вот твой отчет. Прошу тебя, отнеси его кому-нибудь, сведущему в такого рода вопросах.$b$bЯ слышал про ученого-тролля по имени Зилзибин Барабанный Бой. Он посвятил много времени изучению форм жизни, встречающихся лишь в Азероте; он и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к нему. Нам любая помощь не помешает.$b$bЕго дом находится во втором ряду Волока в Оргриммаре.","Отнесите отчет Зилзибину Барабанному Бою в Оргриммар.","Прости, мы не знакомы... Но судя по всему, тебе приходилось слышать обо мне. Чем могу помочь? Ты мне что-то $Gпринес:принесла;?","Что до твоего отчета... да, я уже встречался с этими тварями. Рудознатец правильно поступил, отправив это письмо и тебя ко мне.$b$bЭти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься, $N – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу.$b$bЖаль, что нам не хватило ума понять это раньше.",nil,nil,nil,nil}
RUQL_QUESTS[33]={"Волки на границе","Видимо, эта волчья болезнь не пройдет сама собой. Каждый день количество зараженных волков все возрастает. Мне больно думать об уничтожении детей природы, но мы должны убить этих заболевших молодых волков прежде, чем начнется эпидемия.$B$BУбей зараженных молодых волков в долине и принеси мне их шкуры в доказательство того, что дело сделано.","Принесите 8 шкур зараженных волков Игану Меховщику к Аббатству Североземья.","Хэй, $N. Как идёт охота на заражённых волков?","Мрачное было дельцо, но ты $Gвыполнил:выполнила; свою часть уговора.",nil,nil,nil,nil}
RUQL_QUESTS[34]={"Незваный гость","Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.$B$BТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Приозерья, но порой заходит и сюда, в мой сад.","Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.","Грубобрюх все еще бесчинствует или ты уже $Gизбавил:избавила; Приозерье от этого паразита?","Наконец-то моему саду ничего не грозит! Спасибо тебе, $N, ты оказал мне большую услугу. Теперь мой сад расцветет с небывалой пышностью!",nil,nil,nil,nil}
RUQL_QUESTS[35]={"Новые заботы","Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несет стражу у моста и должен знать, что там происходит на самом деле.$B$BУ меня есть штормградский скакун, ты можешь воспользоваться им, чтобы добраться до стражника Томаса. Скажи мне, когда будешь $gготов:готова; отправиться.","Маршал Дугхан просит вас поговорить со стражником Томасом.",nil,"Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса. Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны.",nil,nil,nil,nil}
RUQL_QUESTS[36]={"Похлебка Западного Края","Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь.$b$bМожет быть, ты окажешь мне услугу? Я напишу рецепт похлебки Западного Края, а ты отнесешь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги.","Отнесите Сальме Сальден рецепт похлебки Западного Края.","Я буду очень скучать по Верне Хмуробров... Скажи-ка, ты не $Gвстретил:встретила; ее по пути сюда?","Эта Верна всегда была такой милой девушкой. Нам будет ее не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для нее. Ладно, хватит сплетничать! Начнем же готовить похлебку Западного Края!",nil,nil,nil,nil}
RUQL_QUESTS[37]={"Пропавшие стражи","Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчет, мне нужно выяснить, что с ними случилось.$B$BОтправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки.","Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи.",nil,"Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\".",nil,nil,nil,nil}
RUQL_QUESTS[38]={"Похлебка Западного Края","Помоги мне сварить похлебку Западного Края! Мне нужны для нее следующие ингредиенты:$b$b3 куска жилистого мяса стервятника$b3 рыла кровоклыка$b3 глаза мурлока$b3 окры","Принесите Сальме Сальден 3 куска жилистого мяса стервятника, 3 рыла кровоклыка, 3 глаза мурлока и 3 окры.","Возвращайся ко мне, когда соберешь:$B$B3 куска жилистого мяса стервятника$B3 рыла жутеклыка$B3 глаза мурлока$B3 окры.","Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла жутеклыка. И вот все готово! За оказанную помощь, $N, я предлагаю тебе отведать первую порцию похлебки Западного Края.",nil,nil,nil,nil}
RUQL_QUESTS[39]={"Донесение Томаса","Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками.$B$BЯ знаю, лишних солдат у нас нет, но, может, Дугхан пришлет хоть какую-то помощь...","Доставьте донесение в Златоземье маршалу Дугхану.",nil,"Да, вести невеселые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко.$B$BЕсли положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье...",nil,nil,nil,nil}
RUQL_QUESTS[40]={"Водяная нечисть","$n, в Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей.$B$BЯ предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчет. $B$BЯ прошу тебя, $n, поговори с Дугханом и постарайся убедить его послать отряд на восток!","Реми Повторюх просит вас найти в Златоземье маршала Дугхана и поговорить с ним.",nil,"Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчеты о появлении мурлоков на востоке крайне недостоверны.$B$BЯ понимаю твою тревогу, но пока не будут получены надежные сведения о мурлоках, никаких войск на восток я посылать не стану.",nil,nil,nil,nil}
RUQL_QUESTS[45]={"Судьба Рольфа","При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков.$B$BВозможно, именно здесь и окончил свой путь Рольф...","Обыщите поселение мурлоков и найдите Рольфа – или подтверждение его смерти.",nil,"На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\".",nil,nil,nil,nil}
RUQL_QUESTS[46]={"Награда за мурлоков","Армией Штормграда обещана награда за мурлоков-скрытней и мурлоков-добытчиков из Элвиннского леса. Убей их и принеси их рваные плавники стражнику Томасу. Армия Штормграда хорошо за это заплатит.$B$BМурлоки построили селение на Озере Каменных Столбов – это к северу отсюда. Еще одно селение расположено на юге – там, где русло реки разделяется надвое.","Принесите 8 рваных плавников мурлоков к восточному мосту Элвиннского леса и отдайте их стражнику Томасу.","Ну что, $N, как идет охота?","Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса. Он будет рад узнать, что ситуация под контролем.$B$BТвоя помощь в этом деле была просто неоценимой.",nil,nil,nil,nil}
RUQL_QUESTS[47]={"Золотая пыль","Кобольды в этих местах иногда носят с собой золотую пыль. Достань мне этой пыли, и я дам за нее лучшую цену в городе. Да, лучшую цену в городе!$B$BКобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой.","Принесите 10 порций золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу.","Эй! Ну как, есть Золотая пыль... пыль?","Благодарю за пыль, $N. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится.",nil,nil,nil,nil}
RUQL_QUESTS[48]={"Янтарное сладкое","Где-то в южных краях, там, где вьется лоза$bЕсть колодец с водой, что чиста как слеза.$bБьет священной воды одинокий ручей,$bБудь же другом, скорей, отправляйся за ней!","Принесите Мрачнобуху Громовару воду святого источника.","И-ик! Хо-хо! Хочешь выступление на бис?$B$BГде-то в южных краях, там, где вьется лоза$BЕсть колодец с водой, что чиста как слеза.$BБьет священной воды одинокий ручей,$BБудь же другом, скорей, отправляйся за ней!","И-ик! Хо-хо!",nil,nil,nil,nil}
RUQL_QUESTS[49]={"Янтарное сладкое","Как прекрасна янтарная россыпь зерна!$bСловно жаром костра пропиталась она.$bЧтобы вышел наш пенный напиток хорош,$bТы ячмень мне добудь, кукурузу и рожь.","Принесите Мрачнобуху Громовару мешок ячменя, мешок ржи и мешок кукурузы.","На бис? Легко!$B$BКак прекрасна янтарная россыпь зерна!$BСловно жаром костра пропиталась она.$BЧтобы вышел наш пенный напиток хорош,$BТы ячмень мне добудь, кукурузу и рожь.","И-ик! Хо-хо!",nil,nil,nil,nil}
RUQL_QUESTS[50]={"Янтарное сладкое","Прочь дремота и лень! Встану я поутру,$bЗамешаю зерно и в сусло разотру,$bСплавить куб перегонный – и будет добро!$bТолько истинных свойств подойдет серебро.","Принесите Мрачнобуху Громовару истинное серебро.","На бис, для тебя? Легко, мой друг!$B$BПрочь дремота и лень! Встану я поутру,$BЗамешаю зерно и в сусло разотру,$BСплавить куб перегонный - и будет добро!$BТолько истинных свойств подойдет серебро.","И-ик! Хо-хо!",nil,nil,nil,nil}
RUQL_QUESTS[51]={"Янтарное сладкое","Хочешь, друг мой, на брагу взглянуть? – так и быть!$bНам осталось лишь только ее процедить.$bВетвь смоковницы даст нам немного угля,$bБудет хмельный напиток светлей янтаря!","Принесите Мрачнобуху Громовару ветку смоковницы.","Повторить? Для тебя – что угодно!$B$BХочешь, друг мой, на брагу взглянуть? - так и быть!$BНам осталось лишь только ее процедить.$BВетвь смоковницы даст нам немного угля,$BБудет хмельный напиток светлей янтаря!","И-ик! Хо-хо!",nil,nil,nil,nil}
RUQL_QUESTS[52]={"Защита границы","Приветствую, $n. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи.$B$BХочешь нам помочь?","Убейте 8 лесных хищников и 5 молодых лесных медведей. Затем вернитесь к стражнику Томасу у восточного моста Элвиннского леса.","Надеюсь, волки и медведи уже перебиты?","Я так тебе благодарен, $N!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас.$B$BЧто бы там ни было, хотел бы я, чтобы оно не покидало леса...",nil,nil,nil,nil}
RUQL_QUESTS[53]={"Янтарное сладкое","Вот медовая брага готова вполне,$bСловно солнце играет в ее глубине!$bМы в дубовый бочонок ее разольем,$bА потом насладимся напитком вдвоем!","Принесите Мрачнобуху Громовару вязанку обуглившихся дубовых поленьев.","Конечно, ради тебя я спою еще раз!$B$BВот медовая брага готова вполне,$BСловно солнце играет в ее глубине!$BМы в дубовый бочонок ее разольем,$BА потом насладимся напитком вдвоем!","Углем отфильтровано, вызрело в бочке,$BВосторг, упоение в каждом глоточке.$BПоднимем же тост за тебя, за меня$BИ за сладкий напиток цвета янтаря!",nil,nil,nil,nil}
RUQL_QUESTS[54]={"Донесение в Златоземье","$n, ты – |3-6($c),\n\n чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса.$B$BЕсли ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.","Отнесите документы маршала Макбрайда маршалу Дугхану в Златоземье, что в Элвиннском лесу.","У тебя сообщение от маршала Макбрайда? Североземье по сравнению с Элвиннским лесом – мирный сад, но мне любопытно, о чем пишет Макбрайд.Дайте-ка мне бумаги...","Что же, тут говорится, что ты $Gбыл:была; $Gназначен:назначена; полномочным представителем маршалов Штормграда. Прими мои поздравления.$B$BИ удачи тебе... Охранять Элвинн – это непростая работа. Да еще когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки!$B$BВ наши мрачные времена политика – дело темное...",nil,nil,nil,nil}
RUQL_QUESTS[55]={"Морбент Скверн","Морбент Скверн прячется в своем доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях...$B$BПримени против него Погибель Морбента, она обратит в прах всю его защитную магию.$b$bУбей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, герой Сумеречного леса.","Примените Погибель Морбента против Морбента Скверна, убейте его и верните Погибель Морбента в лагерь Свена.","Неужели Морбент Скверн повержен?!","Морбент Скверн убит. Темные всадники по-прежнему топчут наши земли, но все же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему.$B$BТы $Gсовершил:совершила; невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу.$B$BСтупай, $N. Быть может, судьба вновь приведет тебя ко мне...",nil,nil,nil,nil}
RUQL_QUESTS[56]={"Ночной Дозор","Я – командир Ночного Дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе.$b$bЕсли ты $gготов:готова; на подвиги, помоги нам! Отправляйся на Безмятежное кладбище на юге от Темнолесья и убей 8 скелетов-воинов и 6 магов-скелетов. Мы должны дать отпор нежити!","Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев.","Я вижу, ты $Gвернулся:вернулась;, $N. Если хочешь доказать, что $Gполезен:полезена; Ночному дозору, возвращайся ко мне, когда убьешь 8 скелетов-воинов и 6 скелетов-магов.","Великолепно, $N. За верную службу народу Темнолесья тебе полагается награда.",nil,nil,nil,nil}
RUQL_QUESTS[57]={"Ночной Дозор","$n, я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей 15 скелетов-губителей и 15 ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!","Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев.","Народ Темнолесья благодарит тебя, $N. Ты $Gдоказал:доказала; свою преданность Ночному дозору.",nil,nil,nil,nil,nil}
RUQL_QUESTS[58]={"Ночной Дозор","Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках, $n. У нас не хватает стражей для обеспечения безопасности города. Придется тебе снова отправиться на Вороний холм и уничтожить 20 распространителей чумы в восточном мавзолее.","Убейте 20 распространителей чумы в восточном мавзолее Вороньего холма по просьбе командира Алтеи Чернодрев.","Мне нужна твоя помощь, $N. Отправляйся на кладбище на северо-западе и избавь восточный мавзолей от 20 распространителей чумы.$B$BВернись ко мне, когда твоя задача будет выполнена.","Я благодарю тебя, $N, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!",nil,nil,nil,nil}
RUQL_QUESTS[59]={"Броня из кожи и ткани","Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на лесопилку Восточной долины: она изготовит для тебя броню. Когда получишь новые доспехи, используй их для защиты Элвиннского леса от врагов, $n.$B$BЛесопилка находится к востоку от заставы сразу за мостом.","Отдайте Саре Тимберлейн знак брони Штормграда.","Армия Штормграда поручила мне снабжение солдат тканевыми и кожаными доспехами.$B$BЕсли ты дашь мне знак брони, я буду рада помочь тебе.","Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен.$b$bЖелаю удачи, |3-6($C)! Надеюсь, новый доспех тебе пригодится.",nil,nil,nil,nil}
RUQL_QUESTS[60]={"Свечи кобольдов","Приветствую тебя, $gдобрый путник:прекрасная госпожа;! Не найдется ли у тебя свободной минутки?$B$BМы с братом держим аптеку в Штормграде, и мне тут понадобились большие свечи. Воск нужен, понимаешь? Вот я и думаю: может, ты мне поможешь?$B$BСвечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских шахтах видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?","Принесите 8 больших свечей в Златоземье Вильяму Песту.","Ну как, ты уже $Gраздобыл:раздобыла; свечи?","Ну что, пришлось попотеть? Спасибо за свечи, $N! А вот и твоя награда...",nil,nil,nil,nil}
RUQL_QUESTS[61]={"Посылка в Штормград","В Штормграде мой брат Морган ждет посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит.$B$BВот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта.","Доставьте посылку Вильяма Моргану Песту в Торговый квартал Штормграда.","О, да это посылка от моего братца! Вот это здорово! Определенно, сегодня мой счастливый день!","Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдется какое-нибудь зелье или безделушка, которые тебе пригодятся...",nil,nil,nil,nil}
RUQL_QUESTS[62]={"Рудник Подземных глубин","Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды.$B$BНужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчета. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур.","Исследуйте рудник Подземных глубин и вернитесь в Златоземье с докладом для маршала Дугхана.","Что ты можешь сообщить, $N? Ты $Gбыл:была; в руднике Подземных глубин?","Скверные вести. И что дальше? Может, драконы?! Похоже, придется усилить охрану рудника. Спасибо тебе, $N. И подожди, не уходи... возможно, у меня найдется для тебя еще одно задание.",nil,nil,nil,nil}
RUQL_QUESTS[63]={"Зов Воды","На побережье Серебряного Бора, к западу от Гробницы, находится святилище, оскверненное чумой. Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель.$B$BВозьми браслеты элементалей и остатки зелья Брин и помести их в жаровню. Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить.$B$BПринеси мне доказательство того, что мое задание выполнено, и в награду я дам тебе тотем.","Одолейте оскверненное воплощение воды и поместите в жаровню Вечного источника в Серебряном бору его браслеты и оставшиеся капли чистейшей воды.","Жаровня все еще отражает окружающий свет, и, подойдя поближе, вы видите, что пламя тихонько колеблется.$B$BПохоже, эти места не так сильно затронула порча, и в целом, если не считать недостающих компонентов, жаровня готова к ритуалу призыва очищенного воплощения воды.","Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин. Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен...",nil,nil,nil,nil}
RUQL_QUESTS[64]={"Забытая вещь","Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты ее не пропустишь. Если вернешь мне мои часы, я буду очень признателен!","Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.","Боюсь, тебе так и не удалось достать мои часы?","Мои часы! Благодарю тебя, $Gлюбезный:любезная; $Gгосподин:госпожа;!$b$bМы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности.",nil,nil,nil,nil}
RUQL_QUESTS[65]={"Братство Справедливости","Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовет себя Братством Справедливости. Мне нужно, чтобы ты $gпроник:проникла; в эту бандитскую шайку. Нам нужно узнать, кто ее главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан.$b$bОтправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и все разузнай.","Поговорите с Вилли в Приозерье по просьбе Гриана Камнегрива.",nil,"Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу.",nil,nil,nil,nil}
RUQL_QUESTS[66]={"Легенда о Сталване","Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть.$B$BПогрузившись в длительный и тяжкий транс, я сумела разгадать эту темную тайну. Мне открылось имя: Сталван.$B$BОтыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас.","Найдите клерка Далтри в ратуше Темнолесья.",nil,"А, так тебя послала мадам Ева...",nil,nil,nil,nil}
RUQL_QUESTS[67]={"Легенда о Сталване","Сталван, значит? Дай-ка погляжу в журнал.$b$BСталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно!$b$bОкажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке.","Отправьтесь в Лунореченскую школу и сообщите все сведения о Сталване клерку Далтри.",nil,"Старый сундук со скрипом открывается...",nil,nil,nil,nil}
RUQL_QUESTS[68]={"Легенда о Сталване","Вы находите в старом сундуке пыльное неотосланное письмо.","Отнесите пыльное неотосланное письмо клерку Далтри.","А, я тебя помню. Это ты $Gспрашивал:спрашивала; насчет Сталвана. Удалось его отыскать?","Занятно. Значит, этот тип все же побывал в Луноречье. Странно, что письмо так и не доставили. Тем не менее я обновлю записи в журнале.",nil,nil,nil,nil}
RUQL_QUESTS[69]={"Легенда о Сталване","Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан еще один адрес, частично вычеркнутый. Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там, $n.","Отправляйтесь в таверну \"Гордость льва\" и спросите, не слышал ли кто о Сталване.",nil,"Сталван? Знакомое имя.",nil,nil,nil,nil}
RUQL_QUESTS[70]={"Легенда о Сталване","Имя Сталван мне знакомо. А, вспомнил.$b$bМного лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды. Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез.$b$bВторопях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана. Адресовано оно в район каналов Штормграда. Можешь прочитать.","Возьмите недоставленное письмо Сталвана из сундука и доставьте его в район каналов Штормграда.","Что это у тебя? Дай-ка посмотреть...","А ты не робкого десятка, раз $Gрешился:решилась; доставить это.",nil,nil,nil,nil}
RUQL_QUESTS[71]={"Доклад для Томаса","Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей.","Отдайте стражнику Томасу у восточного моста Элвиннского леса медальоны стражей Рольфа и Малакаи.","Приветствую, $N. Тебе удалось узнать, что случилось с Рольфом и Малакаи?","Увы, $N, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придется считаться...",nil,nil,nil,nil}
RUQL_QUESTS[72]={"Легенда о Сталване","Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится.$b$bПоследние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион. Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадется.","Найдите улики в пожитках управляющего Фольсома.",nil,"Вы медленно снимаете крышку с ящика...",nil,nil,nil,nil}
RUQL_QUESTS[73]={"<TXT> Без награды",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[74]={"Легенда о Сталване","Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника.","Отнесите страницу из дневника маршалу Хаггарду.","Что это у тебя? Не вижу. Зрение стало совсем никудышное. Дай-ка страницу сюда.","Я едва разбираю буквы, но почерк напоминает мне о... Да, я видел что-то подобное до того, как мое зрение окончательно испортилось.",nil,nil,nil,nil}
RUQL_QUESTS[75]={"Легенда о Сталване","Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов. Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой.$b$bОкажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване. Мне кажется, там была выцветшая страница с интересными записями. Принеси ее мне, и я помогу тебе по мере сил.","Найдите в сундуке на втором этаже выцветшую страницу с записями.","Ну что, $Gнашел:нашла; страницу, о которой я говорил?","Это она!",nil,nil,nil,nil}
RUQL_QUESTS[76]={"Яшмовая шахта","Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте.$B$BОтправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберешься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту.","Обследуйте Яшмовую шахту и вернитесь с докладом в Златоземье к маршалу Дугхану.","Приветствую тебя, $N. Какие новости? Что удалось обнаружить в Яшмовой шахте?","Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут все хуже и хуже!$b$bКонечно, я благодарен тебе за информацию, $N, но лучше бы мы ошибались...",nil,nil,nil,nil}
RUQL_QUESTS[77]={"Грязное дело","Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть. Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен. Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя. Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы.$B$BДостать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка. Но другого способа нет – придется тебе идти на базу и искать полные бутылки.","Найдите заброшенную базу Орды на Осклизлой скале и заберите из ящиков 10 бутылок \"Медовой зыби из Внутренних земель\".","Я так понимаю, что ты $Gпринес:принесла; мне бутылки с напитком, да?","Отличная работа, $N. Я очень рад, что напиток не испортился – нет ничего хуже на вкус, чем негодная медовуха.$B$BПогоди минутку, магии нужно время, чтобы подействовать на этот ценный груз. Хотя, на самом деле, никакой магии тут нет – я всего лишь перелью эту \"Медовую Зыбь\" в новые бутылки, и тогда этот напиток превратится в величайшее сокровище!",nil,nil,nil,nil}
RUQL_QUESTS[78]={"Легенда о Сталване","Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\". Ее хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет.","Отнесите выцветшую страницу с записями хозяину таверны Смиттсу в Темнолесье, что в Сумеречном лесу.","Тебя послал маршал Хаггард? Что ж ты молчишь?$B$BЭх, старина Хаггард. Бедняга скоро совсем ослепнет. Впрочем, давай, покажи, что там у тебя.","Клянусь Светом! Я узнаю этот почерк!",nil,nil,nil,nil}
RUQL_QUESTS[79]={"Легенда о Сталване","Я много лет следил за легендами, ходящими об этом Сталване. Когда пару лет назад нескольких заезжих аристократов нашли мертвыми, мы с Хаггардом решили расследовать это дело. Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим. Найденные тобой улики подтверждают его вину. Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!","Отнесите грязную страницу командиру Алтее Чернодрев.","Надеюсь, ты ко мне не по пустякам пришел, |3-6($C). Но, во имя Света, говори быстрее. Для меня превыше всего безопасность Темнолесья, и терять время впустую я не намерена.","Надо же, ты $Gоказался:оказалась; настоящим сыщиком, |3-6($c).",nil,nil,nil,nil}
RUQL_QUESTS[80]={"Легенда о Сталване","Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, то его вина несомненно доказана.$b$bЗа долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков. Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале.","Покажите запятнанную кровью страницу записей клерку Далтри.","И снова ты здесь, $N. Что на этот раз?","Несомненно! Почерк на этой странице совпадает с подписью в журнале.",nil,nil,nil,nil}
RUQL_QUESTS[81]={"Груз медовухи","Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки. Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка! Вот, держи.$b$bДоставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре. Да, и пожалуйста, не забудь передать привет Мальтону. Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита.","Доставьте бочонок в Оргриммар Драну Дрофферсу.","Если ты не собираешься ничего покупать и у тебя нет ничего с собой, значит, ты впустую отнимаешь у меня время! Где моя медовуха?","Ну-ка, ну-ка, надо еще посмотреть, что там в этом бочонке!$B$BДа, похоже, все цело. Ну, вот твоя плата за доставку. Я выручу впятеро больше, когда продам ее у себя в таверне! Хы-хы!$B$BНу, а эти лишние бутылки \"Медовой зыби\" из Внутренних земель прибережем для особых случаев. Надо попробовать смешать ее с шампанским. Назовем это... медованским!",nil,nil,nil,nil}
RUQL_QUESTS[82]={"Исследование Ядовитого улья","Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье. А НЕИЗВЕСТНО нам... все остальное.$b$bДля начала надо узнать, кто наш враг! Ступай в Ядовитый улей и добудь части тел проклятущих насекомых Сентипаар. Отнеси их алхимику Пестычинсу, пусть повозится. Если уж он возьмется за работу, скоро мы обо всем узнаем!","Принесите 5 частей тел насекомых Сентипаар из Ядовитого улья алхимику Пестычинсу в Прибамбасск.","Ты ведь младший геодезист, да? Говори скорее, ситуация серьезная! Ты $Gпринес:принесла; мне части тел насекомых, обещанные Рудознатцем?!","Неплохая работа – я немедленно примусь за анализ этих частей! Сразу скажу одно – таких насекомых я еще не видел. Такое впечатление, что ими управляет какая-то чуждая сила.$b$bНемедленно поговори с Рудознатцем; ситуация серьезная, ему без сомнений понадобится твоя помощь! Не знаю точно, но скорее всего речь снова пойдет о насекомых пустыни Танарис!",nil,nil,nil,nil}
RUQL_QUESTS[83]={"Превосходные льняные изделия","Головорезы Элвиннского леса носят льняные повязки, этот материал я могла бы использовать для производства превосходных льняных изделий.$B$BПринеси мне льняные повязки, а я сделаю из них кое-что полезное для тебя.$B$BЭтих бандитов полно в Элвиннском лесу.","Принесите 6 красных льняных повязок на Лесопилку Восточной долины и отдайте их Саре Тимберлейн.","Послушай, $N, у меня лен кончается. Может, выручишь меня?","Отличные повязки, даром что ткань грубовата...$b$bВот, держи!",nil,nil,nil,nil}
RUQL_QUESTS[84]={"Назад к Билли","Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!","Отнесите пирог со свининой на Виноградники Маклура и отдайте его Билли.","О-ох... Помираю с голоду... Эй, $N, не угостишь пирожком?","М-м, вкуснятина! Пирог что надо!$b$bПохоже, ко мне возвращается память...",nil,nil,nil,nil}
RUQL_QUESTS[85]={"Потерянное ожерелье","Я потеряла ожерелье. Сдается мне, его стащил этот сорванец Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники Маклура, это к востоку отсюда.$B$BПожалуйста, разыщи мое ожерелье, порадуй старуху-вдову!","Поговорите с Билли Маклуром.",nil,"Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь!$b$bМожет, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится.",nil,nil,nil,nil}
RUQL_QUESTS[86]={"Пирог для Билли","Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твое ожерелье. Кстати... Говорят, у тетушки Бернис получаются отличные пироги со свининой.$B$BПринеси ей нежной кабанины – около ферм кабанов видимо-невидимо – и попроси испечь для тебя пирог.","Принесите 4 куска нежной кабанины на ферму Стоунфилд и отдайте тетушке Бернис.","Что? Я еще должна кормить пирогами мальчишку, который стащил мое ожерелье?! С другой стороны, если подумать, пирог – не такая большая цена за то, чтобы вернуть ожерелье назад.$b$bЛадно уж... Кабанье мясо у тебя есть?","Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!",nil,nil,nil,nil}
RUQL_QUESTS[87]={"Фикс","Я играл около рудника Подземных Глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Не знаю, как оно попало туда... я тут ни при чем!$B$BВ общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в своем логове над шахтой. Если отыщешь этого кобольда, найдешь и ожерелье, точно тебе говорю!","Верните ожерелье тетушке Бернис на ферму Стоунфилдов.","О, $N? Привет, привет... Ну что, нашлось мое ожерелье?","Мое ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо!$b$bВот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил. Если бы только он взял это с собой в последний поход!..",nil,nil,nil,nil}
RUQL_QUESTS[88]={"Принцесса должна умереть!","У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке Принцесса. И эта громадная гора сала то и дело пробирается на мой огород и пожирает мои овощи!$B$BИ так вышло, что сейчас она как раз там! Принцесса должна умереть! Принеси мне ее ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное!$B$BТы найдешь Принцессу прямо в центре арбузного поля. Убей ее!","Убейте Принцессу, заберите ее ошейник и отнесите на ферму мамаше Стоунфилд.","Ну как? Надеюсь, Принцесса уже мертва?","Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна, $N!$b$bВзгляни: что-нибудь из этого тебе, надеюсь, подойдет?",nil,nil,nil,nil}
RUQL_QUESTS[89]={"Мост Безмолвия","Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем.$b$BНам не хватает материалов на ремонт моста. Если ты принесешь мне 5 железных пик и 5 железных клепок, $n, я прикажу тебя наградить.$B$BЗа дело!","Принесите 5 железных пик и 5 железных клепок штейгеру Ослоу в Приозерье.","Мост сам собой не строится! Где железные пики и железные клепки?","Отличная работа, $N. Мы можем продолжить восстановление моста. Еще немного, и закончим.",nil,nil,nil,nil}
RUQL_QUESTS[90]={"Пряные котлеты из волчатины","Мое коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить. Но для этого мне понадобятся кое-какие продукты. Принеси 10 постных волчьих боков и немного травяных приправ Штормграда. В лесу полно волков, и добыть мясо будет несложно. Что до приправы, то ее можно купить у Фелисии Гамп в цветочном магазине в районе каналов Штормграда.","Принесите 10 постных волчьих боков и травяные приправы Штормграда шеф-повару Груалю в Темнолесье.","Ты принес 10 постных волчьих боков? А травяную приправу от Фелисии из Штормграда?","Отличная работа, $N! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!",nil,nil,nil,nil}
RUQL_QUESTS[91]={"Закон Соломона","В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях.$b$bОн прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно закону Приозерья, пособничество врагу королевства карается смертью.$b$bГноллов следует уничтожить!$b$bПринеси мне 10 подвесок Темношкуров и получишь награду.","Принесите 10 подвесок Темношкуров помощнику судьи Конаху в ратушу Приозерья.","Принеси мне 10 подвесок Темношкуров и получишь награду.","Суд Озер благодарит тебя за помощь правосудию, $N. Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях.",nil,nil,nil,nil}
RUQL_QUESTS[92]={"Гуляш по-красногорски","Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!$b$bПринеси мне пять кусков жесткого мяса кондора, пять рыл больших кровоклыков и пять порций хрустящего паучьего мяса.","Принесите Бреанне пять кусков жесткого мяса кондора, пять рыл большого кровоклыка и пять порций хрустящего паучьего мяса.","Мне все еще нужны пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.","Молодец, $N. И какие отличные куски! А вот и мое коронное блюдо – гуляш по-красногорски.",nil,nil,nil,nil}
RUQL_QUESTS[93]={"Темные пирожки с крабами","Открою тебе тайну: темные пирожки с \"крабами\" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки.$B$BГоворят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой.","Добудьте 6 липких паучьих лапок и принесите их шеф-повару Груалю в Темнолесье.","Привет тебе, $N. Ну как, удалось добыть липкие паучьи лапки?","О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…$b$bИ хотя темные пирожки с крабами – мое коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже.",nil,nil,nil,nil}
RUQL_QUESTS[94]={"Недремлющее Око","Мой соперник Моргант – волшебник, наделенный великой силой, но лишенный сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашел способ следить за ним при помощи Ока Азоры.$B$BОднако Око не дает возможности проникнуть в его мысли. Для такого дела мне потребуется помощь.$B$BЕсли ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней.$B$BЕсли это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта.","Отнесите амулет Азоры к статуе льва, стоящей рядом с башней Илгалара в Красногорье.","Статуя льва уже не одно десятилетие несет свою одинокую стражу у печально знаменитой башни Илгалара.$B$BУ подножия статуи есть углубление, куда можно вложить драгоценный камень или амулет...","Вы кладете амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита:$B$BПрими мою благодарность, $Gюный:юная; $N. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание.",nil,nil,nil,nil}
RUQL_QUESTS[95]={"Месть Свена","Раньше я работал на одной из ферм на юго-востоке... а потом темные всадники спустились с перевала Мертвого Ветра и перебили всю мою семью, пока я был в отлучке!$B$BВернувшись, я увидел неподалеку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал темных всадников. Так я и не узнал, что там спрятано.$B$BЕсли ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром.","Выясните, что зарыто за старым пнем на ферме, где работал Свен.",nil,"Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало.",nil,nil,nil,nil}
RUQL_QUESTS[96]={"Зов Воды","Возьми осколок. Возьми его и даруй жизнь.$B$BДаруй жизнь и пойми. Пойми, что вода – это жизнь... А скверна – конец жизни.$B$BОберегай и даруй жизнь силой воды.","Отнесите Осколок Воды Заклинательнице Воды Ислене к Лестнице Прилива, что в Степях.","Ты $Gвернулся:вернулась;. Отлично!$B$BКак путешествие в Серебряный бор? Много времени заняло?Мне трудно понять, $Gдостиг:достигла; ли ты успеха, ведь большая часть этих земель затронута порчей. Она затмевает все доброе, что есть в них. Впрочем, порой маленькая победа оказывается не менее важной, чем большая. Очищение воды здорово поможет и тебе, и другим шаманам.","А вот и доказательство твоих свершений, как я и просила.$B$BЯ рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотем воды.$B$BПусть он служит тебе верой и правдой. Удачи!$B$BСледующее испытание ожидает тебя нескоро, поэтому учись хорошенько. Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты. Когда найдешь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания.",nil,nil,nil,nil}
RUQL_QUESTS[97]={"Легенда о Сталване","$n, немедленно сообщи командиру Чернодрев, что почерки совпадают! Ее подозрения подтвердились!","Сообщите новости командиру Алтее Чернодрев.","Да, $N?","Я так и знала! Отличная работа, $N!",nil,nil,nil,nil}
RUQL_QUESTS[98]={"Легенда о Сталване","Сталван Мистмантл вел порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, |3-6($c),\n\n и покончи со Сталваном раз и навсегда.$b$bПриведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно ее предчувствие позволило нам раскрыть это темное преступление. Благодаря ей в Темнолесье стало безопаснее.","Убейте Сталвана Мистмантла и принесите мадам Эве его фамильное кольцо.","Да, $N?","Знаю, $N, Сталван мертв. Я ощутила волну надежды, пробежавшую по оскверненному лесу. Сумеречный лес раз и навсегда освободился от кровожадной твари. Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища. А ты $Gотважен:отважна; и $Gхитер:хитра;, |3-6($C).",nil,nil,nil,nil}
RUQL_QUESTS[99]={"Безрассудство Аругала","По мере того, как растет мое понимание магии Аругала, растет и мое презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". $b$bУ меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днем живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунной Ярости. $b$bМне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне 6 заколдованных кандалов из деревни Погребальных Костров, $n.","Принесите 6 кандалов из деревни Погребальных Костров Далару Ткачу Рассвета в Гробницу.","Тебе удалось собрать для меня кандалы из деревни Погребальных Костров, $N?","Твоя настойчивость весьма похвальна. С помощью информации, которую ты $Gпомог:помогла; мне собрать, Аругал падет, и вся его безрассудная магия развеется. Браво, $N.",nil,nil,nil,nil}
RUQL_QUESTS[100]={"Зов Воды","Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь оскверненные духи вокруг вас уничтожены.","Поговорите с Низшим воплощением воды на Берегу Северного прилива, что в Серебряном бору.",nil,"Спасибо тебе. Спасибо шаманам.$B$BПорча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь.",nil,nil,nil,nil}
RUQL_QUESTS[101]={"Тотем кары","По лесу расползается тление и порча, $n, и все мы вынуждены позаботиться о самозащите. Ветер несет мне вести о великой опасности, поджидающей тебя в ближайшем будущем.$b$bЕсли ты желаешь оградить себя от нее, $gблагородный:благородная:c; |3-6($c),\n\n принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда. Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.","Принесите 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда мадам Еве в Темнолесье.","Принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда, и я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.","Ты поступил мудро, $N. Этот тотем Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотем в руку – и его магическая аура защитит тебя. Не теряй мужества, $Gпрекрасный:прекрасная; |3-6($C). Тебе оно понадобится, ибо я чувствую – грядет немало кровопролитных сражений.",nil,nil,nil,nil}
RUQL_QUESTS[102]={"Патрулирование Западного Края","Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.$b$bТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.","Принесите капитану Данувину на Сторожевой холм 8 лап гноллов.","$GНабрал:Набрала; ли ты уже 8 лап с тех вероломных гноллов?","Хорошая работа, $N. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то. Пожалуйста, прими эту награду в знак признательности за твои усилия.",nil,nil,nil,nil}
RUQL_QUESTS[103]={"Хранитель огня","Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.$b$bПомогите мне поддержать огонь факела – принесите 5 фляг масла, собрав их с сельскохозяйственных големов.","Принесите капитану Грейсону на Маяк в Западном Крае 5 бурдюков с маслом.","Огонь вскоре погаснет, если не будет масла, $N.","Хвала тебе, $Gсмелый:смелая; |3-6($C). Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел.$B$BМеня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.",nil,nil,nil,nil}
RUQL_QUESTS[104]={"Опасность на побережье","Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете. Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали. Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним. Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах.$b$bУбейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас.","Принесите чешую Старого Мрачноглаза капитану Грейсону к Маяку в Западном Крае.","Ну как, вам еще не удалось справиться с угрозой по имени Старый Мрачноглаз? Его видели носящимся вдоль береговой линии Западного Края.$B$BВозвращайтесь ко мне, когда злобная тварь будет мертва.","Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа, $N. Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других. Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию.",nil,nil,nil,nil}
RUQL_QUESTS[105]={"Увы тебе, Андорал","Увы, пришло время напасть на Андорал и изгнать оттуда лича!$b$bЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.$b$bУбей Аража и принеси мне его кристалл-талисман!","Принесите осколок оберега Аража верховному палачу Деррингтону в Бастион в Западных Чумных землях.","Тебе было дано задание, $N. Ты $Gпринес:принесла; мне кристалл лича в доказательство его выполнения?","Свершилось! Араж... этот лич наконец-то пал!$B$BСегодня ты $Gоказал:оказала; огромную услугу Орде. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в залог нашей благодарности. Пусть все знают, что благодаря тебе Орда одержала победу!",nil,nil,nil,nil}
RUQL_QUESTS[106]={"Юные влюбленные","За что мне это наказание? Мое сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу!$B$BПожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда...","Отдайте любовное послание Мейбелл Томми Джо Стоунфилду.","Письмо? От Мейбелл? О, моя радость, свет моей жизни!.. Давай скорее письмо!","Я больше не могу жить в разлуке с ней! Я должен увидеть ее!",nil,nil,nil,nil}
RUQL_QUESTS[107]={"Записка для Вильяма","Бьюсь об заклад, у Вильяма Песта найдется зелье, которое поможет соединить наших юных влюбленных!$B$BВот, держи: отнесешь эту записку Вильяму. Найдешь его в Златоземье, в таверне \"Гордость льва\".","Отнесите записку бабули Стоунфилд Вильяму Песту.","Что тут у тебя? Записка от бабули Стоунфилд? Ах, Милдред... Сто лет ее не видел. И что же она пишет?","У меня просто сердце разрывается, как подумаю об этих бедных детках, Мэйбелл и Томми Джо. Ах, молодость... Весна... Любовь...$b$bДумаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать...",nil,nil,nil,nil}
RUQL_QUESTS[108]={"<TXT> Таинственная награда",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[109]={"Доклад Гриану Камнегриву","Похоже, |3-6($c),\n\n тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.","Поговорите с Грианом Камнегривом. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.","Ну... Как дела?","А, так это мой друг тебя сюда отправил? С его стороны это большая любезность.$B$BЧто ж... Монархия Штормграда больше не поддерживает нас. Остается полагаться на ополчение. Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому.",nil,nil,nil,nil}
RUQL_QUESTS[110]={"Анализ частей насекомых","Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел. Ох, печенкой чую, не последняя это потеря, проклятые жуки еще покажут нам, где раки зимуют!$b$bПоговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых. Если все готово, принести мне результаты.","Найдите в Прибамбасске алхимика Пестычинса и получите результаты анализа частей насекомых.",nil,"Да, результаты готовы. Они, мягко говоря, неприятные.$B$BК сожалению, наши подозрения подтвердились, и насекомых контролирует неведомая сила. И не только неведомая, но и злобная. Этих насекомых превратили в настоящих опустошителей. Я такого еще не видел!",nil,nil,nil,nil}
RUQL_QUESTS[111]={"Разговор с бабулей","Прошу тебя, $n, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она.$B$BБабуля сейчас дома – это к востоку отсюда...","Поговорите с бабулей Стоунфилд.","Не могу дождаться, чтобы услышать, как отреагируют мои друзья!$B$BОни никогда этого не ожидают.","Пока наши семьи враждуют, у Томми Джо и Мэйбелл вряд ли есть шансы, но... может, мы дадим им возможность хоть немного побыть вместе.$B$BХм... Что бы придумать...",nil,nil,nil,nil}
RUQL_QUESTS[112]={"Хрустальный фукус","Да, я могу приготовить для Мейбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус.$B$BЭти водоросли растут в океане, и мурлокам иногда удается добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдется нужный компонент.Озеро находится к востоку от Златоземья.","Принесите Вильяму Песту в Златоземье 4 ветки хрустального фукуса.","Тебе удалось добыть хрустальный фукус? Уверен, Мейбелл ждет не дождется встречи со своим драгоценным Томми Джо...","Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов.",nil,nil,nil,nil}
RUQL_QUESTS[113]={"Анализ частей насекомых","Старший геодезист Рудознатец должен немедленно увидеть мой отчет. Более того... его должны увидеть все, кто умеет читать. Серьезная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору. Да что там, всему Азероту – эти твари не собираются останавливаться.$b$bПусть Рудознатец сделает копию моего отчета, распространи ее среди всех своих союзников. Пусть все узнают об этом!","Отнесите отчет старшему исследователю Рудознатцу в Прибамбасск. Получите копию отчета, как просил алхимик Пестычинс.","Ну как, младший геодезист $N, старина Пестычинс подготовил отчет?","Спасибо за доставку отчета, младший геодезист $N. Вот плата за верную службу Водной компании Прибамбасска.$B$BХотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за нее звонкой монетой, но Пестычинса я знаю много лет. Если он советует рассказать о нашествии насекомых всем и каждому, да будет так. Подожди немного, и я сделаю копию.",nil,nil,nil,nil}
RUQL_QUESTS[114]={"Бегство","Отнеси этот напиток невидимости юной Мейбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо.","Отнесите напиток невидимости Мейбелл Маклур.","Томми Джо прочел мое письмо? Что он сказал?","Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми!$b$bБлагодарю тебя, $N. Как только подвернется случай, я выпью этот напиток и найду способ пробраться к моему любимому.$b$bА в дополнение к словам благодарности прими вот это.",nil,nil,nil,nil}
RUQL_QUESTS[115]={"Темная магия","Орки из клана Черной горы позвали на помощь чародеев, а те принесли с собой источники темной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия.$B$BДобудь для меня полуночные сферы. Ты найдешь их у чародеев Черной горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!","Принесите 3 полуночных сферы маршалу Маррису в Приозерье.","Как успехи с чародеями? Где полуночные сферы?","Благодарю тебя, $N. Я немедленно прикажу уничтожить эту мерзость.",nil,nil,nil,nil}
RUQL_QUESTS[116]={"Сухие времена","У меня возникло небольшое затруднение, $n. Еще немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки.$b$bНе хочешь подзаработать?$b$BПринеси мне бочонок светлого громоварского от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.","Принесите кабатчику Дэниэлсу из Приозерья бочонок светлого громоварского из Западного края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья.","Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.","Отличная работа, $N! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков. Завсегдатаи трактира будут счастливы!",nil,nil,nil,nil}
RUQL_QUESTS[117]={"Громоварское","Торопись давай, иди побыстрей,$bЧтоб нашего пойла отведать скорей.$bОно ближе к пиву – не спутаешь с кашей,$bНо нужен нам хмель, чтоб сварить пойло наше.","Принесите Мрачнобуху Громовару 5 шишек хмеля.","Торопись, мой друг, и иди побыстрей,$bЧтоб нашего пойла отведать скорей.$bОно ближе к пиву – не спутаешь с кашей,$bНо нужен нам хмель, чтоб сварить пойло наше.","Хмель, и ячмень, и дрожжи, и солод -$bОт вкуса кидает то в жар, то в холод.$bНе надо просить и не надо молить,$bВедь можно себе из бочонка налить!",nil,nil,nil,nil}
RUQL_QUESTS[118]={"Цена подков","Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!$B$BОтнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков.","Отнесите записку Вернера кузнецу Аргусу в Златоземье, что в Элвиннском лесу.","Что такое? Говоришь, Вернер тебя послал? Давай сюда его письмо. И ГОВОРИ ГРОМЧЕ!","Так старому Вернеру нужны подковы, да?!",nil,nil,nil,nil}
RUQL_QUESTS[119]={"Доставка подков","Ладно, так и быть, пошлю ему 50 подков...$B$BВот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикрепленную к ящику!","Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье. Отдайте ему ящик с подковами.","О, да ты $Gвернулся:вернулась;! Удалось достать подковы?","Спасибо, ты здорово мне $Gпомог:помогла;.$b$bЧто это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф!$b$bЛадно, $N, спасибо за помощь.",nil,nil,nil,nil}
RUQL_QUESTS[120]={"Гонец в Штормград","Тяжелые настали времена, |3-6($c). Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми.$b$bСпеши!","Мировой судья Соломон просит вас отнести отчет генералу Маркусу Джонатану в Штормград.","С чем пришел?","Вольно, |3-6($C).$b$bЧиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королем и объясню ему ситуацию. Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепление, как только получу приказ Его Величества.",nil,nil,nil,nil}
RUQL_QUESTS[121]={"Гонец в Штормград","Пока я жду ответа от короля, хочу, чтобы ты $gотнес:отнесла; это письмо мировому судье Соломону. $B$B$GСвободен:Свободна;, |3-6($c)!","Отнесите ответ генерала Маркуса Джонатана мировому судье Соломону в Приозерье.","Новости от генерала? Когда прибудет подкрепление?","Благодарю тебя, |3-6($C). В знак признательности Озер и Штормграда прими эти деньги.$b$bХотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны.",nil,nil,nil,nil}
RUQL_QUESTS[122]={"Брюшная чешуя","В обмен на подковы Аргус из Златоземья просит брюшную чешую черных дракончиков. Если ты добудешь мне 6 лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю.$B$BЧерных дракончиков можно отыскать к югу от Приозерья, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю.","Добудьте 6 лоскутов чешуи с брюха черных дракончиков и отнесите их Вернеру Осгуду в Красногорье.","Если я не отдам чешую жадине Аргусу, он пошлет за ней кого-нибудь другого. Ты уже $Gдобыл:добыла; материал?","Спасибо! Теперь я смогу расплатиться с Аргусом...",nil,nil,nil,nil}
RUQL_QUESTS[123]={"Вымогатель","На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\".$B$BСудя по всему, Вымогатель обосновался неподалеку от тыквенного поля Бреквеллов в восточной части Элвиннского леса.$B$BПохоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану, он сейчас на лесопилке Восточной долины.","Отправляйтесь к маршалу Маккри на лесопилку Восточной долины, что в Элвиннском лесу, и отдайте ему расписание Вымогателя.","Что?! Да никто из наших в Элвиннских шахтах уже несколько месяцев не работает!$B$BДай-ка сюда эту бумажку...","Хм... Я слышал об этом \"Вымогателе\", вот только не знаю, на кого он работает. Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну...",nil,nil,nil,nil}
RUQL_QUESTS[124]={"Лай гноллов","Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей...$B$BЕсли ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны.","Убейте 10 громил из стаи Красногорья и 8 мистиков из стаи Красногорья. Вернитесь к Вернеру Осгуду.","Лошади по-прежнему нервничают, а по ночам все еще доносится проклятый волчий вой. Прошу тебя, $N, сделай что-нибудь с этими гноллами!","Благодарю тебя за помощь, $N!",nil,nil,nil,nil}
RUQL_QUESTS[125]={"Утраченные инструменты","Мне не помешала бы помощь, $n. Наш город в осаде, и достать припасы и оборудование все труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили ее снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера.$b$bДостань его, $n, и я щедро вознагражу тебя.","Достаньте ящик с инструментами штейгера Ослоу со дна Озера Безмолвия.","Удалось вытащить инструменты?","Отличная работа, $N! Я уж и не надеялся вновь увидеть свои инструменты.",nil,nil,nil,nil}
RUQL_QUESTS[126]={"Вой в холмах","$n, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.$B$BСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.$B$BСоблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...","Принесите лапу Изувоя Вернеру Осгуду в Приозерье.","Изувой – опасное существо, $N. Если ты еще не $Gготов:готова; сразиться с ним, я тебя понимаю.","И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов.",nil,nil,nil,nil}
RUQL_QUESTS[127]={"Продажа рыбы","Озеро Безмолвия славится пятнистой рыбой-луной. На нее всегда есть спрос... А мой запас подходит к концу!$B$BПринеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты $gсам:сама; не умеешь удить, то... Попытайся отнять рыбу у мурлоков!","Принесите 10 тушек пятнистой рыбы-луны портовому начальнику Барену в Приозерье.","Ну как, где моя рыба-луна?","Иметь с тобой дело – одно удовольствие, дружище!",nil,nil,nil,nil}
RUQL_QUESTS[128]={"Награда за головы орков Черной горы","Мы должны уничтожить клан Черной горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи.$b$bМировой судья Соломон распорядился перебить этих гнусных тварей. Убей 15 воителей из клана Черной горы и возвращайся ко мне.","Убейте 15 воителей из клана Черной горы.","Возвращайся, когда убьешь 15 воителей из клана Черной горы.","Вижу, ты доблестно сражался с кланом Черной Горы, |3-6($C). Ты $Gоказал:оказала; нашему городу неоценимую услугу.",nil,nil,nil,nil}
RUQL_QUESTS[129]={"Бесплатный обед","Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушел на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края.$B$BЕсли ты отнесешь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес.","Отнесите обед стражнику Паркеру. Он патрулирует дорогу, ведущую в Темнолесье.","Дарси прислала мне обед, да? У нее доброе сердце. Что ж... Пора подкрепиться!","Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!",nil,nil,nil,nil}
RUQL_QUESTS[130]={"Визит к травнице","Если ты все равно идешь к Дарси, не отнесешь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города.$B$BТолько когда будешь покупать цветы... не говори травнице Марти, от кого они и кому...","Поговорите с травницей Красногорья Марти Джайнроз.",nil,"Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже $Gнашел:нашла; $Gвозлюбленную:возлюбленного;?$B$BПонимаю, мне не следует совать нос не в свое дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена.",nil,nil,nil,nil}
RUQL_QUESTS[131]={"Доставка нарциссов","Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!","Отнесите Дарси букет нарциссов.","И снова здравствуй, $N. Понравился ли Паркеру обед?","Какая прелесть! Надо поскорее поставить их в воду!$b$bНо... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не $Gсказал:сказала;, для кого они? Иначе не удивлюсь, если она их отравила.$b$b\nНет-нет, ты ни в чем не $Gвиноват:виновата;. Большое спасибо! А вот и твой обед.",nil,nil,nil,nil}
RUQL_QUESTS[132]={"Братство Справедливости","То, о чем я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами.$b$bОтнеси эту записку Камнегриву. В ней разъясняется все, что я знаю на эту тему.","Отнесите записку Вилли Гриану Камнегриву в Западный Край.","Приятно видеть вас снова, $N. Так что там Вилли собирался рассказать?","Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа.",nil,nil,nil,nil}
RUQL_QUESTS[133]={"Чучело вурдалака","Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!..$B$BЯ хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько ребер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы.$B$BПринеси мне ребра, и я дам тебе несколько монет.","Добудьте 7 ребер вурдалаков и принесите их в хижину Аберкромби.","Кажется, я слышу за домом шаги вурдалаков – надо поскорее сделать фигурку! Ты $Gпринес:принесла; мне ребра вурдалаков?","О, спасибо. Это наверняка сработает!",nil,nil,nil,nil}
RUQL_QUESTS[134]={"Нападение огров","Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.$B$BПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.$B$BПрошу тебя, $n, верни мне ящик, без него я как без рук.","Вернуть ящик Аберкромби владельцу.","Ты принес мой ящик? Коли так, пожалуйста... Быстро дай его сюда!","Хвала Нек... то есть ТЕБЕ, $N! Ты более чем заслуживаешь награды.$B$BАга! Как я счастлив! Впереди много радостных ночей!",nil,nil,nil,nil}
RUQL_QUESTS[135]={"Братство Справедливости","Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну. Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе.","Отнесите записку Вилли Матиасу Шоу в Штормград.","Какое у тебя ко мне дело? Я очень занятой человек...","Это дело может оказаться сложнее, чем полагает Камнегрив.",nil,nil,nil,nil}
RUQL_QUESTS[136]={"Спрятанное сокровище капитана Сандерса","Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что мое сокровище теперь может стать твоим, главное – следуй подсказкам.$b$bСначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдешь мой сундучок. Загляни внутрь за следующей подсказкой.","Найдите сундучок капитана Сандерса и поищите в нем следующую подсказку.",nil,"Сундучок медленно, со скрипом, открывается. Кажется, ничего в нем нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!",nil,nil,nil,nil}
RUQL_QUESTS[137]={"<NYI> <TXT> Рекомендация Штормграда","Если у тебя есть рекомендации от одного из наших маршалов, покажи их мне. Взамен я дам тебе пару Львиных перчаток.","Отдайте генералу Маркусу Джонатану в Штормграде рекомендации из Элвиннского леса.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[138]={"Спрятанное сокровище капитана Сандерса","Ключ к поиску сокровища таков: \"Превосходно, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге. Ищи на обочине дороги развалины старого очага. Там найдешь старую бочку, в которой и будет следующий ключ\".","Найдите старую бочку рядом с разрушенным очагом и поищите в ней следующий ключ.",nil,"Отличная работа, $Gохотник:охотница; за сокровищами!",nil,nil,nil,nil}
RUQL_QUESTS[139]={"Спрятанное сокровище капитана Сандерса","Обыскивая бочку, вы обнаруживаете еще один кусок пергамента. На нем написано: \"А теперь от этой бочки поверни к северу. Прямо, как ворон летит, иди, пока не наткнешься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утесах. Осмотри кувшин внимательно – может, и найдешь то, что ищешь\".","Найдите следующую подсказку в пустом кувшине, найденном рядом с ветряной мельницей.",nil,"Ты на пути к главному призу, $Gискатель:искательница; сокровищ!",nil,nil,nil,nil}
RUQL_QUESTS[140]={"Спрятанное сокровище капитана Сандерса","Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандера. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: \"Раз уж ты нашел мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!","Установите местонахождение сундука капитана Сандерса и откройте его.",nil,"Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище.$B$BПоздравляем!",nil,nil,nil,nil}
RUQL_QUESTS[141]={"Братство Справедливости","Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф. Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны. Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошелся король, когда восстановление города было завершено. Это могло бы объяснить пару вещей.$b$bЯ тут расписал все более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!","Передайте документ, написанный Шоу, Гриану Камнегриву в Западный Край.","Пролил ли Мастер Шоу какой-то свет на происходящее?","Эдвин ван Клиф... Мне хорошо известно это имя. Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца. Мне понадобятся дополнительные доказательства, чтобы я поверил в это.",nil,nil,nil,nil}
RUQL_QUESTS[142]={"Братство Справедливости","Нам нужно выяснить местонахождение Убежища Братства Справедливости. $n, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено.","Выследите вестника из Братства Справедливости в Западном Крае и принесите отнятое у него сообщение Гриану Камнегриву.","$N, удалось ли вам найти какую-то информацию? Вы определили местоположение посланника?","Вот явное доказательство того, что ими верховодит ван Клиф. Теперь все, что нам нужно узнать, – это где прячутся бандиты братства.$b$bНам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена. Он пообещал навести нас на убежище бандитов в обмен на жизнь. Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище. Возвращайтесь ко мне, когда выясните местонахождение убежища.",nil,nil,nil,nil}
RUQL_QUESTS[143]={"Гонец в Западный Край","Что-то странное происходит в армии Штормграда, подкрепления все нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном Крае создано народное ополчение.$b$bОтнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов.","Отнесите просьбу о помощи Гриану Камнегриву в Западный Край.","Привет тебе, |3-6($C). Какое дело привело тебя к народному ополчению?","Добрый вестник, ты хорошо $Gпослужил:послужила; своему господину.",nil,nil,nil,nil}
RUQL_QUESTS[144]={"Гонец в Западный Край","Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы.$b$bОтнеси мой ответ в Красногорье, |3-6($c),\n\n и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.","Вернитесь к чиновнику Соломону с ответом Гриана Камнегрива.","Скоро ли ждать прибытия народного ополчения? Добрые ли вести ты несешь от лорда Камнегрива?","Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты ее собственных земель? Впрочем, зря я об этом говорю вслух.$b$bВот, $Gвестник:вестница;. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься.",nil,nil,nil,nil}
RUQL_QUESTS[145]={"Гонец в Темнолесье","И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного Дозора на защиту Приозерья. Надо как можно скорее доставить мое послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги.","Отнесите письмо лорду Чернодреву в Темнолесье.","Похоже, ты $Gприбыл:прибыла; издалека, |3-6($C). Что привело тебя в Темнолесье?","Благодарю за проделанный путь. Вести и верно важные.",nil,nil,nil,nil}
RUQL_QUESTS[146]={"Гонец в Темнолесье","Не знай я мирового судью Соломона лично, решил бы, что он сошел с ума. Послать в Приозерье Ночной Дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной Дозор, то наш город падет, едва лишь Дозор доберется до края леса.$B$BОтнеси мой ответ своему господину в Приозерье.","Вернитесь к мировому судье Соломону с ответом лорда Элло Чернодрева.","Рад снова видеть тебя, $Gпосланник:посланница;. Могу ли я сообщить маршалу, что Ночная стража уже в пути?","Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так?$b$bО, я забыл отблагодарить тебя за услуги, |3-6($C). Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути.",nil,nil,nil,nil}
RUQL_QUESTS[147]={"Охота на человека","Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель...$B$BЗдесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там.","Найдите и убейте \"Вымогателя\", а затем принесите его кольцо маршалу Маккри.","Тебе удалось разыскать Вымогателя? И на кого же он работает?","Так тебе удалось его найти? Отлично, Маркроу, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах!$B$BА это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда. С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках?$B$BНепростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ.",nil,nil,nil,nil}
RUQL_QUESTS[148]={"Припасы из Темнолесья","Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели.$B$BНе $gмог:могла; бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.","Поговорите с мадам Евой.",nil,"А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать еще... Если ты принесешь мне призрачные волосы.",nil,nil,nil,nil}
RUQL_QUESTS[149]={"Прядь призрачных волос","На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.$B$BВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.$B$BБудь $gосторожен:осторожна;, рядом с домом бродит множество темных тварей.","Отнесите Слепой Мэри призрачный гребень.","*Всхлипывает.*$bПожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!$B$BЯ уродина! Уродина! Прошу тебя, отвернись!","Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун.$B$BАх, мне бы в зеркало посмотреться...",nil,nil,nil,nil}
RUQL_QUESTS[150]={"Мурлоки-браконьеры","Мурлоки начинают нас беспокоить. Все больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили все озеро!$B$BУбей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить...","Принесите 8 плавников мурлоков портовому начальнику Барену в Приозерье.","$GПринес:Принесла; плавники? Торопись, надо скорее изгнать мурлоков из нашего озера!","Молодец, $N. Надеюсь, тебе не слишком солоно пришлось.$B$BСтранно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали...",nil,nil,nil,nil}
RUQL_QUESTS[151]={"Бедная старая Савраска","Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я ее покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, $gсэр:леди;, если бы вы могли принести ей несколько горстей овса с окрестных полей.$b$bУверена, что вы найдете овес на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.","Принесите 8 горстей овса Верне Хмуробров.","Старая Савраска уже валится с ног. Не $Gдобыл:добыла; ли ты овса для нее?","Огромное тебе спасибо, $N! Бедная старая Савраска будет просто счастлива!",nil,nil,nil,nil}
RUQL_QUESTS[152]={"Зачистка побережья","Ты, должно быть, $gвидел:видела; все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой...$b$bРазберись с ними – убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков, – и награда будет ждать тебя.","Убейте 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков и вернитесь к капитану Грейсону на Маяк в Западном Крае.","Убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков, – и награда будет ждать тебя.","Хорошая работа, $N. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом.",nil,nil,nil,nil}
RUQL_QUESTS[153]={"Красные кожаные банданы","В Братстве Справедливости идет постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам.$b$bПринесите мне 15 таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение.","Принесите разведчику Галиану на Сторожевой холм 15 красных кожаных бандан.","Принесите мне 15 красных кожаных бандан, и я вам хорошо заплачу.","Хорошая работа, $N. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды.",nil,nil,nil,nil}
RUQL_QUESTS[154]={"Гребень для Евы","НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!","Верните гребень для призрачных волос мадам Еве в Темнолесье.","Чувствую, ты уже $Gвидел:видела; Слепую Мэри. Гребень все еще у тебя?..","Ну, из этого выйдет целая катушка нити из призрачных волос, да еще и останется несколько прядей. Прими эти монеты в уплату за лишние пряди.",nil,nil,nil,nil}
RUQL_QUESTS[155]={"Братство Справедливости","Так Камнегрив считает, что $gтакой слабый:такая слабая:r; |3-6($r) сможет меня защитить? А ведь придется. Возьми-ка с собой пару-тройку друзей.$b$bТы же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить.$b$bДай мне знать, когда ты и друзья, которых ты соберешь, будут готовы идти.","Сопроводите предателя к тайному убежищу Братства Справедливости. Когда он покажет, где прячутся ван Клиф и его люди, вернитесь к Гриану Камнегриву.","Какое у тебя ко мне дело? Я очень занятой человек...","Великолепно, сэр $N! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!",nil,nil,nil,nil}
RUQL_QUESTS[156]={"Сбор цветков гнили","Если ты принесешь мне несколько цветков гнили, я сделаю для тебя сок зомби.$B$BЦветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал!$b$bКладбище Вороньего холма кишмя кишит этими скелетами. Заодно ты и нас от них избавишь. Темнолесье будет тебе весьма признательно.","Соберите 8 цветков гнили и отнесите их хозяину таверны Смиттсу.","Привет. Ну как, $Gпринес:принесла; цветки гнили?","Отлично, ты $Gсумел:сумела; добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов.$B$BНочной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех.",nil,nil,nil,nil}
RUQL_QUESTS[157]={"Доставка ниток","Вот тебе нитки, $n. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.","Принесите нить из призрачных волос в хижину на севере от кладбища Вороньего холма и отдайте ее Аберкромби.","Я должен обвязать нитью из призрачных волос двери и окна, чтобы не пускать в дом чуждых призраков. Ты $Gпринес:принесла; ее?","Великолепно! Она прекрасно подойдет…$b$bВот, дражайший $N, прими это в уплату за благороднейший поступок.",nil,nil,nil,nil}
RUQL_QUESTS[158]={"Сок зомби","Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдется лишняя бутылочка.$B$BТоропись, $n. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнем.","Поговорите с хозяином таверны Смиттсом.",nil,"Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают.",nil,nil,nil,nil}
RUQL_QUESTS[159]={"Доставка сока","А вот и сок зомби...$B$BБудь с ним $Gосторожен:осторожна;. Он такой крепкий, что мертвого поднимет!","Отнесите сок зомби в хижину Аберкромби.","Сок зомби согреет меня долгими холодными ночами. Ты $Gпринес:принесла; его?","Тысяча благодарностей, $N. Твоя глу... то есть твоя доброта согрела сердце старика!$b$bВот, прими это в знак моей благодарности.",nil,nil,nil,nil}
RUQL_QUESTS[160]={"Письмо для мэра","Отнеси это письмо Элло Чернодреву, мэру Темнолесья.$b$bМы с ним старые друзья... и когда он прочтет и узнает, что ты для меня $gсделал:сделала;... уверен, он будет так же счастлив, как и я! Ха-ха-ха!","Отнесите письмо Аберкромби Элло Чернодреву, мэру Темнолесья.","Аберкромби?.. Я не знаю такого человека. Так говоришь, этот Аберкромби написал мне письмо?$B$BЧто ж, давай его сюда...","*Элло рассматривает письмо...*$B$BЧто это за язык? Похоже, какой-то древний... Не могу его прочитать.",nil,nil,nil,nil}
RUQL_QUESTS[161]={"Прямая и черная угроза","Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелегкий и опасный, $N.$b$bПройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться.","Главный инженер Плотиннер хочет, чтобы вы отнесли странно пахнущий порошок Ашлану Камнехмылу, специалисту по взрывчатым веществам в лагере Мо'грош.","Что ты там бубнишь, $Gсынок:дочка;? В ушах звенит, аж жуть. Ух ты, что это ты мне $Gпринес:принесла;?","Да, старина Плотина не зря беспокоится.",nil,nil,nil,nil}
RUQL_QUESTS[162]={"Возвышение силитидов","Прошу тебя, отнеси этот отчет кому-нибудь, сведущему в такого рода вопросах.$b$bЯ слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает.$b$bГоворят, она сейчас в Храме Луны в Дарнасе.","Отнесите отчет о наблюдении за насекомыми Грацине Силе Духа в Дарнас.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[163]={"Вороний Холм","Что-то неладно на Вороньем Холме, $n. Калор клянется, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон.$b$bЕсли тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме.","Выясните, кто поселился на Вороньем Холме.","Ах, $N! Так скоро $Gвернулся:вернулась;? Не сомневаюсь, ты снова $Gбыл:была; на охоте? Не волнуйся, если у тебя были какие-то неудачи, в конечном итоге тебе станет лучше!$B$B... В любом случае, ты не станешь хуже...","Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет... не может быть. Всего лишь безвредный Трясунчик.",nil,nil,nil,nil}
RUQL_QUESTS[164]={"Припасы для Свена","Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса.$b$bУвы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?","Отнесите Свену припасы.","С первого взгляда ты кажешься опытным бойцом, |3-6($C). Хочешь пополнить наши ряды?","Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды.",nil,nil,nil,nil}
RUQL_QUESTS[165]={"Отшельник","Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живет в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?","Навестите старика в хижине рядом с кладбищем Вороньего холма.",nil,"Илана Карвин? Хе-хе, да, разумеется, Карвин.$B$BНет, со мной все в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею. Может, ты окажешь старику пару услуг?",nil,nil,nil,nil}
RUQL_QUESTS[166]={"Братство Справедливости","Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено.","Убейте Эдвина ван Клифа и принесите его голову Гриану Камнегриву.","Как продвигается ваша охота на Эдвина ван Клифа?","$N, вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края. Смерть Эдвина ван Клифа станет началом конца для Братства Справедливости. Надеюсь, недалек тот прекрасный день, когда мир вновь снизойдет на эту честную землю.",nil,nil,nil,nil}
RUQL_QUESTS[167]={"О, брат мой...","Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю.$b$bВдруг тебе повезет больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги исследователей. Если ты не найдешь брата, постарайся найти хотя бы его значок.","Принесите значок Лиги исследователей, принадлежавший Вилдеру Крапивцу, в Штормград.","Нет ли у тебя каких-либо известий о моем брате? Можно ли еще надеяться, ведь столько времени прошло?","Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определенность лучше загадок, даже если она лишает надежды.",nil,nil,nil,nil}
RUQL_QUESTS[168]={"Сбор воспоминаний","Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесет в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдешь их карточки Союза шахтеров, принеси их мне, я отправлю их семьям погибших.","Добудьте 4 карточки Союза шахтеров и верните их Вилдеру Крапивцу в Штормград.","Принеси мне карточки Союза шахтеров, которые принадлежали моим друзьям...","Спасибо тебе, $N. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны.",nil,nil,nil,nil}
RUQL_QUESTS[169]={"Разыскивается: Гат'Илзогг","Розыск! Гат'Илзогг, вождь клана Черной горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. $b$bГат'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат'Илзогга мировому судье Соломону, будет щедро вознагражден.","Убейте Гат'Илзогга и принесите его голову мировому судье Соломону в Приозерье.","Что это, |3-6($c)?","Великолепная работа, $N! Гат'Илзогг вел своих громил в бой, и они убивали ни в чем не повинных людей. Мы отомстили ему. Это первый шаг на пути возвращения крепости королевству Штормграда!",nil,nil,nil,nil}
RUQL_QUESTS[170]={"Новая угроза","Надеюсь, ты $gоказался:оказалась; здесь не случайно, |3-6($c). Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес.$b$bЯ слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замерзшего озера.$b$bТак ведь и это еще не все! Недавно они напали на наш лагерь на западе и разгромили его!$b$bНам и так воинов не хватает, а тут еще эти гады... Послушай, $gприятель:подруга;, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть...","Убейте 6 троггов из племени Каменной Челюсти и 6 сильных троггов из племени Каменной Челюсти.","Живучие маленькие насекомые, не так ли?",nil,nil,nil,nil,nil}
RUQL_QUESTS[171]={"Опекун Альянса","Ты $gбыл:была; очень $gдобр:добра; ко мне, $n. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо.$b$bВот бы всем ребятам в приюте повезло, как мне, – мы сделали столько всего интересного! Как ты думаешь, сможем мы еще раз найти Крэггла Головодерга и купить у него стойку с пластиковыми мечами? Думаю, он так и ходит со своей тележкой поблизости от Торгового квартала. Тогда и остальные ребята в приюте тоже смогут повеселиться!$b$bА после этого я вернусь домой.","Купите стойку с пластиковыми мечами у Крэггла Головодерга, а затем отведите своего подопечного-сироту обратно в приют Штормграда и верните детскую свистульку попечительнице сирот Найтингейл в Соборном квартале Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[172]={"Детская неделя","Ты хочешь помочь сиротам? Да благословят тебя боги! Твоя помощь во время Детской недели будет очень кстати!$b$bВот, возьми эту свистульку. Действовать она будет недолго – до конца Детской недели. Свистни в нее – и появится сирота, за которым ты обещаешь присматривать. Свистни еще раз – ребенок уйдет.$b$bПрошу тебя, $n, пользуйся свистулькой почаще, не забывай своего подопечного! Для детей это так важно...","Воспользуйтесь орочей детской свистулькой. Присматривайте за сиротой в течение Детской недели.",nil,"Заг-заг! Меня зовут Грент. Ты теперь $Gмой:моя; $Gопекун:опекунша;, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться!$B$BА мы теперь будем все делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь все равно как $Gстарший:старшая; $Gбрат:сестра;. Вот здорово!",nil,nil,nil,nil}
RUQL_QUESTS[173]={"Воргены в лесу","На Сумеречный лес наступают силы тьмы, и цель мастера Карвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$b$bТы считаешь, что $gдостоин:достойна; вступить в наши ряды?$b$bКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Карвина. Если ты хочешь показать, на что $gспособен:способна;, то слова тебе не помощники.$b$bВыступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.","Калор из Темнолесья просит вас убить 6 тенеткачей Ночной Погибели.","$N, как успехи на охоте?","Твои успехи впечатляют, $N. Похоже, ты на многое $Gспособен:способна;. Пожалуй, твоим талантам следует найти более достойное применение.$b$bВпрочем, вот что интересно... Воргены появились словно из ниоткуда. Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема.",nil,nil,nil,nil}
RUQL_QUESTS[174]={"Взгляни на звезды","Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звезды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство.$B$BПринеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один.","Принесите Виктору Призм'Антрасу бронзовую трубку.","Тебе удалось отыскать искусного инженера и сделать бронзовую трубку?","Великолепно, $N! Первый шаг мы сделали успешно!",nil,nil,nil,nil}
RUQL_QUESTS[175]={"Взгляни на звезды","Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь ее и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса.","Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.",nil,"Все верно, у меня некогда было зеркальце.",nil,nil,nil,nil}
RUQL_QUESTS[176]={"Разыскивается: \"Дробитель\"","Разыскивается: Дробитель$B$BВ юго-западной части Элвиннского леса рыщет могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось.$B$BАрмия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить ее, необходимо пробраться в леса и убить Дробителя.","Решите \"проблему с Дробителем\" и вернитесь к маршалу Дугхану.","О да, этот Дробитель мне и моим людям немало крови попортил... Ты можешь о нем что-нибудь сообщить?","Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем!$B$BВот твоя награда, $N, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!",nil,nil,nil,nil}
RUQL_QUESTS[177]={"Взгляни на звезды","Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил мое зеркальце. Говорят, что теперь эта тварь живет на Безмятежном кладбище.","Заберите зеркало Слепой Мэри у Невменяемого Вурдалака и отдайте его Виктору в Темнолесье.","Я показал Когу наш прибор для изучения звезд, и он его одобрил. Ты не $Gдобыл:добыла; отражающее устройство?","Шедеврально! Это непременно сработает. Я глубоко признателен!",nil,nil,nil,nil}
RUQL_QUESTS[178]={"Поручение Теокрита","<До вас доносится голос...>$B$BНе пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом.$B$BЯ потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь мое сообщение, значит, заклинание сработало.$B$BПринеси мне эту подвеску, и я щедро вознагражу тебя.","Принесите выцветшую подвеску Темношкуров верховному магу Теокриту в Башню Азоры, что в Элвиннском лесу.","Говоришь, ты $Gслышал:слышала; мой голос из подвески? Хм-м-м... Дай-ка ее мне, надо ее как следует изучить.","Благодарю тебя, $N. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало. Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них.$B$BХочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески.$B$BК сожалению, до этого еще очень далеко.",nil,nil,nil,nil}
RUQL_QUESTS[179]={"Дворфийские экипировщики","Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя все время мерзнут руки. Ну, угадал?$b$bЯ скажу, что тебе нужно: пара хороших теплых перчаток. Ну да, душа у меня добрая, так что замерзнуть я тебе не дам. Только вот есть одно условие.$b$bПринеси мне волчьего мяса – и мы, считай, в расчете. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мерзли. Ну, что скажешь?","Принесите Стену Крепкоруку 8 кусков жесткого волчьего мяса.","Что, потрепали тебя волки? Да уж, когти и клыки – это тебе не шуточки!","О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, $N, свою часть сделки я выполню честно. Вот, посмотри, что из этого тебе подойдет.",nil,nil,nil,nil}
RUQL_QUESTS[180]={"Разыскивается: лейтенант Фангор","Разыскивается: лейтенант Фангор$b$bГлава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведет приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону.","Убейте лейтенанта Фангора и принесите его лапу мировому судье Соломону в Приозерье.","Какие новости ты несешь Суду?","Значит, злобный лейтенант Фангор мертв? Прекрасно. Ты удивительно $Gхрабрый:храбрая; |3-6($C). Городской совет Приозерья благодарит тебя за помощь.",nil,nil,nil,nil}
RUQL_QUESTS[181]={"Взгляни на звезды","Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!","Отыщите Ззарк'Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье.","Тебе удалось уговорить Ззарк'Вула одолжить нам свой монокль для эксперимента?","Наконец-то! Устройство для изучения звезд готово! Спасибо тебе, $N. Я могу продолжить исследования...",nil,nil,nil,nil}
RUQL_QUESTS[182]={"Угроза атаки троллей","Тролли проявляют какую-то небывалую активность. Мы и раньше видели, что они иногда собирают боевые отряды, но чтобы такое...$b$bОсобенно меня беспокоит защита Старой Наковальни. Мне совсем не хочется, чтобы тролли атаковали Старую Наковальню в то время, как все наши силы брошены на троггов. Прореди немного их ряды. Пусть знают, что мы не беззащитны.","Убейте 10 троллей-подростков из племени Мерзлогривов.","Насколько я знаю, эти тролли происходят из клана Снежной Гривы. Боюсь, о них я не знаю больше ничего, что могло бы тебе пригодиться, $N.","Проклятые тролли! Да не озарит их Извечный Свет!$B$B*Шумно дышит; немного успокаивается.*$B$BЭти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь...",nil,nil,nil,nil}
RUQL_QUESTS[183]={"Охотник на вепрей","Нет ничего лучше охоты на диких вепрей, верно?$b$bПравда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно...$b$bКороче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов.","Убейте 12 малых скальных вепрей по просьбе Талина Остроглаза.","Как идет охота?",nil,nil,nil,nil,nil}
RUQL_QUESTS[184]={"Документ Хмуроброва","Это закладная на ферму в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной. На обороте документа торопливо нацарапаны слова:$B$B\"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится.$B$BС Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\"$B$BНаверное, Хмуробровы были бы рады получить этот документ назад...","Доставьте документ Хмуроброва во Владение Янсена в Западном Крае.","У тебя бумага на мою ферму? Вот это да! Вот это здорово! Несколько дней назад ее украли какие-то мерзавцы... Я думал, назад мне ее уже не получить.$b$bПожалуйста, отдай мне эту бумагу. Конечно, мы сейчас уезжаем из Западного Края и вернемся не скоро, но наступят времена, когда она нам очень пригодится...","Ты представить не можешь, $N, как мы тебе благодарны! Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землей.$b$bКонечно, многого я предложить не могу, но возьми хотя бы вот это...",nil,nil,nil,nil}
RUQL_QUESTS[185]={"Охота на тигров","Когда я была юной девушкой, мой отец обучил меня искусству охоты на тигров.$B$BМолодых тигров куда легче выследить и убить. Тигрят полно вокруг нашего лагеря.$B$BТак что проверь, как ты умеешь брать след, и попробуй выследить несколько зверей. Начинай охотиться к югу от лагеря.","Выследите 10 молодых тигров Тернистой долины.","Пока ты не научишься справляться с молодыми тиграми, о дальнейших уроках и речи быть не может.","Неплохо, $N. Пора тебе двигаться дальше.",nil,nil,nil,nil}
RUQL_QUESTS[186]={"Охота на тигров","Одно дело тигрята, совсем другое – взрослые хищники. Но самым сложным испытанием станет охота на взрослых тигров Тернистой долины.$b$bОбычно взрослые тигры бродят к югу от Лагеря Курцена восточнее реки.","Убейте 10 тигров Тернистой долины.","Если ты жаждешь великих свершений, докажи сначала, что $Gспособен:способна;. Убей 10 тигров Тернистой долины и возвращайся.","Впечатляюще, |3-6($C). Ты делаешь успехи.",nil,nil,nil,nil}
RUQL_QUESTS[187]={"Тигриная отвага","Старые тигры Тернистой долины – самые матерые. Немало |3-8($c) из числа |3-8($r) погибло от их зубов и острых как бритвы когтей.$B$BЕсли тебе удастся одолеть этих тварей, такая новость, несомненно, порадует Аджек. Большая популяция матерых тигров обитает к югу отсюда, вблизи Разлома, на границе с мысом Тернистой долины.","Убейте 5 старых тигров Тернистой долины.","Прежде чем перейти к последнему заданию и претендовать на звание $Gвеликого:великой; $Gохотника:охотницы;, убей 10 старых тигров Тернистой долины.","Очень, очень неплохо. Думаю, ты почти $Gготов:готова;.",nil,nil,nil,nil}
RUQL_QUESTS[188]={"Охота на тигров","В легендах говорится о хитрой тигрице... настолько могучей, что силой она превосходила даже взрослых самцов. Охотники из экспедиции Эрнестуэя пытались ее выследить, но безуспешно. Многие из них были растерзаны ее могучими когтями. Останки несчастных еще можно найти на горных склонах к северу от Гром'гола.$b$bЭту тигрицу зовут Син'Далл.$B$BТы сделаешь то, что $gни одному:ни одной:r; |3-2($r) раньше не удавалось: выследи, убей зверя и принеси лапу Син'Далл.","Убейте Син'Далл и вернитесь с ее лапой.","Как идет охота на Син'Далл?","Впечатляюще, должна сказать! Ты $Gвеликий:великая; $GОхотник:Охотница; на тигров, $N!",nil,nil,nil,nil}
RUQL_QUESTS[189]={"Уши троллей Кровавого Скальпа","Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции все растет и растет! Как я объясню это барону Ревилгазу?$B$BНужно действовать решительно... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя... $n зовут, правда? Ты ведь мне поможешь? А уж я заплачу!$B$BПредлагаю сделку... ты принесешь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег.","Добудьте 15 ушей троллей из племени Кровавого Скальпа и принесите их Кебоку в Пиратскую Бухту.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[190]={"Охота на пантер","Если хочешь работать вместе со спецами, которыми руководит Хеминг Эрнестуэй-младший, придется тебе доказать, что ты умеешь охотиться на пантер. Начни с самого простого – молодых пантер. По мере роста охотничьего мастерства тебе, несомненно, придется столкнуться с более сложными и опасными задачами.$B$BДля начала отправляйся на восток. Когда овладеешь искусством охоты на пантер, возвращайся.","Убейте 10 молодых пантер.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[191]={"По следу пантеры","С самыми молодыми пантерами справиться легко. Взрослые, как правило, сильнее и быстрее, так что их одолеть труднее. Они будут твоей следующей целью.$b$bСледы взрослых пантер ведут на запад.","Убейте на охоте 10 пантер.","Иди, убей 10 пантер! Покажи, на что $Gспособен:способна;.","Великолепно, $N!",nil,nil,nil,nil}
RUQL_QUESTS[192]={"Охота на пантер","А теперь – самое трудное. Чем пантеры взрослее, тем хитрее. Они буквально сливаются с окружающей средой и их нелегко обнаружить. Этих хитрющих зверюг называют \"тенебрюхими\" за способность внезапно появляться из темноты... и набрасываться на добычу. А зубки у них о-го-го, можешь не сомневаться!$B$BЕсли хочешь, чтобы тебя признали $gнастоящим охотником:настоящей охотницей; на пантер, тебе нужно убить тенебрюхих пантер. А по-другому – никак. Эти животные встречаются на юго-востоке, за рекой.","Убейте 5 тенебрюхих пантер.","Что ты тут делаешь, $N! Тебе бы ползать по кустам, пытаясь убить 10 Тенебрюхих пантер.","Молодец, $N!",nil,nil,nil,nil}
RUQL_QUESTS[193]={"Охота на пантер","Тебе почти удалось доказать, что ты $gвеликий охотник:великая охотница; на пантер. Множество песен сложено о могучей пантере по кличке Баг'тира, живущей в джунглях. Хватит у тебя сноровки с ней справиться?$B$BЧтобы доказать свое мастерство, принеси клык Баг'тиры Эрлджедину.","Добудьте клык Баг'тиры.","Баг'тира – хитрый зверь. Как идет охота?","Итак, великая Баг'тира мертва! Браво, $N. Ты и правда $Gмогучий:могучая; |3-6($C)!",nil,nil,nil,nil}
RUQL_QUESTS[194]={"Охота на ящеров","Значит, ты считаешь себя $gпревосходным охотником:превосходной охотницей;? Проверим. Ступай в джунгли и подстрели 10 ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью.$B$BИ нет, я не скажу, где их искать! Поиск добычи – это, считай, половина испытания.$b$bЛадно, так и быть... Иди на запад.","Убейте 10 ящеров Тернистой долины.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[195]={"Охота на ящеров","Пришло время усложнить задачу. Пожалуй, отправиться в джунгли и разобраться с десятком ящеров-кнутохвостов – подходящее задание. Эти твари будут посильнее, чем те, с которыми тебе уже доводилось встречаться..$b$bЯщеры-кнутохвосты обитают, главным образом, к юго-востоку от нас, вблизи Руин Кал'аи.","Убейте 10 ящеров-кнутохвостов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[196]={"Большая охота","Там в лесах за рекой к югу отсюда водятся особенно хитрые и осторожные ящеры, которых местные называют \"тропическими ловцами\". Их нелегко обнаружить и весьма непросто убить.$b$bЕсли успешно поохотишься на этих тропических ловцов, тебе будет чем похваляться, сидя у костерка...","Отправляйтесь на охоту и убейте 10 тропических ловцов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[197]={"Охота на ящеров","Прежде чем вернуться в лагерь экспедиции Эрнестуэя, тебе придется выполнить невыполнимое – убить ящера, которого не сумел одолеть ни один охотник. Эту тварь зовут Тетис. Данный зверь сеет ужас на юго-восточной окраине Северной Тернистой долины.$B$BПринеся коготь Тетис тому дворфу-охотнику, ты докажешь свое незаурядное дарование к охоте, |3-6($r).","Убейте Тетис.","Как идет охота на Тетис? Я так понимаю, ее следы вели к нашему лагерю?","Великий $N, убийца ящеров!$b$bНеплохо звучит, а?",nil,nil,nil,nil}
RUQL_QUESTS[198]={"Припасы для рядового Торсена","Хммм. У меня и правда есть для тебя дело. Лейтенант Дорен и его последователи там, на севере, регулярно получают от нас поставки еды и оборудования.$B$BПришло время доставить очередную партию, а, учитывая нападения троллей, никто не хочет за это браться. Лагерь Дорена располагается на северо-западе от дороги у входа в Тернистую долину из Сумеречного леса. Отнеси эту посылку рядовому Торсену, а если его нет в лагере, значит, он дежурит на юге от него. Он займется этими припасами.$B$BУчти, если ты провалишь задание, придется тебе возместить мои затраты.","Доставьте различные припасы гоблинов рядовому Торсену.","Да? Что тебе нужно? А, припасы гоблинов. Странно, что их $Gдоставил:доставила; |3-6($c), обычно они сами этим занимаются. Не важно... Ты ведь их не $Gкасался:касалась;? Славно, славно... Мы бы не хотели, чтобы с нашими минами что-нибудь случилось, о нет.","Эти мины помогут нам защититься от этого зверя, Курцена, и его людей. Спасибо за доставку. Если тебе нужна работа, может быть, я смогу помочь тебе. И тебе не придется иметь дело с гоблинами, а?",nil,nil,nil,nil}
RUQL_QUESTS[199]={"Прямая и черная угроза","Вы берете образец странно пахнущего порошка.","Вернитесь к главному инженеру Плотиннеру и покажите ему найденную улику.","Ну как, нашел улики?","Это тревожная находка, мягко говоря!",nil,nil,nil,nil}
RUQL_QUESTS[200]={"Букмекер Ирод","Если Курцену известна тайна Торсена, значит, в наши ряды затесался шпион. Необходимо выяснить, откуда просочилась информация!$B$BСвязным Торсена в лагере Курцена был букмекер Ирод. Ирод работает снабженцем у Курцена, и знает все о его лагере. Если удастся добыть его записи, быть может, мы узнаем, как накрыли Торсена.$B$BКогда мы служили в войсках Курцена, кабинет букмекера располагался на верхнем этаже единственного двухэтажного дома в лагере. Скорее всего, его записи по-прежнему там.","Найдите записи букмекера Ирода.",nil,"Вы находите записи букмекера Герода.$B$BСреди них: список поставок в лагерь, запросы от полковника Курцена и различные письма.",nil,nil,nil,nil}
RUQL_QUESTS[201]={"Поиск лагеря","Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой Компании возле озера Назферити. Я бы не придал этому значения, но говорят, будто один из тамошних охотников – сам Хеминг Эрнестуэй-младший. Мне не верится, но у него настолько высокие связи, если ты понимаешь о чем я, что лучше заранее обезопасить себя.$B$BПочему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?","Найдите лагерь охотников и сообщите о его местонахождении Кразеку из Пиратской Бухты.","Ну что? Тебе удалось найти лагерь?","Хмм, значит у меня были точные сведения, как обычно. Любопытно. Кажется, они не представляют для нас опасности, но, быть может, им нужны наши превосходные товары. Хммм...",nil,nil,nil,nil}
RUQL_QUESTS[202]={"Полковник Курцен","И снова ты $gпоказал:показала; нам, на что $gспособен:способна;. Кажется, талантов у тебя не меньше, чем у самого Курцена! Это может спасти нас, горстку повстанцев... если ты сможешь выступить против Курцена и одержать над ним верх!$B$BОн управляет своими людьми из глубин Схрона. Ступай в эту пещеру, пробейся сквозь ряды ее защитников, и одолей Курцена и его ближайших приспешников.$B$BПрощай, $n. Ты – наша последняя надежда.","Убейте 6 гвардейцев и 4 заместителей Курцена и принесите голову Курцена лейтенанту Дорену в Лагерь повстанцев.","Смею ли я надеяться, что Курцен и его защитники мертвы, $N?","Я не смел верить вестям, но ты несешь нам доказательство того, что... Курцен и его главные сторонники повержены. Ты спас нас всех!$B$BДжунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом. Теперь, когда его нет, мы можем вздохнуть спокойнее.",nil,nil,nil,nil}
RUQL_QUESTS[203]={"Второе восстание","Мы решительно проигрываем полковнику Курцену. Он не только блестящий тактик – его войска превосходят нас в численности в десять раз! Чтобы выжить, нам придется прибегнуть к его же подлой тактике.$B$BПроберись в лагерь на востоке и убей как можно больше его бойцов. И скройся до прибытия подкрепления.","Убейте 15 партизан Курцена.$B$BВернитесь к сержанту Йохве в Лагерь повстанцев.","Надеюсь, охота оказалась успешной, $N. Нам не продержаться без твоей помощи.","Отлично. Потеря опытных бойцов вынудит его ослабит натиск на наш лагерь.$b$bА ты не боишься быть на нашей стороне, зная, какие силы выступают против нас??",nil,nil,nil,nil}
RUQL_QUESTS[204]={"Дурное лекарство","Чтобы получить шанс выстоять против Курцена, нам необходимо лишить его лекарей. Он собрал немало целителей, которые лечат его войска зельями из джунглей и травят наших бойцов экстрактами ядовитого папоротника.$B$BНам и самим нужны эти составы. Обыщи поселок Курцена – лекарства находятся у его целителей и партизанов, а экстракты скорее всего хранятся в одном из ящиков с припасами.","Принесите сержанту Йохве из Лагеря Повстанцев 7 порций зелья из джунглей и 1 порцию экстракта ядовитого папоротника.","Я жду – не дождусь зелий и экстракта, $N.","Молодец, $N. Эти лекарства помогут нам выжить и сохранить боеспособность. А при помощи экстракта мы создадим собственные снадобья.",nil,nil,nil,nil}
RUQL_QUESTS[205]={"Тролльское колдовство","Пока я изучаю принесенные тобой прорисовки, собери для меня принадлежности злой магии троллей. Тебе придется проникнуть в земли племени Дробителей Черепов, второго племени на далеком юге, и добыть фетиши у их знахарей и мистиков.","Принесите 4 фетиша троллей из племени Дробителей Черепов брату Нимезу в Лагерь Повстанцев.","Ты принес фетиши, $N? Должно быть, именно в них заключается секрет падения Курцена... Мне нужно это узнать!","Спасибо. Я изучу эти фетиши и пойму, они ли причина того, что Курцен обратился ко злу.",nil,nil,nil,nil}
RUQL_QUESTS[206]={"Май'Зот","Хотя Курцен и мертв, зло, соблазнившее его, живет! Вот что мне удалось выяснить: огрский маг – Май'Зот – живет в огрском кургане в восточных горах Тернистой долины. Говорят, что он пользуется магией, овладевающей разумом, и я не сомневаюсь, что Май'Зот виноват в падении Курцена.$B$BПока он жив, зло будет расползаться, и может даже появиться второй Курцен.$B$BУбей его и принеси мне его Око разума, артефакт, позволяющий ему творить темные дела.","Принесите Око разума брату Нимезу в Лагерь Повстанцев.","Да пребудет с тобой мое благословение. Сила Май'Зота сравнима лишь с чернотой его души.","Ага! Тебе удалось убить его! На стороне добра действуют великие силы, $N! Да не ослабеет твоя рука!$B$BЯ исследую Око Разума и попытаюсь придумать, как пользоваться им во благо. Если это невозможно... его следует уничтожить.",nil,nil,nil,nil}
RUQL_QUESTS[207]={"Тайна Курцена","Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного! Должно быть, он находится под воздействием магии троллей. Надо изучить древние легенды, чтобы убедиться в этом.$B$BВ руинах тролльских городов в Тернистой долине спрятаны 4 таблички. Мне необходимо их добыть и прочесть! Перерисуй с них все отметки и принеси рисунки мне.$B$BПервая табличка находится в руинах Бал'лал, вторая – на Коварном рифе, а третья и четвертая – в руинах Зул'Кунды.","Найдите 4 таблички, перерисуйте их и принесите их брату Нимезу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[208]={"Охотник на крупную дичь","$n, ты $gдостоин:достойна; занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием.$B$BТебе удалось убить свирепую Син'Далл, неуловимую Баг'тиру и коварную Тетис. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра, обитающего к югу отсюда. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты.","Добудьте голову короля Бангалаша, огромного белого тигра.","Вижу, ты $Gвернулся:вернулась;. Мне не раз приходилось заползать в лагерь и зализывать раны после столкновения с королем Бангалашем. Побудь здесь.","Отлично сработано! Здорово! Поздравляю, $N, ты преуспел там, где другие потерпели поражение.$b$bВидеть тебя в рядах нашего охотничьего отряда – это честь для меня. Отныне никто не усомнится в твоем искусстве $Gохотника:охотницы; и следопыта.$b$b\nУра тебе! Ура!",nil,nil,nil,nil}
RUQL_QUESTS[209]={"Клыки троллей","Убивать тигров и добывать их клыки на экспорт в Южные моря – трудно и дорого. К счастью, мы придумали способ обрабатывать простые рогоподобные предметы и изготавливать неотличимые подделки.$B$BЛучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов.$B$BШ-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно? Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!","Добудьте 18 клыков троллей из племени Дробителей Черепов и принесите их Кебоку в Пиратскую бухту.","Сильные, заразы, а? Ну, как успехи? Не хочу показаться нетерпеливым, но это мне покою не дает. Так как?","А, хорошо, хорошо! Хотя ты $Gмог:могла; бы получше счистить... Ну, неважно, неважно что. Спасибо, $N, благодаря тебе у нас возрастет производительность и доходы! Хорошо, хорошо, а теперь перейдем к следующему делу...",nil,nil,nil,nil}
RUQL_QUESTS[210]={"Горшок Кразека","Готовка по большей части лежит на мне. И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской Бухте. Это чудо какое-то! Он сэкономил мне много часов... Пока не сломался!$B$BМожет, ты отнесешь его назад к продавцу, в ремонт? Продавца зовут Кразек.","Отнесите разбитый горшок Кразека гоблину Кразеку.","Здравствуй! Ты мне что-то $Gпринес:принесла;?","А, вижу, разбитый горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой…$B$BАга! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу!$B$BМогу ли я это починить? Разумеется!$B$BНо не за бесплатно. Бесплатный бывает только сыр в мышеловке...",nil,nil,nil,nil}
RUQL_QUESTS[211]={"Увы тебе, Андорал","Увы, пришло время напасть на Андорал и изгнать оттуда лича!$b$bЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.$b$bУбей Аража и принеси мне его кристалл-талисман!","Принесите осколок оберега Аража командиру Ашламу Неутомимому в Лагерь Промозглого Ветра в Западных Чумных землях.","Тебе было дано задание, $N. Ты $Gпринес:принесла; мне кристалл лича в доказательство его выполнения?","Свершилось! Араж... этот лич наконец-то пал!$B$BСегодня ты $Gоказал:оказала; огромную услугу Альянсу. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в знак нашей благодарности. Пусть все знают, что благодаря тебе Альянс одержал победу!",nil,nil,nil,nil}
RUQL_QUESTS[212]={"Холодный обед","Одно из моих коронных блюд – мороженый василиск под соусом винегрет из лайма. Проблема лишь в том, что... Это мясо не подлежит хранению, а ведь я должен приготовить это блюдо сегодня вечером – на день рождения одного благородного господина! Если сможете, принесите мне охлажденный окорок только что убитого ледоглазого василиска, а я организую специально для вас царскую трапезу!$b$bЛедоглазые василиски обитают в дюнах на северо-западе Тернистой долины, так что путь вам предстоит неблизкий. И не задерживайтесь по дороге!","Убейте ледоглазого василиска и принесите его охлажденный окорок Ангусу Штерну в \"Печальный отшельник\".","$N! У вас есть окорок? Я должен приготовить его в ближайший час, либо банкет будет сорван.","О, вот это окорочок! Большое, просто огромное спасибо!$B$BА теперь попрошу меня простить, мне нужно быстренько нарубить мясо, замариновать его и сервировать для банкета.",nil,nil,nil,nil}
RUQL_QUESTS[213]={"Недружественное поглощение","Он слишком далеко зашел! Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата!$B$BРевилгаз заявил, что не потерпит такого, и велел любым способом решить проблему.$B$BЛюбым способом? Я выбираю кражу. Геологов Торговой Компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике. Принеси мне образцы этих камней, и меня не волнует, что тебе придется сделать с геологами для выполнения задания.","Добудьте 8 упавших кристаллов и принесите их Кебоку в Пиратскую Бухту.","Мне нужны эти камни, $N. Любой ценой! Подробности мне не нужны, только результат, ни больше, ни меньше.","Любопытно. Огранка кристаллов говорит только о том, что они собираются пользоваться ими в качестве горючего или катализатора. Большего сказать я не могу. Образцы необходимо показать старшему химику Хихиканту.",nil,nil,nil,nil}
RUQL_QUESTS[214]={"Красные шелковые банданы","Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства.$b$bЯ рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справитесь с заданием, принесите мне 10 красных шелковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи, $n.","Принесите 10 красных шелковых бандан разведчице Риэле к башне на Сторожевом холме.","Избавили ли вы нашу землю от бандитов из Братства Справедливости? Если да, предъявите в качестве доказательства 10 красных шелковых бандан.","Отличная работа $N! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернем эту землю ее народу.",nil,nil,nil,nil}
RUQL_QUESTS[215]={"Тайны джунглей","Спасибо, что $gспас:спасла; меня, $n. Понимаю, как это выглядит... но позволь мне объяснить.$B$BЛейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты $gвидел:видела;, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это – мой шанс... Еще раз спасибо за спасение.$B$BЭто была тайная миссия, никому о ней не говори. Но лейтенант Дорен может все объяснить.","Поговорите с лейтенантом Дореном в Лагере повстанцев.",nil,"Да, Торсен сказал тебе правду. Только помалкивай об этом. Одно время мы, повстанцы, были слепо преданы полковнику Курцену. Но сейчас он перешел на сторону зла, и наша верность обратилась в ненависть. Если кто-нибудь узнает, что рядовой Торсен имел дело с людьми Курцена, однажды утром мы можем найти его с перерезанным горлом.$B$BНасколько мне известно, о задании Торсена знала только сержант Йохва и я. И кто-то еще. Предатель.",nil,nil,nil,nil}
RUQL_QUESTS[216]={"Между молотом и Колючим Мехом","Эти фурболги Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на западе, преграждает нам путь к заставе Расщепленного Древа. Это на дороге, что идет в обход деревни Астранаар. Если мы не будем ее контролировать, Альянс получит дополнительный путь для вторжения.$B$B$n, мы должны заткнуть эту дыру!$B$BИди в деревню Колючего Меха и перебей фурболгов. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!","Каранг Амаккар из дозора Адского Крика поручил вам убить 15 фурболгов из племени Колючего Меха в деревне Колючего Меха.","Если будет расчищен путь между нашими базами, то шансы захватить весь Ясеневый лес резко возрастают.","Отлично, |3-6($C), отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что еще одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдет полным ходом!$b$bТы $Gзаслужил:заслужила; свою награду, герой! Честь и слава тебе!",nil,nil,nil,nil}
RUQL_QUESTS[217]={"Защита королевских земель","$N, наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привел к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят.$B$BЕсли ты $Gуверен:уверена; в своих силах, $N, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю.","Убейте предводителя троггов Громага и его охранников, Скрежетуна и Буяна. Сообщите об этом капитану Ругельфассу, ожидающему вас в южной сторожевой башне.","Громаг и его охранники, Скрежетун и Буян, все еще живы. Задание не выполнено, покуда все трое живы. Все дворфы рассчитывают на тебя, $N.","Превосходно, $N! Ты $Gвернул:вернула; надежду Лок Модану. Громаг мертв, и у нас появилась надежда изгнать троггов из наших земель.",nil,nil,nil,nil}
RUQL_QUESTS[218]={"Лед и огонь","Сорен правильно сделал, что послал тебя сюда. Эти сведения нам пригодятся.$B$BПравда, дело в том, что это сильно прибавляет нам работы. Тролли, хоть они сейчас и пребывают в полнейшем замешательстве, все равно жаждут выгнать дворфов из Холодной долины. И я уж точно не позволю какому-то огненному демону превратить нашу снежную долину в горное озеро.$B$BВожак троллей, его прислужники и огненная тварь должны быть в пещере к юго-востоку отсюда. Разберись с ними со всеми.","Убейте Грик'нира Холодного, 10 слуг Грик'нира и своенравного элементаля огня.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[219]={"Пропавший без вести","Наконец-то, сторонники Альянса!$b$bПомогите... Пожалуйста...$b$bПоследнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен.$b$bМне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда...","Проводите капрала Кишана до Красногорья.","Да?","Ты отлично послужил Королевству, |3-6($C). Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Черной Горы. Подобная храбрость заслуживает великой награды.",nil,nil,nil,nil}
RUQL_QUESTS[220]={"Зов Воды","Прежде чем дать тебе в награду следующий тотем, Ислен поручит тебе еще одно задание. Для этого понадобится фиал с водой, который я дал тебе.$B$BСтупай, поговори с ней. Мы еще встретимся.","Отнесите фиал с чистейшей водой Ислене Заклинательнице Воды к Лестнице Прилива, что в Степях.","Еще раз здравствуй, $N. Ты хорошо выглядишь.$B$BЧто привело тебя ко мне так скоро?","А, фиал с водой, созданной и благословленной Брин и добытой тобой, ни больше ни меньше.$B$BЖидкость в этом фиале необходима для создания сапты, но годится и для других целей.$B$BПри помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода. Что же до оставшихся капель... о них я расскажу тебе потом.$B$BНе боишься долгого пути, Ахахаха?",nil,nil,nil,nil}
RUQL_QUESTS[221]={"Воргены в лесу","Может, ты $gзаметил:заметила; крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы.$b$bСтранствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться.$b$bБудь $gосторожен:осторожна;.","Убейте 12 вестников Тьмы из стаи Ночной Погибели.","Уже $Gвернулся:вернулась;, $N? Надеюсь, ты не собираешься отказываться от задания?","Ты достойно $Gвыступил:выступила; против вестников Тьмы, $N. Но, похоже, ряды их нескончаемы. На место убитых становятся все новые и новые воргены.$b$bЧто за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город...$b$b\nЯ возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберется с этой проблемой.",nil,nil,nil,nil}
RUQL_QUESTS[222]={"Воргены в лесу","Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса.$b$bСамыми опасными из всех оказались Ярые Клыки и нечистые воргены. Они живут рядом с пещерами и в руднике на юге.$b$bЗарево их костров видно издалека.","Калор просит вас убить 8 Ярых Клыков из стаи Ночной Погибели и 8 нечистых воргенов из стаи Ночной Погибели.","Страшные звери, не так ли? Но не бойся, $N, те, кто стоит за Свет, никогда не упадут!","Честно говоря, $N, я не верил, что ты справишься с этой задачей, но ты воистину $Gмогучий:могучая; |3-6($C). Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо.",nil,nil,nil,nil}
RUQL_QUESTS[223]={"Воргены в лесу","Вот, $n. Отнеси это письмо мастеру Карвину.$b$b*Он отдает вам поблекший пергамент.*$b$bЕсли к нам потянутся такие, как ты, в отряде будет больше людей, чем в Ночном Дозоре! Быть может, тогда мы завершим работу, которую сейчас делаем с большим трудом.","Отнесите записку Калора Джонатану Карвину.","Да, что тебе нужно? Быстрее, у меня полно неотложных дел.","Прости за холодный прием, $N, ты ведь понимаешь, что я очень занятой человек. Вижу, ты $Gпроизвел:произвела; впечатление на Калора. Уверяю тебя, это нелегко. Так или иначе, он рекомендует принять тебя в наши ряды.$b$bВокруг полно ненадежных людей, а нам нужна помощь тех, на кого можно положиться. Мы бьемся против демонов, нежити и их пособников. Не теряй бдительности, осторожности и не доверяй никому, кто не хочет нам помочь.$b$bДа озарит тебя Свет!",nil,nil,nil,nil}
RUQL_QUESTS[224]={"Защита королевских земель","Мы должны защитить озеро Лок, $n! Множество королевских солдат проливает кровь в далеких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов!$b$bНам нужна твоя помощь, $gотважный искатель приключений:отважная искательница приключений;. Ступай и устрани нависшую над нами угрозу. Убей 6 троггов из племени Камнедробов и 6 разведчиков из племени Камнедробов и возвращайся.","Горный пехотинец Кремневик из Телсамара просит вас убить 6 троггов из племени Камнедробов и 6 разведчиков из племени Камнедробов.","Лок Модан в осаде, $N! Все сторонники Альянса, способные держать оружие, должны нам помочь. Ты уже $Gубил:убила; 10 троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов?","Молодчина, $N! Ты $Gпроявил:проявила; немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно $Gпослужил:послужила; королю Магни.$b$bЕсли тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне.",nil,nil,nil,nil}
RUQL_QUESTS[225]={"Заброшенная могила","Надпись на древнем могильном камне гласит:$B$BМОРГАН ЛАДИМОР$b$b*При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*","Поговорите с Широй Фон-Инди в Темнолесье.",nil,"Морган Ладимор?$b$bА-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушел на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо.$b$bПодожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я...",nil,nil,nil,nil}
RUQL_QUESTS[226]={"Волки идут по пятам","Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант. Мы здесь совсем одни, приходится самим добывать себе еду. Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязываются лютые волки. Что и говорить, жить здесь опасно!$B$BНо если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки.","Убейте 12 голодных лютых волков и 8 бешеных лютых волков. Вернитесь к Ларсу в лагерь Свена на западной границе Сумеречного леса.","Охота еще не закончена?..","О, хорошо. Ты здорово $Gпроредил:проредила; волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном.$B$BВот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию.",nil,nil,nil,nil}
RUQL_QUESTS[227]={"Морган Ладимор","*Он роется на полках и вытаскивает книгу в кожаном переплете.*$b$bЕсли хочешь узнать побольше, спроси Алтею, она занималась... проблемами... возникшими с ним в последнее время.","Поговорите с командиром Алтеей Чернодрев в Темнолесье.",nil,"Морган Ладимор? Никогда о нем не слышала...$b$bА, ты о Мор'Ладиме! Ты не знаешь его историю?$b$bЧто ж, я объясню тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже $Gслышал:слышала;. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей.$b$b*Она смеривает вас взглядом.*$b$bКажется, ты $Gсмог:смогла; бы помочь ему упокоиться с миром.",nil,nil,nil,nil}
RUQL_QUESTS[228]={"Мор'Ладим","Разведчики сообщают, что Мор'Ладим бродит по кладбищу. Мы похоронили его за домом на холме, знаешь, где это?$b$bБольше я тебе ничем помочь не могу... Разве что пожелать удачи.","Убейте Мор'Ладима и отнесите его череп командиру Альтее Чернодрев в Темнолесье.","Я не буду винить тебя, если тебе не удастся справиться с ним, $N. Мор'Ладим отнял жизни у сильнейших из наших воинов.","Ты $Gубил:убила; его? Это великий подвиг, $N! Прими благодарность от имени народа Темнолесья и Ночного дозора.$B$BАх, да... Осталось еще одно дело...",nil,nil,nil,nil}
RUQL_QUESTS[229]={"Выжившая дочь","Надо было предупредить тебя раньше...$b$bКак бы тебе сказать...$b$bМорган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.","Поговорите с дозорным Сарой Ладимор в Темнолесье.",nil,"Да? Мой отец…$B$B*Она опускает глаза.*$BBЖаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как...",nil,nil,nil,nil}
RUQL_QUESTS[230]={"Лагерь Свена","Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью.$B$BЗаглавие не указано, зато в ней содержатся сведения, необходимые Свену.","Принесите Свену книгу, найденную на ферме Свена.","Что ты $Gнашел:нашла;?! Пожалуйста, дай посмотреть...","*Свен прочитывает несколько страниц и захлопывает книгу.*$BBЭтот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!",nil,nil,nil,nil}
RUQL_QUESTS[231]={"Дочерняя любовь","Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймет, что я жива и никто не винит его в случившемся.$b$b*Со слезами на глазах она снимает кольцо с правой руки и отдает вам.*$b$bИ... спасибо, $n.","Отнесите кольцо Сары Ладимор на могилу Моргана Ладимора.","Оставь меня в покое...","*В шорохе ветра слышится призрачный голос...*$B$BЧто это?.. Сара? Неужели она жива? Камень с сердца…$B$B$N. Возьми мой меч, Принцип. Моя душа упокоилась, и он более мне не нужен. Он был выкован во имя добра, а я оказался не достоин владеть им. Быть может, ты сможешь нести Свет вместо меня.$B$BЛиз, любовь моя...",nil,nil,nil,nil}
RUQL_QUESTS[232]={"Посылка для аптекаря Зинг","Королевскому фармацевтическому обществу нужна твоя помощь. Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении.$B$BСогласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку. К счастью, я как раз из таких. Отнеси этот заказ Алессандро Лусе, хозяину \"Тысячи мелочей Синей Луны\", он даст тебе набор для полевых испытаний. Принеси его мне, и я расскажу тебе подробнее о задании.","Отнесите заказ на товары Алессандро Луке в Подгород.","Да, чем могу помочь? Ты здесь по приказу Королевского фармацевтического общества или же просто поговорить $Gпришел:пришла;?","А, так Зинг нужен набор для полевых испытаний? Жаль, что она не решилась осчастливить меня своим визитом.$B$BЛадно, сейчас я подготовлю набор.",nil,nil,nil,nil}
RUQL_QUESTS[233]={"Почта Холодной долины","Не думаю, что ты горишь желанием мне помочь, $gпарень:красотка;, но у меня тут целая куча писем, а времени на доставку нет.$b$bЭто все для Талина Остроглаза. Его лагерь – у замерзшего озера, к западу отсюда.$b$bНу что, может, доставишь ему почту?","Доставьте письма Талину Остроглазу в Холодную долину.","А? Что? Для меня что-то есть?","Благодарю тебя, я уже давно ждал этих писем...$b$bКонечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалеку живет, может, зайдешь к нему?",nil,nil,nil,nil}
RUQL_QUESTS[234]={"Почта Холодной долины","Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда. Не сомневаюсь, он будет рад этому посланию.","Доставьте письмо Грелину Белобороду в Холодную долину.","Могу ли я тебе чем-нибудь помочь?","Здорово! Я уже давно не получал весточки из Стальгорна.",nil,nil,nil,nil}
RUQL_QUESTS[235]={"Большая охота","Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!","Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.",nil,"Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где $Gюному:юной; |3-2($C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.",nil,nil,nil,nil}
RUQL_QUESTS[236]={"Горючее для разрушителей","$n! Ты как раз вовремя. Хотя эта битва закончилась, мы должны подготовиться к новым сражениям. Отправляйся в Огненную котловину, который находится в на юго-востоке Озера Ледяных Оков, и принеси оттуда несколько неугасимых угольков.$B$BСмешав их с обычным углем, мы получим топливо для наших разрушителей и осадных машин.$B$BКстати, если по пути тебе встретятся солдаты Орды – не стесняйся, убей их и забери угольки. Нельзя допустить, чтобы в следующей битве преимущество оказалось на их стороне.","Осадный кузнец Крепкохват из Крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.","Итак, тебе удалось достать угли? Или злые ордынцы отшлепали тебя по пути к Котлу?","Превосходно! Теперь огонь войны никогда не угаснет.",nil,nil,nil,nil}
RUQL_QUESTS[237]={"Защита королевских земель","Горный пехотинец Кремневик превозносит тебя до небес, |3-6($r). Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны.$b$bОтправляйся в южные холмы и убей 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.","Горный пехотинец Булыжный Карьер просит вас убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов.","Мы должны выиграть время, |3-6($c). Тебе приказано убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Не ослабляй натиск на врага, пока не подойдет подкрепление. Сейчас не время сидеть сложа руки.","Ты прекрасно $Gсправился:справилась; с заданием, |3-6($c)! Сам король может гордиться тобой.$b$bК сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью мое сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу.$b$bПоговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты $Gнужен:нужна; нам как никогда.",nil,nil,nil,nil}
RUQL_QUESTS[238]={"Посылка для аптекаря Зинг","Я подготовил набор, $n. Не сомневаюсь, аптекарю Зинг не терпится его получить. Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счет Общества. Кроме того, передай ей мой пламенный привет.$B$BНу же, не стой как истукан. Простым курьерам не ведом отдых, а?","Отнесите набор для проведения полевых испытаний аптекарю Зинг в Подгород.","Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.$b$bТы ведь $Gпринес:принесла; его?","Хорошо – приятно работать с теми, кто старается не тратить мое время попусту.$b$bКогда я закончу с набором, ты сможешь двинуться в путь. Набор пригодится для сбора необходимых данных.$b$bЯ попытаюсь закончить побыстрее. А пока ждешь, можешь обдумать, что возьмешь с собой в пустыню.$b$bДа, именно в пустыню.",nil,nil,nil,nil}
RUQL_QUESTS[239]={"Гарнизон у Западного ручья просит помощи!","Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей!$B$BТвоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в Гарнизоне у Западного ручья. Рейнер скажет тебе, что делать.$B$BГарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдешь через речушку по мосту, сверни направо.","Отправляйтесь в Гарнизон у Западного ручья и поговорите с заместителем судьи Рейнером.",nil,"Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю.$b$bУ нас тут сложилась, скажем так, напряженная ситуация. Надеюсь, ты сумеешь нам помочь.",nil,nil,nil,nil}
RUQL_QUESTS[240]={"Возвращение к Трясунчику","А вот и пирожки с \"крабами\" а-ля Груал!","Отнесите Трясунчику темные пирожки с крабами.","$N, ты уже здесь! А где моя еда?!","Ага! Спасибо, $N. Как раз то, что нужно.$B$BА вот и твоя плата за услугу!",nil,nil,nil,nil}
RUQL_QUESTS[241]={"<TEST> ЭЙ МИСТЕР УИЛСОН!","Описание","Краткое описание",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[242]={"<UNUSED>","Throm-ka, |3-6($c). There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. $b$bThey have denied the Warchief's mandate, leaving us only one course of action. We will eliminate them so that they will no longer dirty the name of the Horde.","Убейте 8 налетчиков из клана Драконьей Пасти, 3 костестражей из клана Драконьей Пасти и военачальника клана Драконьей Пасти.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[243]={"Поход в пустыню","Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен. Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными. Мне нужно по восемь образцов каждого вида.$B$BКроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы измененного набора. Поговори с главным инженером Чепухастером и добудь у него источник энергии.$B$BБез образцов ткани можешь не возвращаться.","Поговорите с главным инженером Чепухастером из Прибамбасска насчет источника энергии для набора для полевых испытаний.",nil,"А, наши источники энергии 4711-ФТЗ! Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке.$b$bНе вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился. А, думаешь, я ни о чем не догадался? Как бы не так. Но это тебе дорого обойдется, |3-6($c). В Прибамбасске ничто не достается даром.",nil,nil,nil,nil}
RUQL_QUESTS[244]={"Вторжение гноллов","Привет тебе, |3-6($c). Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов.$B$BВ Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесенные вести.$B$BФелдон обычно обходит территорию к югу от моста по дороге в Приозерье.","Поговорите с заместителем судьи Фелдоном. Его можно найти у моста западнее Приозерья, что в Красногорье.",nil,"К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель. И тогда не только Приозерье окажется в осаде!$b$bВозьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе.",nil,nil,nil,nil}
RUQL_QUESTS[245]={"Восьминогая угроза","Привет тебе, |3-6($c). Наверное, ты $Gвидел:видела; пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья.$b$bМне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов.$b$bМой тебе совет: остерегайся их яда.","Убейте 15 карликовых ядовитых кругопрядов и доложите об этом дозорному Додсу, ожидающему вас в Сумеречном лесу.","Вам лучше быть осторожным, имея дело с пауками, я потерял из-за них несколько своих людей, и поверьте мне, это неприятное зрелище - видеть человека, висящего вверх ногами в их паутине после того, как яд начал действовать чтобы смягчить их.","А! Ты $Gвернулся:вернулась;. И на первый взгляд – в целости и сохранности. Разумеется, $N, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание свое выполняю. Держи.",nil,nil,nil,nil}
RUQL_QUESTS[246]={"Подсчет врагов","У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать.$B$BПоищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги.$B$BСделай это ради армии Штормграда, $n, и получишь награду.","Убейте 10 полукровок из стаи Красногорья и 6 браконьеров из стаи Красногорья и сообщите об этом заместителю судьи Фелдону из Приозерья.","Прости, $N, но у меня сейчас совсем нет времени. Если тебе не о чем сообщить, мне лучше вернуться к делам.","*Заместитель судьи Фелдон слушает ваш отчет.*$b$bЗначит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения.$b$bЧто ж, $N, мы благодарим тебя за помощь.$b$bЕсли ты еще не $Gбеседовал:беседовала; с маршалом Маррисом и мировым судьей Соломоном, непременно обратись к ним. Дела у нас идут все хуже; не сомневаюсь, эти двое найдут тебе работу.",nil,nil,nil,nil}
RUQL_QUESTS[247]={"Завершение охоты",nil,nil,nil,"$N, ты $Gубил:убила; всех трех чудовищ охоты в Ясеневом лесу. Ты $Gпредоставил:предоставила; мне несомненные доказательства их гибели, так что сомнений в твоих силе и упорстве у меня нет. В твоих жилах течет кровь охотников, и да будет тебе хвала по делам!$B$BПрошу, прими эту безделицу в знак благодарности за твои деяния, совершенные тобой ныне в Ясеневом лесу во славу Орды. Да будут духи предков милостивы к тебе!",nil,nil,nil,nil}
RUQL_QUESTS[248]={"Пронизывающий взор","Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны.$B$BВозьми еще один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью.$B$BОтыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдет сундук или кувшин.","Поднимитесь на уцелевшую башню рядом с крепостью Каменной Стражи в Красногорье.$b$bОтыщите подходящее место и спрячьте там амулет Азоры.","Когда-то в этом кувшине был какой-то смрадный напиток, но теперь пустой сосуд лежит, забытый, на паре бочек.","Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи.",nil,nil,nil,nil}
RUQL_QUESTS[249]={"Моргант","Ценой долгих усилий я раскрыл планы Морганта.$B$BОн ищет Косу Элуны... и быть может, уже отыскал ее! Коли так, то скоро Красногорье, а следом и все королевство Штормграда почувствует его темную мощь.$B$BЯ не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты $gдолжен:должна; войти в башню Илгалара и бросить ему вызов.$B$BОдолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.","Победите Морганта.$B$bПринесите его подвеску Тени Теокриту в башню Азоры в Элвиннском лесу.","Торопись, $N, пока не сбылись мои опасения и темное влияние Морганта не расползлось по всей стране.","Ты $Gсделал:сделала; великое дело, $N. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности.$B$BСмиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена.$B$BВместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях.",nil,nil,nil,nil}
RUQL_QUESTS[250]={"Черная угроза","Хвала небесам, что хоть кого-то волнует наша Дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Черного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора.$b$bПотому-то ты мне и $gнужен:нужна;, $n. Я заметил саперов из клана Черного железа неподалеку от восточной части Дамбы. Разведай обстановку и возвращайся с уликами.","Осмотрите область вокруг восточной части Дамбы и отыщите для главного инженера Плотиннера улику, указывающую на замыслы дворфов Черного Железа.",nil,"В подозрительной бочке содержится странно пахнущий порошок.",nil,nil,nil,nil}
RUQL_QUESTS[251]={"Перевод записки Аберкромби","Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он.","Отнесите письмо, адресованное Элло, Шире Фон-Инди.","Значит, это записка от отшельника Аберкромби? Я с ним не знаком, но если он живет на кладбище, то мозг у него – трухлявый, как старый пень!","*Шира принимается за перевод записки...*",nil,nil,nil,nil}
RUQL_QUESTS[252]={"Перевод для Элло","О небо! Если то, о чем сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое.$B$BОтнеси-ка переведенную записку Элло.$B$BИ поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу...","Отнесите переведенное письмо лорду Элло Чернодреву.","А, так записку перевели? Дай-ка взглянуть...","*Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд.*$b$bХотя ты $Gпомогал:помогала; Аберкромби по доброте душевной, именно ты $Gобрек:обрекла; наш город на гибель.$b$b*Элло погружается в раздумья...*",nil,nil,nil,nil}
RUQL_QUESTS[253]={"Невеста Бальзамировщика","Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть ее к жизни, он прибег к темной магии и даже вложил в грудь мертвой супруги собственное сердце.$B$BЭто оживило Элизу... но ее сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать ее обратно.$B$BВсе его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из нее сердце и принеси его мне, пока оно бьется. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет.","Отыщите могилу Элизы. Извлеките из нее сердце Бальзамировщика и вернитесь к Элло Чернодреву.","Тебе удалось найти могилу Элизы? А достать сердце Бальзамировщика?","Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью.$B$BТы $Gсовершил:совершила; подвиг во имя нашего народа, $N. Мы тебя не забудем.",nil,nil,nil,nil}
RUQL_QUESTS[254]={"Копание земли",nil,nil,nil,"Вы копаете землю... и наконец находите остатки гроба.$B$BВы слышите скрежет когтей по крышке и лязганье гнилых зубов…$B$BРешитесь ли вы открыть гроб и достать сердце Бальзамировщика?",nil,nil,nil,nil}
RUQL_QUESTS[255]={"Наемники","Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и Дамба - Дамба! - тоже в опасности.$B$BПохоже, у меня нет выбора. Придется искать наемников.$B$BКак насчет тебя? На первый взгляд ты подходишь, |3-6($c). На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?","Мировой судья Тупонос просит вас убить 4 огров из клана Мо'грош, 4 громил из клана Мо'грош и 4 головорезов из клана Мо'грош.","Все получилось?","Прекрасные новости! Я и народ Телcамара глубоко признательны тебе. Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами.",nil,nil,nil,nil}
RUQL_QUESTS[256]={"Разыскивается: Чок'сул","По приказу мирового судьи Телcамара:$b$bЧок-сул, обвиняемый в организации нападений на город Телcамар, Каменную плотину и раскопки, приговаривается к смерти любым из возможных способов.$b$bВознаграждение получит тот, кто предоставит судье доказательства смерти Чок-сула.$b$bВ последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан.","Убейте Чок'сула и принесите его голову мировому судье Тупоносу в Телcамар.","Да? Чем я могу вам помочь?","Ой! Что это? И зачем ты $Gпритащил:притащила; ее…$b$bБоги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телcамара достаются тебе по праву!",nil,nil,nil,nil}
RUQL_QUESTS[257]={"Похвальба охотника","Думаешь тягаться с Дерилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду. Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет.$b$bНеподалеку от озера Лок Модан свила гнезда стая канюков. Почему бы не подстрелить несколько тварей? Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружье.$b$b*Он с презрением осматривает вас.*$b$bВсе равно тебе нечего терять.","Убейте 8 горных канюков и вернитесь к Дерилу Юному в Приют странников.","Не вышло? Не расстраивайся, бедненький $N…$B$BНе всем же быть такими, как я.","Что? Получилось?!$B$BПослушай добрый совет, $N, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренек с луком справился бы с такими... небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом.$B$BЧто ж, э-э-э... Пусть не говорят, что Дерил Смелый не держит свое слово.",nil,nil,nil,nil}
RUQL_QUESTS[258]={"Вызов охотнику","$n $GБатькович:Батьковна;, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко.$b$bА вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут.$b$bНе расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься!$b$bЯ не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад...","Убейте 10 старых горных вепрей и вернитесь к Дерилу Юному в Приют странников.","Вполне простительно пожалеть себя, если тебе утер нос кто-то столь же юный, как я. Не расстраивайся, $N...$B$BКстати, это у тебя имя такое или кличка?","Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трепку, да? Не беспокойся, я никому не расскажу о твоем поражении. Тебе и без досужих болтунов тяжело.$B$BО! Ты $Gумудрился:умудрилась; убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребенок смог бы... Обещание?$B$BКакое еще обещание?",nil,nil,nil,nil}
RUQL_QUESTS[259]={"<UNUSED>","Hello there, $n. I've heard much about your exploits, and must say I'm honored to meet you. I don't suppose you've heard the story of Ol' Kelt? Ah, well, Ol' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn't much he hadn't done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you're interested, you might talk to Kelt.","Talk to Kelt Thomasin.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[260]={"<UNUSED>","Now, this will no doubt convince you that I am, as they say--and don't deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent a good bit of my life trying to track it down, and I believe I got close, but alas, I fear old age has caught up to me. If you would like to try hunting down the monster of the Loch, bring me some treshadon teeth and claws.$b$b<He smiles mysteriously.>","Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[261]={"Путями Алого ордена","Буду откровенен. Мы ведем войну с нечистью. Это зло, уничтожающее наш народ и оскверняющее нашу землю. Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак. Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души.$B$BТы с нами? Тогда яви свое мужество и докажи свою доблесть: убей нежить-опустошителей, бродящих по Пустошам на юге, в Долине Костей.$B$BСделай это, и братство Алого ордена примет тебя.","Убейте 30 представителей нежити-опустошителей и вернитесь к брату Антону на Высоте Найджела.","С каждым днем Плеть становится все сильнее и многочисленнее. Если ты действительно хочешь остановить ее, докажи это делом!","Тебе удалось доказать свою решимость. Братство Алого ордена благодарит тебя.$B$BЕсли тебя не страшит то, что ради правого дела приходится убивать, причем часто и много, тогда тебе с нами по пути.",nil,nil,nil,nil}
RUQL_QUESTS[262]={"Таинственный незнакомец","Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!$b$bПрошу тебя, $n, помоги мне. Ты не раз $gтворил:творила; настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!$B$BЯ рассказал тебе все, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает ее, и мы выясним имя владельца?","Отнесите книгу, обнаруженную на ферме Свена, в Темнолесье и покажите ее горожанам.","Если у тебя есть что-нибудь из вещей того незнакомца, которого ты разыскиваешь, покажи это мне. Может быть, я смогу понять, кто ее владелец.","Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести. Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы.$b$bЯ могу сказать одно: он не из Темнолесья.",nil,nil,nil,nil}
RUQL_QUESTS[263]={"Защита королевских земель","Горные пехотинцы уверяют, что ты $gсилен и отважен:сильна и отважна;, $n. Нам $gнужен:нужна; |3-6($r) вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас $gпоявился закаленный:появилась закаленная; в боях |3-6($c),\n\n то может быть, нам удастся выстоять.$b$bУбей 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов.","Горный пехотинец Стенолом просит вас убить 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов.","Уже $Gвернулся:вернулась;? На всякий случай повторяю: я просил убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов, $N. В атаку, Гроза троггов!","Я сразу понял, $N, что Стальгорн будет тобой гордиться. Ты славно $Gпослужил:послужила; королю Магни. Теперь, доказав, что ты верный $Gзащитник:защитница; Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы.",nil,nil,nil,nil}
RUQL_QUESTS[264]={"Покуда смерть не разлучит нас","Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\"$B$BА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чертового долга!$B$BИ посмотрите, $n, теперь на плоды борьбы за \"справедливость\"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!$B$BВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!","Положите подвеску Кларисы на могилу Юрива в Серебряном бору.","Каменная плита холодна на ощупь. Могила была осквернена: вокруг валяется мусор, барельеф на плите исцарапан, из него выбиты куски, надгробье зарастает травой.$b$bНикому нет дела до погребенного здесь, особенно если это жертва поветрия.","Вы кладете дешевую безделушку на могилу, и драгоценный камень в ней заметно тускнеет.$b$bКогда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мертвая, в руках вырезанного на надгробной плите изображения. Ваши мысли прерывает порыв холодного ветра, пронесшегося по Гробнице. На мгновение все вокруг вас замирает.",nil,nil,nil,nil}
RUQL_QUESTS[265]={"Продолжение поисков незнакомца","Вот твоя книга, $n, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное.$B$BЯ же скажу одно: хотя автор этой книги не из нашего города, тетрадь для нее он купил здесь.","Поговорите с горожанами о таинственном незнакомце.","Иногда я продаю чистые тетради ученым и магам, а также тем, что хочет вести дневник.$B$BЯ помню всех покупателей за последние несколько месяцев...","Ах, да. Я продал эту тетрадь одному сомнительному типу. Он не представился, но явно нервничал, дергался, то и дело оглядывался через плечо.$B$BНадеюсь, что смог тебе помочь...",nil,nil,nil,nil}
RUQL_QUESTS[266]={"Расспросы в таверне","Вот твоя книга, желаю удачи в расследовании.$B$BСоветую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел.","Найдите в таверне улики, связанные с таинственным незнакомцем.","Хотя \"Алый Ворон\" процветает не так, как раньше, путники гостят здесь и в наши дни.$B$BЕсли ты опишешь того, кого ищешь, может быть, я его вспомню.","Ах да, эту книгу я помню. Ее владелец снимал комнату на несколько дней и вечерами засиживался в баре, все писал.$B$BГород он покинул в спешке, бормоча под нос, что его преследует... что-то. В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие.$B$BПервое, что ему встретится на западе, – это Вороний холм...",nil,nil,nil,nil}
RUQL_QUESTS[267]={"Угроза со стороны троггов","$C, не знаю, $gслышал:слышала; ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов.$b$bИ все же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений 8 каменных зубов троггов.","Принесите 8 каменных зубов троггов капитану Ругельфассу к южной сторожевой башне.","Ты $Gпринес:принесла; мне 8 каменных зубов троггов? Если нет, тебе есть чем заняться, $N.","Отличная работа, $N. Ты $Gоказал:оказала; всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!",nil,nil,nil,nil}
RUQL_QUESTS[268]={"Возвращение к Свену","Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить ее на ферме Свена во время поспешного бегства...$B$BВот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме.$B$BХотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!","Отнесите Свену законченные записи Трясунчика.","Тебе удалось выяснить, что это за незнакомец?","Записи многое проясняют. Теперь мне ясно, что следует искать темных всадников! Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы.",nil,nil,nil,nil}
RUQL_QUESTS[269]={"В поисках мудрости","Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну.$B$BХоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас.$B$BТебя ждет много опасностей... Однако поспеши, $n. С каждым часом в Сумеречном лесу сгущается тьма.","Отдайте законченные записи Трясунчика епископу Фартингу в Штормграде.","Отдохни пока, $Gбрат:сестра;. Я вижу, у тебя позади долгий путь, и на тебя возложена тяжкая ноша. Скажи, что за тень пала на тебя?","*Епископ изучает записи...*$B$BЗло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя.$B$BНо прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться... Некромант Морбент Скверн всегда был необычайно силен, а чтобы стать неуязвимым, наложил на себя могучие чары. Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды.",nil,nil,nil,nil}
RUQL_QUESTS[270]={"Обреченный флот","Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорн. Одно из судов было нагружено светосталью.$b$bЭтот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится.$b$bОтправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз еще можно найти – он сообразит, где нужно искать.","Отправляйтесь в Гавань Менетилов в Болотине и поговорите с дворфом по имени Глорин Стальной Лоб.",nil,"Светлая сталь – и впрямь драгоценный металл, но все говорит за то, что задание у тебя не из легких. Ты $Gпроделал:проделала; длинный путь, $Gбратишка:сестрёнка;. Если тебе сильно повезет, ты можешь найти то, что ищешь.$b$bА если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь.",nil,nil,nil,nil}
RUQL_QUESTS[271]={"Месть Вайрины","Не хочешь отплатить Его Смелости? Вынуждена признать, что Дерил в самом деле многое умеет.$b$bГод назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дерил решил выступить против зверя сам. Разумеется, он ничего не добился, да еще и получил этот уродливый шрам над глазом.$b$bУбей медведя, и не сомневаюсь, что даже Дерил ненадолго лишится дара речи.$b$bСтарину Черношкура можно отыскать в логове в холмах над Телcамаром.","Убейте Старину Черношкура и принесите его голову Дерилу Юному в Приюте странников.","А, $N! Уже $Gвернулся:вернулась;? Опять $Gохотился:охотилась;? Не огорчайся, если тебя постигнет неудача. Неудачи заставляют нас работать над собой!$B$BВ любом случае тебе повезет больше, чем некоторым...","Э... что это? Судя по всему, медвежья голова.$B$B*Он невольно проводит пальцем по старому шраму.*$B$BЧто ж, интересная добыча. Не тот ли самый медведь...$B$B*Он умолкает и начинает заметно дрожать.*$B$BО, скорее убери ее! Убери отсюда эту страшную штуку!",nil,nil,nil,nil}
RUQL_QUESTS[272]={"Испытание Морского Льва","Вот твое второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.$B$BПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.","Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.$B$BСложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремула.$B$BОтнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне.","Вы уже собрали кулон воедино и принесли мне, $N? Если вам нужна помощь в поиске частей, спросите местных жителей, возможно, они дадут вам немного информации. Кроме того, это даст вам возможность исследовать эту чудесную и священную поляну.","Ты $Gпрошел:прошла; испытание Морского Льва, $N. Прими мои поздравления.$B$BКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.$B$BЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.",nil,nil,nil,nil}
RUQL_QUESTS[273]={"Снабжение экспедиции","Еще не поздно, ты можешь поискать Хальдара. Вряд ли он ушел далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро.$b$bОни пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера.$b$bНайти их будет несложно, если они еще не добрались до места назначения.","Поговорите с Хальдаром.",nil,"Хм, жалкой засаде Черного Железа не помешать мне доставить товар!$b$bНо Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил.$b$bЛадно, подумаю об этом позже.",nil,nil,nil,nil}
RUQL_QUESTS[274]={"Черная угроза","А теперь отнеси эту смесь обратно главному инженеру и быстро. Черное Железо не медлит, не можем и мы.","Ашлан Камнехмыл велел вам вернуться к главному инженеру Плотиннеру с нейтрализующей смесью.","Что ты $Gпринес:принесла; от Аслана?","Нейтрализующий коллоид? Для Cефория? О небо!",nil,nil,nil,nil}
RUQL_QUESTS[275]={"Нарывы на теле земли","Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить ее, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли.$B$BПолзуны водятся у водоемов в Болотине.","Убейте 8 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину.","Я слышу стон земли Болотины. Трясинные ползуны все еще оскверняют ее своим присутствием. Возвращайся, когда выполнишь мое поручение.","Скоро раны на теле земли затянутся, и лихорадка спадет. Я благодарю тебя и вручаю небольшой подарок...",nil,nil,nil,nil}
RUQL_QUESTS[276]={"Вытоптанные луга","Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова!$B$BЧтобы спасти природу нашего края, придется истребить часть гноллов.$B$BУбей 15 гноллов из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне.","Убейте 15 гноллов из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину.","Ты еще не $Gвыполнил:выполнила; мое задание, |3-6($C).","Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, |3-6($c), заставил меня задуматься. Спасибо тебе!",nil,nil,nil,nil}
RUQL_QUESTS[277]={"Запрет на огонь","Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!$B$BОтбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров.","Принесите Ретилю Стражу Природы 9 необработанных кремней.","Ты $Gпринес:принесла; эти проклятые камни для высекания огня?","Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть.",nil,nil,nil,nil}
RUQL_QUESTS[278]={"Прямая и черная угроза","Немедленно принимайся за сбор материалов для нейтрализации взрывчатки, $N. Паучий яд ты найдешь у пауков у озера Лок Модан. Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко. Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто.$B$BМы должны разминировать творение Черного Железа! Как только соберешь все материалы, сразу же возвращайся, и я подготовлю состав.","Принесите паучий яд, Мо'грошский кристалл и слезу кроколиска главному инженеру Плотиннеру.","Ты $Gпринес:принесла; все необходимое? Торопись!","Наконец-то, $N!",nil,nil,nil,nil}
RUQL_QUESTS[279]={"Угроза из глубин","Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить.$B$BОдин из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и все – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмется их защищать.$B$BЖрун промышляет в речном заливе к северу отсюда. Найди его и убей. А еще убей всех его родичей и принеси мне его голову.","Убейте 12 мурлоков из племени Синежабрых.$B$BПрикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[280]={"Прямая и черная угроза","Я только сегодня видел мятежников из клана Черного Железа, которые тащили к дамбе большую бочку. И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил! Боюсь, они заложили сефорий у основания дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты. Вот, у меня получилась нейтрализующая смесь.$B$BСкорее, возьми смесь и залей ее в бочку, пока не поздно. Торопись!","Проплывите по реке к основанию дамбы, отыщите бочку с порохом и влейте в нее нейтрализующую смесь, чтобы предотвратить взрыв.","Крышка бочки медленно отвинчивается.","Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение.",nil,nil,nil,nil}
RUQL_QUESTS[281]={"Украденные товары","Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\". Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила. Ее надо вернуть во что бы то ни стало.$B$BОбыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – все, что может быть связано с украденным грузом. Найди статуэтку Менетила и верни ее мне.","Обыщите сундуки, бочки и ящики в поселениях мурлоков на побережье.",nil,"Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома. Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому...$B$B...и находите несколько бутылок из красного стекла.",nil,nil,nil,nil}
RUQL_QUESTS[282]={"Наблюдения Сенира","Я собирался послать своего ученика к брату Сениру с отчетом, но парень он не слишком надежный, а мне нужен кто-то, на кого действительно можно положиться. Ну, то есть, конечно, если ты не будешь возражать.$b$bХм-м. Чтобы добраться до Караноса, тебе придется пройти по тоннелю. $b$bПеред тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов.$b$bСначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток. Рядом с тоннелем Талос и стоит – найти его будет несложно.","Поговорите с горным пехотинцем Талосом.","Приветствую! Я тебе вот что скажу, $N: ты в тоннеле Дун Морога будь поосторожнее, там полно троггов, так что дорога небезопасна.$b$bЯ тебе даже больше скажу: если у тебя нет неотложных дел в Дун Мороге, оставайся-ка лучше в Старой Наковальне, пока в тоннеле не станет поспокойнее.","Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно?$b$bС другой стороны, пару советов-то я могу тебе дать...",nil,nil,nil,nil}
RUQL_QUESTS[283]={"Прямая и черная угроза","Бочка негромко шипит.","Кажется, нейтрализующая смесь сработала. Вернитесь к главному инженеру Плотиннеру – принесите ему добрые вести.",nil,"Огромное спасибо, $N! Ты $Gспас:спасла; Каменную дамбу. Без твоей помощи террористы Черного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, $Gотважный:отважная; |3-6($C)!$B$BДамба снова в безопасности... по крайней мере, пока...",nil,nil,nil,nil}
RUQL_QUESTS[284]={"Поиски продолжаются","Вы обыскиваете все поселение мурлоков в этом районе, но статуэтки Менетила здесь нет.$B$BМожет быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?","Найдите статуэтку Менетила.",nil,"Эту бочку, похоже, никто не трогал. Вы открываете ее...$B$BЗапах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!",nil,nil,nil,nil}
RUQL_QUESTS[285]={"Поиски в поселениях мурлоков","Вы обыскиваете еще несколько жилищ мурлоков. Вот досада – опять ничего!$B$B...Но вы уверены, что все получится.$B$BСтатуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу.","Продолжите поиски статуэтки Менетила в поселении мурлоков.",nil,"Бочка наполовину утоплена в грязи и мокрой траве...",nil,nil,nil,nil}
RUQL_QUESTS[286]={"Возвращение статуэтки","Вы достаете бочку из грязи, открываете ее и видите серебряную статуэтку, укрытую соломой. Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом.$B$BЭто, должно быть, и есть статуэтка Менетила! Теперь вам надо вернуть ее Карлу Борану в Гавань Менетилов.","Верните статуэтку Менетила Карлу Борану. Его можно найти в Гавани Менетилов, что в Болотине.","Ты $Gпринес:принесла; статуэтку?","Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты $Gсослужил:сослужила; нам хорошую службу и получишь обещанную награду.$B$BРадостно сознавать, что в этом мире еще есть надежные люди, на которых можно положиться, и особенно – в такое тяжелое и неспокойное время.",nil,nil,nil,nil}
RUQL_QUESTS[287]={"Форт Мерзлогривов","Я не успеваю с донесением, и твоя помощь, $n, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда.$b$bВот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне.$b$bОтправляйся из Караноса по северной дороге. Когда перейдешь через мост, следуй на запад по замерзшей реке, пока не доберешься до Заледеневшего озера. На западном берегу обнаружишь Поселок Пивоваров. Форт Мерзлогривов находится к юго-западу от него.","Обследуйте форт Мерзлогривов и убейте 5 охотников за головами из племени Мерзлогривов по просьбе Сенира Белоборода из Караноса.","Мои указания были предельно ясны! У нас мало времени, тебе нужно поторопиться! Не возвращайся, пока не найдешь пещеру.","А, $N! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно четки...$b$bДай-ка мне закончить донесение.$b$b*Он приносит бумагу и что-то быстро на ней пишет.*$b$bВот! Ха-ха, теперь это совсем забавно... Думаю, $N, ты не откажешься помочь мне еще разок?",nil,nil,nil,nil}
RUQL_QUESTS[288]={"Третья флотилия","Когда-то я был первым помощником на \"Владычице\", линейном корабле Третьей флотилии Кул-Тираса. Обреченной флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки!$B$BУ нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре.$B$BОх, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу.","Купите первому помощнику Фитсиммонсу кружку медовухи.","Трубы горят, сил нет! $GДобрый:Добрая; $Gгосподин:госпожа;, не купите бедному забулдыге чего-нибудь горячительного? Умираю!","Вот! И голова не болит, и язык развязался. Спасибо, $Gприятель:подруга;!",nil,nil,nil,nil}
RUQL_QUESTS[289]={"Проклятая команда","<Приободрившись, Фитсиммонс продолжает рассказывать...>$B$BЯ единственный уцелевший из всех матросов злополучной Третьей флотилии Кул-Тираса, погибшей у северного побережья. И хотя я последний из команды, чье сердце бьется и кто еще дышит, я не единственный, кто еще бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не дает им покинуть гниющие остовы кораблей.$B$BЕсли ты сможешь их освободить, тогда, может быть, они избавятся от проклятия.","Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов.","Мне снятся кошмары, в которых я слышу, как наяву, стоны моих обреченных собратьев! Заклинаю тебя, $Gдобрый:добрая; $Gсэр:леди;, освободи их от этого ужаса. Пусть их стоны и вопли умолкнут навечно.","Благодарю тебя, $N. И прими благодарность моих несчастных собратьев.",nil,nil,nil,nil}
RUQL_QUESTS[290]={"Очищение","Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моем корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора.$B$BСтарина капитан снится мне до сих пор. Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь.$B$BПотом отнеси ее в город и отдай жрецу Глорину Стальному Лбу.","Возьмите ключ от сейфа на \"Отважном\" у капитана Халиндора.$B$BОткройте сейф на \"Отважном\".","Сейф заперт надежно.","Ключ насквозь проржавел, но замок открылся без труда.",nil,nil,nil,nil}
RUQL_QUESTS[291]={"Донесения","Замечательно! Отнеси мое донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдешь его в Стальгорне, в палате, где король Магни вершит суд.$B$bЧто? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы.$b$bКстати, будь $gдобр:добра;, не говори о том, как ты мне $gпомогал:помогала;. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.","Отнесите донесение Сенира сенатору Бэрину Краснокамню в Стальгорн.","Хм... похоже, мои охранники потеряли хватку и пропускают ко мне кого попало. Ладно, что тебе надо? Говори быстрее.","*Он быстро просматривает донесение.*$b$bПо приказу КОРОЛЯ!? Магни совсем спятил! И еще этот проклятый Белобород... Значит, взял дела в свои руки? Сенат этому не обрадуется, вовсе не обрадуется.$b$bЧто, ты еще здесь? Иди отсюда, пока я охрану не вызвал!",nil,nil,nil,nil}
RUQL_QUESTS[292]={"Око Палета","Внутри сундука лежит темный шар, источающий зловещее свечение. Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета.$B$BОтнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов. Попросите его снять проклятие с Ока.","Отнесите проклятое Око Палета Глорину Стальному Лбу. Его можно найти в Гавани Менетилов, что в Болотине.","Тебя послал этот пропойца Фитсиммонс? Так скажи ему, что эль у меня закончился! Нечего ему разорять мои запасы.","Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты $Gнашел:нашла; его среди обломков судна? Это многое объясняет! Но как же Око попало на корабль Третьей флотилии?..$B$BНеудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи.",nil,nil,nil,nil}
RUQL_QUESTS[293]={"Проклятое Око","Я не могу снять проклятие с Ока Палета. Это людское творение, и поэтому тебе следует направиться в Штормград. Найди того, кто сумеет тебе помочь. Обратись к архиепископу Бенедикту. Он главный в Соборе Света Штормграда, и сможет дать тебе наставления.$B$BНадеюсь, у тебя все получится.","Отнесите Око Палета архиепископу Бенедикту. Его можно найти в Соборе Света в Штормграде.","Что это у тебя? Какой-то запачканный шар...","Это Око Палета. Определенно, оно видело много скорбей и печалей... может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии.$b$bСейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей.",nil,nil,nil,nil}
RUQL_QUESTS[294]={"Месть Ормера","Придется признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а мы с Меррин и бедолагой геологом оказались в ловушке здесь, наверху.$b$bПомоги очистить Болотину от ящеров, $n. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утеса. Убей по 10 тварей каждого вида.$b$bЭто будет началом моей мести.","Убейте 10 крапчатых ящеров и 10 крапчатых крикунов.","Убей 10 крапчатых ящеров и 10 крапчатых крикунов, $N. Мои погибшие товарищи не заслужили своей горькой участи. Пора свести счеты.","Я понимаю, что убийство – грязная и опасная работа, $N. Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой.",nil,nil,nil,nil}
RUQL_QUESTS[295]={"Месть Ормера","Пора нанести им сокрушительный удар. Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов. Убей по 10 гадов каждого вида!","Убейте 10 крапчатых смертехватов и 10 крапчатых острозубов. Вернитесь к Ормеру Сталеплету на раскоп Вельгара.","Крапчатые смертехваты и крапчатые острозубы должны заплатить за все, что они с нами сделали. Ты уже $Gубил:убила; по десятку этих мерзавцев?","$N, ты не представляешь, как ты мне $Gпомог:помогла;!",nil,nil,nil,nil}
RUQL_QUESTS[296]={"Месть Ормера","Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр. Он крупнее остальных и отличается особой свирепостью. Могу поклясться, что он – их вожак, это он привел их сюда и подначил разорить шахту.$b$bСослужи мне последнюю службу, $n. Зарлозуба надо предать правосудию. А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте! Убей его и в доказательство принеси мне один из его когтей.","Убейте Зарлозуба и принесите Ормеру Сталеплету один из когтей чудовища.","Зарлозуб мертв? Ты $Gотомстил:отомстила; за смерть наших братьев?","Спасибо, $N. Мы не забудем того, что ты $Gсделал:сделала; для нас. Сколько ни в чем не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах. Но ты $Gотомстил:отомстила; за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни.",nil,nil,nil,nil}
RUQL_QUESTS[297]={"Сбор идолов","Незадолго до появления троггов на раскопках мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!$B$BОтбей 8 идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдешь у троггов – а их в раскопе более чем достаточно.","Принесите Магмару Рудоколу 8 резных каменных идолов c раскопок Сталекрута.","И где же идолы? Надо хорошенько изучить их и сообщить о результатах в Стальгорн!","Ты $Gдобыл:добыла; их! Хвалю, $N!$B$BИ хотя там полно троггов-берсерков, ты, кажется, не сильно $Gпострадал:пострадала;. Я буду с интересом следить за твоей судьбой... Ты подаешь надежды.",nil,nil,nil,nil}
RUQL_QUESTS[298]={"Отчет о ходе раскопок","Мне нужно отправить в Телcамар отчет о ходе работ и запрос на получение нового груза пороха! Вот мой отчет. Отнеси его Джерну Шлеморогу, он наш представитель в Телcамаре.$b$bЗадание не сложное, но достаточно важное.","Отнесите отчет о ходе работ Джерну Шлеморогу в Телcамар.","О, отчет о ходе работ на раскопе? Превосходно!","Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями...$b$bТак или иначе, он будет потрачен не зря!$b$bНо вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся.",nil,nil,nil,nil}
RUQL_QUESTS[299]={"Тайны прошлого","Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырех местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\".$b$bБоюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты $gмолод и полон:молода и полна; сил.$b$bОбыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!","Обыщите раскопки и найдите четыре недостающих фрагмента скрижали: Адос, Модр, Голм и Неру. Принесите их геологу Вельгару.","Ты $Gнашел:нашла; недостающие фрагменты, $N? Адос, Модр, Голм и Неру...","Итак, скрижаль Гоаз восстановлена! Ты хорошо $Gпотрудился:потрудилась;, $N. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землей\". Похоже, грядут грандиозные перемены.",nil,nil,nil,nil}
RUQL_QUESTS[301]={"Отчет в Стальгорн","Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придется отнести его отчет в штаб-квартиру Лиги исследователей.$b$bВот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ.$b$bГрозовую Вершину можно найти в Зале Исследователей.","Отнесите отчет Сталекрута о ходе работ геологу Грозовой Вершине.","Представители моего клана терпеть не могут, когда нас беспокоят по пустякам, |3-6($C). Надеюсь, твои вести стоят моего драгоценного внимания.","Проклятый Железняк! Я послал ему целый воз пороха еще неделю назад, но он не потрудился упомянуть об этом в отчете.$b$bТак... куда делся порох?!?",nil,nil,nil,nil}
RUQL_QUESTS[302]={"Порох для Сталекрута","Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута.$B$BИ еще одно: я хочу, чтобы ты лично $gпроследил:проследила; за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.","Поговорите с Джерном Шлеморогом в Телcамаре.",nil,"Что? Грозовая Вершина хочет, чтобы ты лично $Gпроследил:проследила; за доставкой груза к Железняку?$b$bЯ... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно.",nil,nil,nil,nil}
RUQL_QUESTS[303]={"Война с Черным Железом","Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Черного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр.$b$bТебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников, тогда, может быть, мы и продержимся до подхода подкрепления.$b$bИ поторопись! У нас мало времени.","Убейте 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников по просьбе Мотли Гармасона.","Рогго не смог связаться с резервными силами. Нам нужно наступательное давление на лагерь Черного Железа, $C. А теперь возвращайся и выполняй свой долг перед королем Магни!",nil,nil,nil,nil,nil}
RUQL_QUESTS[304]={"Мрачное поручение","Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Черного Железа – те еще бестии. Чертово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда.$b$bРазыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, |3-6($c).","Убейте Балгараса Нечистого и принесите его ухо Гриму Длиннокосу в Дун Модр.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[305]={"Пропавшие ученые","Ты, должно быть, $gтот самый разведчик:та самая разведчица;, $gкоторого:которую; обещал прислать Длиннокос? Знаешь... как-то мне неспокойно на сердце.$b$bМоя благоверная, Меррин, работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю, весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!$b$bДлиннокос обещал, что, если я вскорости не получу никаких известий, он пришлет мне $gразведчика:разведчицу;, $gкоторый:которая; проверит, что стало с экспедицией. Как я понимаю, ты и есть $gэтот разведчик:эта разведчица;, $n. Разыщи Меррин на раскопе к востоку отсюда!","Таррел Камнепряд просит отыскать Меррин Камнепряд на раскопках.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[306]={"Пропавшие ученые","Это было ужасно! Мы обнаружили несколько очень редких артефактов. Пока мы занимались раскопками, нам все чаще и чаще начали попадаться огромные кости.$b$bВсе случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас. Почти все наши погибли в неравной схватке.$b$bОстались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и геолога, он прикрывал нас, пока мы бежали в укрытие. А теперь мы в ловушке, и вся наша работа пропала!$b$bВот, отнеси эту записку моему дорогому Таррелу. Я ему все написала подробно. Он разберется.","Отнесите записку от Меррин Таррелу Камнепряду. Его можно найти в Гавани Менетилов, что в Болотине.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[307]={"Грязные лапы","Серебряные копи давно уже выработаны. Лига рудокопов превратила их в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!$B$BРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в копи не спустились воины и не разнесли все к демонам. Задача твоя не из простых, помощники тебе не помешают.$B$BОборудование находится в ящиках лиги Рудокопов, разбросанных по копям.","Отправляйтесь к Серебряным копям и принесите 6 ящиков с инструментами шахтеров горному пехотинцу Грозовой Вершине.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[308]={"Отвлечь Ярвена",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[309]={"Охрана груза","Надо доставить этот порох Сталекруту, но сейчас эта телега никуда не пойдет. Вес немалый, а здесь небезопасно – кто знает, что еще замышляют дворфы Черного Железа, особенно теперь, когда с ними Сайан.$b$bС тобой мне будет гораздо спокойнее. Пока мы с тобой будем охранять телегу, Миран сможет выгрузить бочонки с порохом в лагере.","Защитите Хальдара и караван Сталекрута, а затем поговорите с геологом Сталекрутом.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[310]={"Злейшие соперники","Не могу не признать, эти Громовары варят славное пойло. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок...$B$BВот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что мое пиво лучше, чем Громоваров!$B$BЕсли бочонки охраняются, тебе придется отвлечь стражу...","Замените один бочонок эля Громоваров бочонком жгучего пива Ячменоваров в подвале \"Громоварки\" в Караносе.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[311]={"Возвращение к Марлетте","Подсунув бочонок жгучего пива Марлетты в подвал Громоварки в Караносе, вы хватаете бочонок эля Громопойлов в качестве доказательства...","Принесите бочонок громового эля Марлетте Ячменовар в Поселок Пивоваров.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[312]={"Ограбление тайника Тундры Макгранна","У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Но он не смог взломать ториевый замок. Но я же с голоду помру, если не верну свое мясо!$b$bТы вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь.","Добудьте из пещеры Старого Ледоборода вяленое мясо из краденого ларя Тундры Макгранна.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[313]={"Вести наблюдение издалека","Из-за катаклизма множество троггов выбрались на поверхность, в связи с чем тролли из племени Мерзлогривов были вынуждены спасаться бегством. К сожалению, они поселились совсем рядом с нами, и это создает для нас проблемы.$b$bЯ отдал распоряжение горному пехотинцу Данстану отправиться вместе со своим отрядом в Серую берлогу, что к юго-западу отсюда, приглядывать за живущими там вендиго, но сейчас мне нужно, чтобы они вернулись в Каранос. Найди их и скажи, чтобы они установили в Серой берлоге роботов удаленного наблюдения, полученных от гномов, а сами отправлялись в Каранос.","Сообщите о распоряжениях капитана Таррана горным пехотинцам Данстану, Льюину и Валгруму. Их можно найти в Серой берлоге.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[314]={"Защита стада","Мы услышали шум среди ночи. Поутру не досчитались двух баранов в отаре. Эта подлая тварь Вагаш покушается на наш скот. И поскольку армия Стальгорна уже невелика, приструнить этого Вагаша некому.$b$bМожет, тебе хватит отваги для того, чтобы найти и прикончить эту тварь? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но будь $gосторожен:осторожна;, он смертельно опасен.","Добудьте клык Вагаша.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[315]={"Всем портерам портер","Я тут по делу, а дело мое – создать самый лучший портер! Я знаю, что у меня получится, пивоварение – это мое призвание. Надо только найти правильный рецепт...$B$BНа Мерцающем хребте, что к северо-западу отсюда, тролли из племени Мерзлогривов выращивают одну травку, называется звездолист. Они используют ее в странных ритуалах своего племени. Нам она не особенно полезна, но у нее необычный вкус... И я хочу поэкспериментировать с ней при изготовлении пива!$B$BСбор звездолиста может быть опасен, но я хорошо заплачу тебе за все, что ты сможешь \"позаимствовать\" из корзинок с травами в поселении троллей.","Принесите 7 порций звездолиста Регольду Ячменовару в Каранос.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[316]={"<UNUSED 1>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[317]={"Заготовка продовольствия","Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока Сталежар работает с моим танком, не отправишься ли ты на охоту?$B$BМне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова.","Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Толстопузу в Поселок Сталежара.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[318]={"\"Вечное сияние\"","Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку.$B$BРедгольд живет в Поселке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути.$B$BИ... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок.","Возьмите бочонок \"Вечного сияния\" у Регольда Ячменовара в Поселке Пивоваров.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[319]={"Услуга за \"Вечное сияние\"","У меня есть бочонок \"Вечного сияния\", но... не $gмог:могла; бы ты оказать мне услугу? Поселку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко...$B$BМы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты $Gвзял:взяла; это зверье на себя, у нас было бы больше времени на ремесло и пивоварение.","Убейте 6 медведей-ледолапов, 8 старых скальных вепрей и 8 снежных леопардов. Вернитесь к Регольду Ячменовару в Поселок Пивоваров.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[320]={"Возвращение к Толстопузу","Вот твоя бочка \"Вечного сияния\", $n. И спасибо тебе за охоту.","Отдайте бочонок \"Вечного сияния\" пилоту Толстопузу в Поселке Сталежара.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[321]={"Светосталь","Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожженной и потопленной красными драконами во время последней Великой войны.$B$BФлотилия вышла из Лордерона, и с ней шел эльфийский боевой корабль – \"Орлик\". Он вез груз светостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись...$B$BЛадно, краткий исторический экскурс будем считать законченным. \"Орлик\" затонул к югу от Гавани Менетилов. Если найдешь светлосталь, принеси ее мне.","Найдите груз с затонувшего корабля \"Орлик\" в Болотине.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[322]={"Достойное оружие","В Квартале Дворфов Штормграда есть оружейник, мастер по светостали. Зовут его Гриманд Элмор.$B$BМеталл, который ты $gнашел:нашла;, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!","Отнесите сундук со слитками светостали Гриманду Элмору в Штормград.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[323]={"Доказательство силы","Морбент Скверн – могущественный некромант и союзник темных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу.$B$BХрабрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками.","Убейте 15 скелетов-налетчиков, 3 скелетов-лекарей и 3 скелетов-хранителей и вернитесь к Свену.","Не опускай оружия, $C. Главное – не отчаиваться. Отчаяние – первейшее оружие сил зла.",nil,nil,nil,nil,nil}
RUQL_QUESTS[324]={"Утерянные слитки","Вы забрали слиток светостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки. Найдите мурлоков-налетчиков у остова \"Орлика\" и отберите у них светосталь.","Соберите 5 слитков светостали и вернитесь к Глорину Стальному Лбу в Болотину.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[325]={"Вооружен и особо опасен","Вот оружие против твоего врага. $n, иди и сражайся. Удачи тебе, возвращайся со славой!","Принесите Погибель Морбента Свену в Сумеречный лес.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[326]={"<UNUSED>","x","x",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[327]={"<UNUSED>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[328]={"Спрятанный ключ","Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплете одной из книг Ирода обнаруживается маленький латунный ключ.$b$bПовнимательнее изучив записи, вы находите упоминания \"надежного сейфа\". Этот сейф спрятан внутри Схрона, системы пещер позади поселка Курцена.$B$BЕсли найти его, быть может, удастся разрешить загадку обнаружения Торсена.","Откройте сейф букмекера Ирода маленьким латунным ключом.","Сейф окован бронзой. Выглядит он очень прочным и очень тяжелым.","Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи.",nil,nil,nil,nil}
RUQL_QUESTS[329]={"Шпион найден!","Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М.$B$BЯсно одно, ее автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев.","Отнесите грязную записку лейтенанту Дорену в Лагерь Повстанцев.","Тебе удалось выяснить, кому была известна тайна Торсена? Среди нас есть предатель?","Спасибо, $N. Эта записка позволит нам вычислить и уничтожить предателя!",nil,nil,nil,nil}
RUQL_QUESTS[330]={"Расписание дежурств","Принесенная тобой записка подписана просто \"-М\".. Не пойму, что это значит.$B$BНо... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель!$B$BИди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном.","Поговорите с капралом Сетманом.",nil,"А, да, я могу узнать. Посмотрим... на прошлой неделе…$B$B... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств.",nil,nil,nil,nil}
RUQL_QUESTS[331]={"Доклад Дорену","Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?","Поговорите с лейтенантом Дореном в Лагере повстанцев.",nil,"Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена.",nil,nil,nil,nil}
RUQL_QUESTS[332]={"Реклама винного магазина","Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.$B$BВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Даларан нуар\". Не пожалеешь!","Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[333]={"Харлан нуждается в помощи","Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...$B$BА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.$B$BЕсли ты отнесешь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика.","Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.","Вы принесли весточку от мистера Бэгли?",nil,nil,nil,nil,nil}
RUQL_QUESTS[334]={"Посылка для Турмана","Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, |3-6($c) вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать...$B$BПрошу вас, $n! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.","Отправляйтесь в суконную лавку Ларсона в Квартал Магов Штормграда, и передайте Турману Шнайдеру его набор для шитья.","Вы хотите купить одежду?",nil,nil,nil,nil,nil}
RUQL_QUESTS[335]={"Благородный напиток","Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$b$bЕсть один цветочек под названием \"слеза Тиллоа\", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной плотины в Болотине.","Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[336]={"Благородный напиток","У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролет проводит наверху, да еще и не платит по счету. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Черный Коготь\"! С ног сбивает – точно тебе говорю, $n!$b$bОтнеси ему это пойло и посмотри, придется ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей.","Отнесите портер \"Черный коготь\" лорду Вишлоку в Зал просителей.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[337]={"Старинная историческая книга","Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – \"История Штормграда\". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.$B$BПохоже, кто-то взял почитать эту книгу, да так и не вернул...","Вернуть книгу \"История Штормграда\" в библиотеку Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[338]={"Зеленые холмы Тернистой долины","Господин Эрнестуэй так расстроится, когда узнает об этом!$B$BОн доверил мне рукопись романа \"Зеленые холмы Тернистой долины\". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!$B$BБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.$B$BЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.","Соберите все недостающие страницы романа \"Зеленые холмы Тернистой долины\". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[339]={"Глава I","Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $b$bНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!","Принесите 1, 4, 6 и 8 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю первую главу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[340]={"Глава II","Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!$B$BМне удалось собрать почти все, кроме 10, 11, 14 и 16.","Принесите 10, 11, 14 и 16 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю вторую главу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[341]={"Глава III","Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлджедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...","Принесите 18, 20, 21 и 24 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю третью главу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[342]={"Глава IV","А, Глава IV, захватывающий финал! И как она закончилась! $b$bНам не хватает всего лишь трех страниц этой главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.","Принесите 25, 26 и 27 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю четвертую главу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[343]={"Кстати, о стойкости духа","Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.","Отправляйтесь в Королевскую библиотеку крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.",nil,"Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?",nil,nil,nil,nil}
RUQL_QUESTS[344]={"Брат Пакстон","\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.","Поговорите с братом Пакстоном из Аббатства Североземья.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[345]={"Запас чернил","Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья – мой верный поставщик...","Поговорите со старшиной Ослоу из Приозерья и расспросите его о ретбанской руде.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[346]={"Возвращение к Кристофу","Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.","Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу \"Как закалялось железо\".",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[347]={"Ретбанская руда","Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.","Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[348]={"Лихорадка Тернистой долины","Плохо... Мне... т-т-ак п-п-лохо.$B$BЯ п-подцепил... лихорадку Тернистой д-долины... Это смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BИщи знахаря Унбагва в с-с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...","Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[349]={"Лихорадка Тернистой долины","врем текст 02 – описание","врем текст 02 – протокол",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[350]={"Помощь старого друга","Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.","Поговорите с Иллингом Триасом в Штормграде.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[351]={"Найди КПХ-17/TN!","Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.$b$b\"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе\".","Отнесите аварийный маяк к автономному роботу Карлса.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[352]={"<UNUSED>","Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don't think being ready would have helped my cause much. One swipe and poof! Darkness. They say I'm lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you'd like to try yourself against her, the Lady of the Loch,",nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[353]={"Посылка для Грозовой Вершины","Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?$b$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.","Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[354]={"Смерти в семье","Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.","Принесите останки Грегора, останки Ниссы и останки Тармена Колману Фартингу в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[355]={"Разговор с Севреном","Ты $gпринес:принесла; мне останки Агамондов и $gутолил:утолила; мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.","Поговорите с мировым судьей Севреном в Брилле.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[356]={"Патруль в арьергарде","Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.$B$BНаш успех на Бастионе рассчитан на битву на один фронт: мы не можем допустить атаки с тыла и, уж конечно, не можем лишить наших защитников линии поставки припасов.$B$BОтправляйся на запад и убей любого приспешника Плети, которого встретишь. Обрати особое внимание на усадьбу Балнира – там настоящее гнездо этой Плети.","Убейте 8 кровоточащих ужасов и 8 странствующих духов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[357]={"Личность лича","На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он – свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.$B$BНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.$B$BЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.","Принесите книгу лича Бетору Ледострелу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[358]={"Грабители могил","Братские могилы к юго-западу от Фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!$B$BУ тебя будет два задания: убить гноллов-гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.","Убивайте грабителей могил и полукровок из стаи Гнилошкуров.$B$BПринесите мировому судье Севрену 8 образцов бальзамирующей лимфы.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[359]={"Обязанности Отрекшихся","Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.","Поговорите со стражем смерти Линнеей.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[360]={"Возвращение к мировому судье","Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждет ее, так что поспеши.$B$BА если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям.","Вернитесь к мировому судье Севрену в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[361]={"Недоставленное письмо","Это письмо, написанное Тарменом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...","Найдите Иветту Фартинг и вручите ей письмо от Тармена Агамонда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[362]={"Мельницы с привидениями","Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Тармен был высоким и учтивым, а его младший брат – слабым и острым на язык.$B$BКогда Мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к Мельницам Агамондов, до сих пор можно услышать его безумное бормотание.$B$BЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.","Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[363]={"Резкое пробуждение","Ты вовремя $gпришел:пришла; в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. $b$bМеня зовут Мордо, я смотритель склепа Похоронного Звона. А ты больше не $gраб:рабыня; Короля-лича. $b$bПоговори с жрецом Тени Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.$B$BЧтобы выбраться из склепа, поднимайся наверх по ступенькам. Затем следуй вниз по дороге, пока не найдешь часовню.","Поговорите с жрецом Тени Сарвисом.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[364]={"Безмозглые твари","C тех пор, как первый Отрекшийся выполз из своей могилы, мы безостановочно ведем войну с армией Короля-лича. Проклятые мертвецы, мерзкие твари с севера, извращенные создания!$b$bХотя Король-лич больше не восседает на Ледяном троне, северная часть деревни все еще находится под осадой его рабов. Уничтожь их, не щади никого, кем бы они тебе не казались. Это больше не твои павшие братья и сестры.","Убейте 5 безмозглых зомби и 5 презренных вурдалаков.","В этой новой жизни ты далеко не продвинешься, если не в состоянии убить даже самых слабеньких зомби, $N. И не возвращайся, пока не сможешь доложить об успешном выполнении.",nil,nil,nil,nil,nil}
RUQL_QUESTS[365]={"Поля Горя","Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.","Украдите 10 тыкв с западной фермы, к северу от Похоронного Звона. Потом отнесите эти тыквы аптекарю Юхану в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[366]={"Книга Гюнтера","Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.","Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[367]={"Новая чума","Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принесите мне 5 склянок крови пса Тьмы, чтобы я мог провести эксперимент.","Принесите аптекарю Юхану 5 склянок крови псов Тьмы.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[368]={"Новая чума","Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.","Принесите аптекарю Юхану из города Брилл 5 чешуек мурлоков из племени Злобного Плавника из Тирисфальских лесов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[369]={"Новая чума","Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.","Принесите Аптекарю Юхану из города Брилл 4 образца яда злобного ночного кругопряда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[370]={"Война с Алым орденом","В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбейте Перрина, трех фанатиков и трех миссионеров, а потом доложите мне.","Убейте капитана Перрина, 3 ревнителей и миссионеров Алого ордена по просьбе исполнителя Зуганда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[371]={"Война с Алым орденом","У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ усадьбы Балнира.$B$BУбейте Вакона и пятерых келейников из Алого ордена – это должно нанести ордену сокрушающий удар!","Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию палача Зуганда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[372]={"Война с Алым орденом","Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш.$B$BЯ даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Темной Госпожи.","По просьбе палача Зуганда убейте капитана Мелраша и двух его телохранителей.","Вы еще не исполнили свой долг, $C. Мы не можем ожидать выполнения плана Темной Госпожи, когда Алый орден будет докучать нашим солдатам. Заставь их умереть и исполни свой долг перед Сильваной!",nil,nil,nil,nil,nil}
RUQL_QUESTS[373]={"Неотправленное письмо","Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в ратушу на Соборной площади\".$B$BКажется, оно написано совсем недавно, и печать еще свежая...","Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.","Да? Я могу чем-то вам помочь?",nil,nil,nil,nil,nil}
RUQL_QUESTS[374]={"Доказательство верности","Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматас, лейтенант Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять перстней членов ордена в доказательство верности Вариматасу и Темной Госпоже.","Принесите 10 перстней Алого ордена стражу смерти Буржесу в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[375]={"Смертельный холод","Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.","Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[376]={"Проклятые","В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тени Сарвису, какая может потребоваться. $b$bПохоже, и ты будешь $gзаписан:записана; к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.","Obtain 4 Scavenger Paws and 4 Duskbat Wings.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[377]={"Преступление и наказание","Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$b$bВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$b$bУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.","Принесите советнику Миллстайпу руку Декстрена Варда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[378]={"Успокоить Гневливого","Ты $Gдоказал:доказала; свою преданность королю Магни, |3-6($c). И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.$b$bЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длиннокосом. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длиннокоса.$b$bПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, $n. Ради Грима! Принеси мне его голову!","Принесите голову Кама Гневливого Мотли Гармасону в Дун Модр.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[379]={"Утолить жажду","Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе 4711-FTZ.$b$bЗнаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло.","Найдите 5 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск.","Ну как, кочевники поделились с тобой водой?","Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!$B$BКак только соберешь, все, что нужно, принеси эту штуковину мне, чтобы я отключил ее как надо. У тебя не больше двух часов на все про все.$B$BЕсли ты не успеешь, я, конечно, продам тебе еще один источник энергии. Ключевое слово – продам!",nil,nil,nil,nil}
RUQL_QUESTS[380]={"Паучья низина","Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета власти Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.","Палач Аррен хочет, чтобы вы убили 8 молодых ночных кругопрядов и 5 ночных кругопрядов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[381]={"Алый орден","Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь осторожен, нечестивое рвение делает их опасными противниками.","Принесите палачу Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[382]={"Красный гонец","В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.","Убейте гонца Мевена Коргала в лагере Алого ордена, а потом сообщите перехваченные известия палачу Аррену.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[383]={"Важные разведданные","Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Похоронном Звоне, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Похоронного Звона на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\".","Отнесите бумаги Алого ордена палачу Зуганду в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[384]={"Кабаньи ребрышки в пиве","Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабаниной, теперь завербован в королевскую армию, чтобы помочь Альянсу.$B$bМожет, ты мне поможешь? Если принесешь мне немного ребер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!","Принесите 4 нежных свиных ребрышка и кружку \"Болтливого пива\" Рагнару Громовару в Каранос.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[385]={"Охота на кроколисков","Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.$b$bМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.$b$bЯ и сам в свое время...","Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[386]={"Что происходит?","Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.$b$bПоложи конец Таргорру Ужасному, $n. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.","Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[387]={"Подавление бунта","Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.","[Deprecated] Warden Thelwater of Stormwind wants you to kill 10 Prisoners, 8 Convicts, and 8 Insurgents in The Stockade.","Тюрьма по-прежнему под контролем бунтовщиков! Этим крысам из Братства Справедливости нужно показать, что это им даром не пройдет! Возвращайся и задай им жару!",nil,nil,nil,nil,nil}
RUQL_QUESTS[388]={"Цвет крови","Кровь моя стынет в жилах от ужасного горя... Мой внук Мак... он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.$b$bЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...","Принесите Никове Раскол 10 красных шерстяных бандан.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[389]={"Базиль Тредд","ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$b$bЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.","Поговорите с надзирателем Телвотером в тюрьме.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[390]={"<UNUSED>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[391]={"Бунтовщики в тюрьме","Скажу тебе сразу, $n: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо...","Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[392]={"Таинственный посетитель","Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.","Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[393]={"Тень прошлого","Знаете ли, $n, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.","Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[394]={"Голова чудовища","Найди Шоу в Старом городе. Дай ему знать, что с Лесковаром покончено, а тебе все известно о заговоре лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.$B$BДумаю, он отправит тебя на встречу с принцем или другим лордом. Не позволяй им запудрить себе мозги, $n. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.","Поговорите с Матиасом Шоу в Штормграде.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[395]={"Гибель братства","Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.$b$B$n, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.$B$BА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.","Поговорите с Баросом Алекстоном в Штормграде.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[396]={"Аудиенция у короля","Я приготовил доклад для короля. Надеюсь, ты сумеешь преподнести его величеству все в лучшем виде. Не переживай так, король обязательно оценит твое благородное служение народу Штормграда и достойно наградит тебя.$B$BСрок твоей аудиенции близок, так что поторопись, чтобы не опоздать в крепость Штормграда.","Доставьте доклад Бароса Алекстона об уничтожении Братства Справедливости королю Вариану Ринну в крепость Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[397]={"За достойную службу","Я слышал, что Лорд Вишлок в восторге от напитка.$b$b$n, ты нам здорово $Gпомог:помогла;. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.","Поговорите с Згги, слугой Зардета Черного Когтя, чтобы получить награду.",nil,"Хозяин дал подарок для $N. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.",nil,nil,nil,nil}
RUQL_QUESTS[398]={"Разыскивается: Червеглаз","Разыскивается: Червеглаз!$B$BУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла.$B$BГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу.$B$BМилосердие – удел слабых.","Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[399]={"Скромные дары прошлого","It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by transients.$b$bI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.$b$bYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?","Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[400]={"Инструменты для Сталежара","Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!$B$BМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.$B$BТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.","Доставьте инструменты Белдину Сталежару.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[401]={"Ожидание перевода","Я почти закончил работу над переводом записки. Она будет готова через несколько минут.","Подождите немного и снова поговорите с Широй Фон-Инди.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[402]={"Шира занят","Прости, но сейчас трудный момент в жизни нашего города. У меня есть другие дела. Может быть позже, если мы все выживем, я закончу перевод.","Зайдите к Шире и выясните, занят ли он.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[403]={"Охраняемый бочонок Громоваров",nil,nil,nil,"Этот бочонок эля охраняет Ярвен Громовар. Пока он в подвале, до бочек не добраться.",nil,nil,nil,nil}
RUQL_QUESTS[404]={"Грязная работа","Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.$B$BОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.","Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[405]={"Блудный лич","Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, $n, как раз подходишь для этого.$B$BОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о найме заблудшего лича. Это очень опасное дело.$B$BПриготовься как следует, |3-6($c). Не подведи нас.$B$BБетора можно найти в Квартале Магов Подгорода.","Отнесите приказы Севрена Бетору Ледострелу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[406]={"<UNUSED>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[407]={"Поля Горя","Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\". Иди, отнеси ему эту тыкву.","Отнесите отравленную тыкву пленному ревнителю Алого ордена, которого держат в погребе таверны \"Петля Висельника\".",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[408]={"Семейный склеп","Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это Семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.$B$BТы не $gдолжен:должна; допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.$B$BА заодно принеси мне череп капитана Даргола.","Убейте 8 стенающих прародительниц и 8 гниющих предков.$B$BУбейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[409]={"Доказательство преданности","Ты говоришь, что $gнеподвластен:неподвластна; воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе, ты $gдолжен:должна; доказать то, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – враг Короля-лича.","Возьмите манящую свечу.$B$BВызовите Лилит Нефару и убейте ее.$B$BВернитесь на остров к Гюнтеру.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[410]={"Спящая тень",nil,nil,"Это старый, побитый, окровавленный стол.","Вы ставите на стол Манящую свечу и зажигаете ее...",nil,nil,nil,nil}
RUQL_QUESTS[411]={"Возвращение блудного лича","Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.","Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[412]={"Операция \"Перенаправление\"","Мне следует вернуться в Гномреган и продолжить исследования, чтобы найти способ вылечить облученных гномов.$b$bНо я оставался в Караносе, потому что это мой город, и я хотел помочь защитить его от атак Мерзлогривов. Я занимался техобслуживанием и ремонтом паровых танков.$b$bПо какой-то причине падальщики Мерзлогривов стали таскать у меня гиромеханические шестерни, которые нужны для завершения ремонта. Все они на передовой Мерзлогривов. Не поможешь мне вернуть эти шестерни?","Принесите Раззлу Шустрецу 8 гиромеханических шестерней.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[413]={"\"Мерцающий портер\"","Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок \"Мерцающего портера\"?","Отнесите бочонок \"Мерцающего портера\" горному пехотинцу Ячменовару.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[414]={"Портер для Кэдрелла","Я бы и еще отхлебнул \"Мерцающего портера\" с хмелеварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телcамар в озере Лок Модан.$B$BЧтобы добраться до Телcамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телcамара.$B$BОтдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!","Отнести бочонок \"Мерцающего портера\" горному пехотинцу Кэдреллу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[415]={"Новое пиво Регольда","Регольд Ячменовар, что живет в Поселке Пивоваров, спрашивал про тебя.$B$BОн хочет поговорить с тобой про свое новое пиво... Сказал вроде, что ты ему $Gпомог:помогла;. Можешь самолично вернуться в Поселок Пивоваров и спросить, что ему надо.$B$BМожет, тебя дармовая выпивка ждет...","Поговорите с Регольдом Ячменоваром.",nil,"$N! Помнишь тот звездолист, что ты $Gпринес:принесла; мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!$B$BВот, попробуй и скажи, как пошло...",nil,nil,nil,nil}
RUQL_QUESTS[416]={"Ловля крыс","К западу отсюда началось настоящее нашествие. Эти подземные крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$b$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились на востоке отсюда, в районе Серебряных копей.","Принесите 8 ушей туннельщиков горному пехотинцу Грозовой Вершине на станцию Альгаз.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[417]={"Месть пилота","Хилдельв пишет в своем дневнике, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\". Он отогнал тварь, но та успела страшно изранить его.$B$BСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.$B$BВ дневнике Хилдельв записал свое последнее пожелание:$B$B\"Отомстить Паршивому Когтю\".","Убейте Паршивого Когтя.$B$BПринесите его коготь и дневник Хилдельва пилоту Большеногу на заставу у Южных врат.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[418]={"Телcамарские кровяные колбаски","Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужна медвежатина, все остальное уже есть. Добудь ее, а уж Видра сготовит все в лучшем виде!","Принесите Видре Жаркий Очаг в Телcамар 8 кусков медвежатины.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[419]={"Пропавший пилот","Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его машину на крутой холм, там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.","Пилот Большеног с заставы у Южных врат просит вас найти пилота Хилдельва.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[420]={"Наблюдения Сенира","Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться.$b$bЕсли тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе.$b$bА добраться туда и вовсе просто: пройдешь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса.","Доставьте донесение Грелина Сениру Белобороду в Караносе.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[421]={"Проявить себя","Леди Сильвана поручила Вариматасу завоевать земли людей и дворфов к югу. $b$bНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. $b$bМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.","Далар Ткач Рассвета из Гробницы хочет, чтобы вы убили 5 белоголовов Лунной Ярости.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[422]={"Безрассудство Аругала","Для меня загадка, каким образом Аругал вообще был принят в Кирин-Тор. В искусстве магии он был совершеннейший невежда.$b$bСейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать ее против него и обеспечить владычество Темной Госпожи в Серебряном бору. $b$bВначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из ловчих смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудь для меня ту из этих книг, что называется \"Зелье Аругала\".","Раздобудьте книгу \"Зелье Аругала\" и принесите ее Далару Ткачу Рассвета в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[423]={"Безрассудство Аругала","Изучив деятельность Аругала, я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин-Тор в самый трудный час. Идиоты! $b$bДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйся в путь и убивай обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберешь столько заколдованных наручей, сколько потребуется для моих исследований. Эти злобные создания обитают к северу и к востоку отсюда.","Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча чернозлобов Лунной Ярости.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[424]={"Безрассудство Аругала","Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. $b$bНо тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. $b$bЭтот рудник стал бы ценным ресурсом для Вариматаса. $b$bЯ хочу, чтобы вы снесли голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим.","Убейте Мрачнона Белесого и принесите его голову Далару Ткачу Рассвета в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[425]={"Ивар Нечистый","Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. $b$bНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. $b$bУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.","Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[426]={"Нападение на мельницы","Плеть пытается основать базу на Мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.$B$BПоступил приказ уничтожить всю Плеть на мельницах.$B$BОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.$B$BЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.","Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[427]={"Война с Алым орденом","Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.","Убейте 10 воинов из Алого ордена по просьбе палача Зуганда.","Если ты хочешь доказать свою ценность Темной Госпоже, убей 10 воинов из Алого ордена, $C.",nil,nil,nil,nil,nil}
RUQL_QUESTS[428]={"Пропавшие ловчие смерти","Пару недель назад двое наших ловчих смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. $b$bОни могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих ловчих смерти. $b$bИх первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там.","Найдите ловчих смерти Квинна Йорика и Ран Йорик.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[429]={"Звериные сердца","Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $b$bСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $b$bМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.","Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[430]={"Назад к Квинну","Вот зелье, которое должно помочь Квинну Йорику поправиться. $b$bА теперь, простите, мне нужно продолжить одно очень важное дело...","Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[431]={"Манящие свечи",nil,nil,nil,"Вы берете одну свечу и кладете ее в сумку.",nil,nil,nil,nil}
RUQL_QUESTS[432]={"Проклятые трогги!","Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!$b$bОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!$b$bНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!$b$bЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!","Убейте 8 головоломов из племени Каменной Челюсти и 8 костегрызов из племени Каменной Челюсти в карьере Гол'Болар.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[433]={"Слуга народа","Будучи членом Сената и Лиги исследователей, я взял на себя заботу по изучению условий работы в карьере. Трогги совсем распоясались!$b$bОни просто разнесли весь карьер Гол'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и заманивая горняков в подземные ловушки.$b$bМы должны выдворить их оттуда. Мои маги работают сверхурочно, чтобы наложить чары на эти руны возвращения. Если ты сможешь отнести руны захваченным шахтерам, они смогут безопасно вернуться на поверхность.","Раздайте руны возвращения 7 захваченным шахтерам в карьере Гол'Болар.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[434]={"Нападение!","Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем.$B$BПока ты $Gсобирал:собирала; для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.$B$BЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.","Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.","Да, $N? С Тирионом дела идут хорошо? Он проинформировал меня о ситуации, и я помог ему обманом заставить Марзона пойти в замок.$B$BМарзон был занозой для многих людей в Штормграде; многие из которых мои близкие друзья. Никто не ...",nil,nil,nil,nil,nil}
RUQL_QUESTS[435]={"Сопровождая Эрланда","Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. $b$bЯ должен доложиться своей коллеге, ловчей смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.$b$bПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...","Проводите Эрланда, защищая его от волков, к Ран Йорик.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[436]={"Раскопки Сталекрута","Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!$B$BСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.$B$BОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.$B$BЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.","Обратитесь к исследователю Удару Топора.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[437]={"Мертвые поля","Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. $b$bМы хотим уничтожить Плеть Ночи. $b$bОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. $b$bСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.","Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. $b$bКогда появится банши Плеть Ночи, убейте ее. $b$bСущность банши принесите верховному палачу Хадрику в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[438]={"Старая переправа","$n, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. $b$bПолагаю, Плеть захватила это место неспроста. Отправляйся к старой переправе и выясни, в чем там дело.","Отправляйтесь к старой переправе. $b$bПоищите причину присутствия там сил Плети.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[439]={"Необычная находка","Из кучи трупов торчит обнаженная рука. Это рука женщины – тронутая чумой, но относительно свежая. $b$bНа пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: $b$b\"Делии\".","Принесите кольцо Делии верховному палачу Хадрику в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[440]={"Кольцо с гравировкой","Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. $b$bНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.","Отнесите кольцо Делии мировому судье Севрену в Брилл.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[441]={"Роли, который живет в Подгороде","У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. $b$bНайти Роли вы можете в Торговом квартале Подгорода.","Отнесите Роли кольцо Делии.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[442]={"Атака на остров Фенриса","А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. $b$bТы снова $Gдолжен:должна; добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!$b$bЯ посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача, $n. Ты $Gдолжен:должна; выйти $Gпобедителем:победительницей;!","Принесите верховному палачу Хадрику в Гробницу голову Тула Когтя Ворона.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[443]={"Лимфа Гнилошкуров","Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. $b$bОтправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалеку от Гробницы.","Принесите 8 бутылок лимфы Гнилошкуров аптекарю Ренферрелу рядом с Гробницей.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[444]={"Происхождение Гнилошкуров","Я выпарил лимфу, которую ты $gпринес:принесла; мне, и разложил ее на основные компоненты. Мои выводы еще не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. $b$bПока я продолжу ее изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров.$b$bИди же. Бетора ты найдешь в Квартале Магов Подгорода.","Отнесите образец лимфы Бетору Ледострелу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[445]={"Доставка в Серебряный бор","Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и $gсам понял:сама поняла;.$B$BЯ состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Темная Госпожа.$B$BОтнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.","Отнесите находки аптекаря Холланда аптекарю Ренферрелу в Серебряном бору.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[446]={"Тул Коготь Ворона","Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошел в силу Король-лич, Тул предал своих братьев и перешел на сторону Плети. $b$bЯ и не думал, что он все еще жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! $b$bЯ знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья.","Отнесите свиток Бетора аптекарю Ренферрелу в Серебряный бор, в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[447]={"Рецептура смерти","Силы Артаса неисчислимы. Но, создав новую чуму, мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. $b$bМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Оплетающей Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород аптекарю Фаранеллу из Королевского фармацевтического общества.","Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их опытному аптекарю Фаранеллу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[448]={"Доложиться Хадрику","Прежде чем вы нападете на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится.","Доложитесь верховному палачу Хадрику в Гробнице.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[449]={"Отчет ловчих смерти","Хотя раны Квинна заживают, я хотела бы доставить наш отчет верховному палачу Хадрику как можно скорее. В нем содержится информация, которая жизненно важна для захвата Серебряного бора Отрекшимися.","Отнесите отчет ловчих смерти верховному палачу Хадрику в Гробницу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[450]={"Рецептура смерти","Вы можете еще послужить Королевскому фармацевтическому обществу, $n. $b$bКогда Аругал навел на лес свою никчемную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. $b$bРаздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу.","Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[451]={"Рецептура смерти","Согласно записям Берарда, мох озерных тихоступов и озерных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. $b$bОн также упоминает об очень редкой субстанции – твердой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. $b$bСоберите образцы моха, а также редкую твердую опухоль и отнесите их аптекарю Фаранеллу в Подгород.","Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихоступа и твердую опухоль опытному аптекарю Фаранеллу в Подгород.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[452]={"Засада в деревне","Ты очень вовремя $gдобрался:добралась; сюда, $n! $b$bСовет деревни Погребальных Костров вернется в любой момент. Аругалу же есть чем заняться в крепости. Он использует Совет как марионеток, чтобы держать лишенных разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства Совета деревни Погребальных Костров сыны Аругала взбунтовались бы против своего предводителя. $b$bЯ не могу справиться со всем в этим в одиночку. Мне нужна твоя помощь. Вместе мы сможем погубить Cовет к вящей славе леди Сильваны.","Помогите ловчей смерти Фарлии уничтожить Совет деревни Погребальных Костров.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[453]={"Поиски таинственного незнакомца","Удачи, $n. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.","Отыщите незнакомца. Его приметы:$B$BОн родом не из Темнолесья.$B$BОн – нервный тип.$B$BОн сбежал из Темнолесья и двинулся на запад.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[454]={"После засады","До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.","Поговорите с Мираном.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[455]={"Альгазская битва","Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.","Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу из Гавани Менетилов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[456]={"Природное равновесие","Мои приветствия, $N. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия.$b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $GЮный:Юная; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.","Убейте 4 молодых ночных саблезубов и 4 молодых щетинистых вепрей.","Дел еще немало, $N. Возвращайся ко мне, как только сократишь поголовье ночных саблезубов и щетинистых вепрей.",nil,nil,nil,nil,nil}
RUQL_QUESTS[457]={"Природное равновесие","Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, $N, однако нужно выполнить еще некоторую работу.$b$bЛесные ресурсы истощатся слишком быстро, если не решить эту проблему. Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия.","Опекун Илталайн хочет, чтобы вы убили 5 облезлых ночных саблезубов и 5 щетинистых вепрей.","Твоя работа еще не завершена, $N. Возвращайся ко мне после того, как убьешь 5 облезлых ночных саблезубов и 5 щетинистых вепрей.",nil,nil,nil,nil,nil}
RUQL_QUESTS[458]={"Защитница леса","Какая отрада, что ты здесь, |3-6($c). Шепот лесных духов донес до моего слуха странные вести.$b$bТаинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определенно не так, если она вновь появилась в этих землях.$b$bНайди Тариндреллу и узнай, что привело ее в наши рощи. Кто-то из Стражей сообщил о том, что ее видели к юго-западу от Альдрассила.","Найдите дриаду по имени Тариндрелла.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[459]={"Защитница леса","Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги. Они покинули свои дома и объединились в племя Кривой Сосны.$b$bЛишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения. Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины.$b$bНапади на этих бесов, $N, и узнай, действительно ли они подпали под чары зловещего мха Скверны.","Соберите 8 порций мха Скверны и принесите их Тариндрелле.","Помоги мне подтвердить или опровергнуть мои подозрения, $N. Принеси мне 8 кусочков мха Скверны.",nil,nil,nil,nil,nil}
RUQL_QUESTS[460]={"В целости и сохранности","На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... $b$bМеня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! $b$bПожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле.","Отнесите голову Аларика на его могилу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[461]={"Замаскированный тайник","Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! $b$bУглубление в стене находится в юго-западной башне крепости, позади пыльной полки. $b$bВозьмите мое тело, а сапоги оставьте здесь. Они мне все равно не по ноге...","Отнесите Аларика к замаскированной нише.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[462]={"<UNUSED>","Other than you, we sent two scouts through Algaz. Only one returned. Here's what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now. Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz. Menethil is through Algaz, then west along the road.","Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[463]={"Страж Природы","Ты ведь $Gслышал:слышала; рассказы о Страже Природы? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и дядя-сторож может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?","Найдите Стража Природы.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[464]={"Боевые знамена","К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.","Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[465]={"Гамбит Нек'роша","Пока ты $Gсражался:сражалась; с кланом Драконьей Пасти, мы получили сведения об их планах.$B$BНек'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!$B$BУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.$B$BВозьми вот этот трут. Пробейся к катапультам и подожги их.$B$BПосле этого найди и убей Нек'роша. Этот паршивец уже свое отжил...","Уничтожьте катапульты Драконьей Пасти.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[466]={"Поиски огневита","Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!$B$BРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.$B$BАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!","Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[467]={"Найдите Камнекожца","Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.","Поговорите с пилотом Камнекожицем.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[468]={"Отчитайтесь перед горным пехотинцем Рокхаром","Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.","Поговорите с горным пехотинцем Рокхаром.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[469]={"Ежедневная доставка","Привет тебе, $Gстранник:путешественница;!$b$bНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!$b$bНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.$b$bЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.","Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[470]={"Прожорливый слизнюк","Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$b$bЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$b$bА в сумке-то мои вещи!$b$bЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $Gсогласился:согласилась; помочь!","Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[471]={"Тяжкая судьба помощника","Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$b$bЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$b$bЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.","Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[472]={"Падение Дун Модра","Дворфы Черного Железа захватили Дун Модр!$b$bЯ тяжело ранен, |3-6($c). Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.$b$bНаш командир, Длиннокос, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...$b$bОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длиннокос тоже спасся! Иди в Дун Модр и отыщи его, |3-6($r)!","Отыщите Грима Длиннокоса возле Дун Модра.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[473]={"Доклад капитану Крепкому Кулаку","$n. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.","Найдите капитана Крепкого Кулака и поговорите с ним.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[474]={"Убить Нек'роша","Катапульты сожжены. Теперь найди и убей вождя Нек'роша.","Убейте вождя Нек'роша.$B$BПринесите голову Нек'роша капитану Крепкому Кулаку.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[475]={"Ветер тревоги","Ветер тревоги веет над лесом.$b$bГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.$b$bНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.","Найдите Гэроласа Талветрена в Деревне Звездного Ветра.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[476]={"Порча Кривой Сосны","Племя Кривой Сосны поражено порчей!$b$bОни подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.$b$bЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, $Gюный:юная:c; |3-6($c). Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен'этиль!","Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.",nil,"Клянусь звездами! Воистину тревожные вести!",nil,nil,nil,nil}
RUQL_QUESTS[477]={"Пересечение границ","Как вы, должно быть, знаете, в деревне Янтарная мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. $b$bЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной мельницы, показывает, что она имеет немаленькое значение. $b$bОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.","Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.",nil,"*С любопытством открыв крышку ящика, вы находите в нем множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона.$b$bПод картами обнаруживается подвеска таинственно-волшебного вида.*",nil,nil,nil,nil}
RUQL_QUESTS[478]={"Карты и руны","*Вы быстро вытаскиваете подвеску из сундука и кладете крышку на место.*","Отнесите странную подвеску темному жрецу Алистеру в Гробницу.","Узнали что-нибудь полезное, $N?","Карты и эта... эта подвеска? Интересно.$b$bОчевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остается неизвестной.$b$bМожет быть, Далар сможет выяснить, что они там ищут.",nil,nil,nil,nil}
RUQL_QUESTS[479]={"Расследование в Янтарной мельнице","Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путем... $b$bМаги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. $b$bЧтобы добраться до Янтарной мельницы, идите на юг по главной дороге, а на развилке сверните на восток.","Добудьте 8 подвесок Даларана и отнесите темному жрецу Алистеру в Гробницу.","Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.","Далар выяснил, что несмотря на замедление, процесс плетения чар зашел уже далеко.$b$bНекий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить.",nil,nil,nil,nil}
RUQL_QUESTS[480]={"Ткач","Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $b$bВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.","Убейте даларанского верховного мага, заберите его посох и отнесите темному жрецу Алистеру в Гробницу.","Быстрее, время на исходе, $N!","Магия волшебников рассеивается, и энергетические узлы вновь засыпают. Ваши усилия оказались плодотворными, $N, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьезный удар.$b$bОднако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее.",nil,nil,nil,nil}
RUQL_QUESTS[481]={"Анализ Далара","Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.","Отнесите подвеску рунической надписи Далару Ткачу Рассвета в Гробницу.","Слушаю вас, |3-6($C). Что это?","Интересно – похоже, новые махинации Кирин Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин Тора для передачи магической энергии.$b$bТо, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьезное.$b$bПосмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях.",nil,nil,nil,nil}
RUQL_QUESTS[482]={"Планы Даларана","Конечно! Как же я мог забыть?$b$bЯнтарная мельница была одним из мест, отмеченных магами Кирин-Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьезной цели. $b$bМы не можем позволить этому случиться... $b$bЧтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. $b$bПередайте эту информацию Алистеру, он спланирует дальнейшие действия.","Поговорите с темным жрецом Алистером в Гробнице.",nil,"Вы принесли тревожные вести, $N. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро.$b$bМне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс.",nil,nil,nil,nil}
RUQL_QUESTS[483]={"Реликвии Пробуждения","Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там все подряд.$b$bСпящие друиды могут так никогда и не выйти из Изумрудного Cна, так и не поняв, в какую западню угодили, если мы только им не поможем. Тонкий ритуал сна нельзя нарушить без реликвий Пробуждения.$b$bОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.","Добудьте реликвии Пробуждения.","$N, похищенные друиды-вороны навеки останутся в ловушке Изумрудного Сна, если мы не сумеем добыть реликвии Пробуждения из обители Бен'этиль, что на западе отсюда.$b$bЧем дольше мы медлим, тем неизбежнее их рок.","Тебе удалось это сделать, $Gюный:юная; |3-6($C)! Славно! И как раз вовремя.",nil,nil,nil,nil}
RUQL_QUESTS[484]={"Шкуры молодых кроколисков","Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!$b$bУже $gвстречался:встречалась; с Эйнаром? Он – один из охотников, приносящих мне шкуры.$b$bВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$b$bУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.","Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.","$N, я ведь тебя посылал за шкурами? Где же они?","Отлично, превосходно! Прекрасные шкуры, $N! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя еще об одной услуге. Думаю, ты справишься.",nil,nil,nil,nil}
RUQL_QUESTS[485]={"Найти КПХ-9/HL!","Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:$B$B\"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение\".$B$B\"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы\".","Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.","Больше всего это похоже на обломки... механического цыпленка. Изнутри яйца снова раздается голосок: 'Да, отличная работа! Это мой автономный робот. Сенсоры показывают, что без подзарядки он не заведется и не долетит в Пиратскую бухту на починку... Иди вперед и положи маяк в робота – дальше он сам все сделает!'","Вы помещаете яйцевидный аварийный маяк в механического цыпленка.$B$BС гудением и жужжанием робот поднимается на ноги, после чего из его механических внутренностей слышится голос Карлса:$B$B\"Что ж, по крайней мере, OOX-09/HL работает, но ему требуется капитальный ремонт! Он тяжелый, и нести его ты не сможешь, но вообще у меня есть одна мысль... Не хочешь ли присмотреть за ним еще немного?\"",nil,nil,nil,nil}
RUQL_QUESTS[486]={"Урсал Изверг","Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, $n, их сон станет вечным.$b$bЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена.$b$bЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Иди по дороге на северо-запад, потом поверни на север к Расселине. Там будет логово Урсала.","Убейте Урсала Изверга.","Наши сородичи не смогут пробудиться, пока Урсал Мучитель не будет повержен, $N.","$N, ты проявил себя как весьма $Gдостойный:достойная; и $Gспособный:способная;) |3-6($C). $R, следующий путем чести столь же неустанно, как ты, обязательно обретет великую славу в этом мире.$b$bДа будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия.",nil,nil,nil,nil}
RUQL_QUESTS[487]={"Дорога в Дарнас","Дорогу в Дарнас нужно охранять. Путники, направляющиеся из Доланаара в Дарнас, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.$b$bКаждый день из Дарнаса и в Дарнас не доходят грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.$b$bВозьмись же за оружие во имя священного леса, |3-6($c). Их логово находится где-то над этой северной дорогой. Убей душителей из племени Кривой Сосны и возвращайся ко мне.","Убейте 8 душителей из племени Кривой Сосны.","На дороге все еще неспокойно, |3-6($C). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.","Ты славно $Gпослужил:послужила; доброму народу Доланаара и Дарнасса, $Gотважный:отважная; |3-6($C). От имени всех часовых Тельдрассила воздаю тебе хвалу.",nil,nil,nil,nil}
RUQL_QUESTS[488]={"Просьба Зенна","Вижу, ты работенку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце $Gнаивному юнцу:наивной девчушке;... вроде тебя.$b$bВидишь ли, $N, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.$b$bМне часто бывают нужны определенные... реагенты. Принеси 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.$b$bИ пусть это все останется между нами, |3-6($r).","Принесите Зенну Грязному Копыту, 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.","Ну что, $N, не $Gзапыхался:запыхалась;? А я все думал, когда же ты принесешь то, что мне нужно…","Ха-ха! Хорошая работенка!$b$bКто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать |3-6($c)? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей.$b$bОбманули дурака на четыре кулака!",nil,nil,nil,nil}
RUQL_QUESTS[489]={"Искупление вины","Совет Леса узнал, что ты $Gпомог:помогла; Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как |3-6($r),\n\n $Gдолжен бы:должна бы; понимать, что оскверняешь лес, убивая созданий Природы!$b$bТы $Gдолжен:должна; искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! $b$bПреподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зеленый дым.$b$bСкорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.","Соберите 3 шишки Скверны.","Ой, $N, ты мне что-то $Gпринес:принесла;? Видать, что-то вкусненькое?","Ну что ты за лапочка! Я знал, что ты мне еще пригодишься!",nil,nil,nil,nil}
RUQL_QUESTS[490]={"<UNUSED>","By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.","Шейла Ночной Бриз у ворот Дарнаса просит принести ей 20 клыков фурболгов из племени Кривой Сосны.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[491]={"Жезл для Бетора","Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трех принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел ее, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса.$b$bЗдесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить.","Отнесите Сплетенный жезл Бетору Ледострелу в Квартал Магов Подгорода.","$N, ты $Gсразил:сразила; Тула Когтя Ворона?","... Что это?! У Туле был наш Сплетенный жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу!$b$bДолжно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал. И хорошо, что Тул не использовал жезл...$b$bЭто удивительная находка. Я признателен за нее, $N, и вознагражу тебя.",nil,nil,nil,nil}
RUQL_QUESTS[492]={"Новая чума","Один из стражей смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Обычно стражи смерти сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный прием\".$B$BПочему бы тебе не пойти и не угостить пленника специальным напитком, который я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота.","Отнесите особый напиток Юхана пленному горному пехотинцу.","Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!","Ах, наконец-то питье! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло.",nil,nil,nil,nil}
RUQL_QUESTS[493]={"Путешествие в предгорья Хилсбрада","Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. $b$bПоэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. $b$bНаправляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!","Отнесите находки аптекаря Ренферрела аптекарю Лидону в деревню Мельница Таррен в предгорьях Хилсбрада.","У вас ко мне какое-то дело?","А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы.",nil,nil,nil,nil}
RUQL_QUESTS[494]={"Время нанести удар","Молчи и слушай, |3-6($c).$B$BМеня направили сюда для наблюдения за Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что ловчая смерти Леш передала следующие слова:$B$B\"Крик ворона на западе манит.\"$b$bСтупай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной поспешностью!","Отправляйтесь в Мельницу Таррен и доставьте послание ловчей смерти Леш верховному палачу Дарталии.",nil,"Крик ворона на западе манит?$b$bОтличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматрас будет доволен.",nil,nil,nil,nil}
RUQL_QUESTS[495]={"Корона Воли","Муг'тола и его отряд огров отправили в Альтеракскую долину за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.$B$BЕго необдуманный поступок привел к неприятным последствиям. Корона Воли позволила Муг'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.$B$BТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.","Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада.",nil,"Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймешь, что я не терплю пустой болтовни.$b$bМуг'тол – наглец, и с ним мы разберемся быстро, тщательно и безжалостно.",nil,nil,nil,nil}
RUQL_QUESTS[496]={"Эликсир Страдания","Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $n.$b$bЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.","Аптекарь Лидон из Мельницы Таррен попросил принести ему 10 языков серых медведей и немного лимфы паука-охотника.","Я вижу, ты $Gвернулся:вернулась;. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.","Отличные компоненты. Что ж, $N, ты $Gумудрился:умудрилась; внести хоть немного радости в мой тоскливый день. Благодарю тебя.",nil,nil,nil,nil}
RUQL_QUESTS[497]={"<UNUSED>","As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.","Go to Tarren Mill and find out the status of the party sent by Thrall.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[498]={"Спасение","Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог'тара, освободи их.","Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.","Ты $Gдолжен:должна; поторопиться, $C. Мне страшно подумать, что люди могут сделать с Друллом и Тог'таром.","Значит, люди собирались поработить наших воинов? Мы еще им покажем!$b$bПохоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он…$b$bКогда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе, $N.",nil,nil,nil,nil}
RUQL_QUESTS[499]={"Эликсир Страдания","Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания.$B$BВот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир.$B$BПосмотрим, достигнут ли желанный эффект.$b$bДай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети.","Дайте Ампи эликсир Страдания.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[500]={"Награда Раздробленного Хребта","Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалеку от разрушенного города. Разведчики доносят, что они и сами руины захватили.$B$BМы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!$B$BСтупай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные кости, которые они таскают с собой, и получишь неплохую награду.","Соберите 9 грязных костей у огров из клана Раздробленного Хребта в Альтеракских горах. Принесите их маршалу Редпату в Южнобережье.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[501]={"Эликсир боли","О, $n... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!$B$BНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.","Принесите 10 сосудов крови горного льва аптекарю Лидону из Мельницы Таррен.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[502]={"Эликсир боли","Ах, ничто так не радует, как запах свежей крови в предгорьях!$b$bСмешаем капелюшку этого и щепотку того, и пойдет веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать.$b$bОтнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое \"угощение\" понравится собачке фермера Рея, Стэнли.","Напоите Стэнли эликсиром Боли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[503]={"Гол'дир","Судя по добытым тобой документам, Гол'дира держат на большой базе Синдиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его.","Освободите Гол'дира и возвращайтесь к Круску в Мельницу Таррен.","Дай мне ключ, |3-6($C), и я сам отомкну замок.","Спасибо, $N. По приказу Вождя я вел экспедицию из Дуротара, но, как видишь, наши планы несколько нарушились. Меня держали в плену в этом городе, заставляя работать – таскать тяжести и копать…$b$bВпрочем, неважно, что мне пришлось вынести. Куда важнее сведения, которые тебе необходимо доставить тем, кто сейчас возглавляет нашу группу.",nil,nil,nil,nil}
RUQL_QUESTS[504]={"Наемники клана Раздробленного Хребта","Ты уже $gпомерился:померилась; силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар...$B$BСтупай в руины Альтерака и отыщи там наемников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.","Убейте 10 солдат-наемников из клана Раздробленного Хребта и возвращайтесь к маршалу Редпату в Южнобережье.","Тебе нужно убить больше солдат-наемников, $N. Выполняя свою задачу, вы должны быть в горах, а не здесь с оружием в руках.","Очень хорошо. Вот награда.$b$bКстати, охотясь на огров ты видел город Альтерак. Как он выглядит? Боюсь, что скверно. Огры не славятся своей чистоплотностью.$b$bК счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья.",nil,nil,nil,nil}
RUQL_QUESTS[505]={"Убийцы из Синдиката","Меня недавно назначили мировым судьей в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.$b$bЛагеря Синдиката расположены на Возвышенности Соферы и на Кинжале Коррана, на севере и на западе от захваченной Ордой Мельницы Таррен. Убей всех союзников Синдиката, которых встретишь в этих лагерях.","Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к мировому судье Генри Малебу в Южнобережье.","Я полагаю, вы убили этих головорезов Синдиката?","Спасибо, $N. Хотя, быть может, они все еще шныряют неподалеку, будем надеяться, что некоторые из убитых воров и бандитов принимали участие в убийстве прежнего чиновника. Но даже если и нет, Синдикат – позор этой земли и человеческой расы.$b$bСмерть этих бандитов и воров – добрая весть для всего Южнобережья.",nil,nil,nil,nil}
RUQL_QUESTS[506]={"Наследие Блэкмура","День или два назад ко мне пришел главарь этого Синдиката. Его звали Алиден Перенольд, и он нарек себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур.$B$BКуда важнее то, что он привел с собой свою любовницу, девочку-тростинку по имени Элайза. У нее на шее висело ожерелье, который жаждет заполучить Вождь.$B$BСтупай, мне пора уходить, когда я закончу свои дела в лагере.","Отнесите собранные Гол'диром сведения Круску на мельницу Таррен.",nil,"Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются!$b$bОтныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь.",nil,nil,nil,nil}
RUQL_QUESTS[507]={"Лорд Алиден Перенольд","Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, $n, добыть медальон для Вождя и вернуться сюда.","Убейте лорда Алидена Перенольда и допросите его любовницу Элайзу насчет ожерелья Тареты.","Ч-что вам нужно?","Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!",nil,nil,nil,nil}
RUQL_QUESTS[508]={"Подарок Тареты","Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нем... Просто оставь меня в покое...","Верните ожерелье Тареты Круску в деревню Мельница Таррен, что в Предгорьях Хилсбрада.","А, вот и ты, $N. Сопутствовала ли тебе удача?","Странно, что вождь пошел на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично $Gпоработал:поработала;, $N, и я не сомневаюсь, что вождь будет рад услышать о твоем успехе.",nil,nil,nil,nil}
RUQL_QUESTS[509]={"Эликсир агонии","Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга.$B$BУвы, Темная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране.$B$BВот мой план: иди-ка ты во Владение Нетандера на юге от Мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне 6 цветков Грязного Рыла для нового эликсира.","Принесите 6 цветков Грязного Рыла аптекарю Лидону из Мельницы Таррен.","Как дела во Владении Нетандера?","А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся.",nil,nil,nil,nil}
RUQL_QUESTS[510]={"Зловещие планы","Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд).$B$BВпрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить все необходимое следует как можно скорее, чтобы \"выполнить важную миссию, нацеленную против Южнобережья\".","Отнесите зловещие планы мировому судье Южнобережья Малебу.","$N, вид у тебя обеспокоенный. Ты хочешь о чем-то рассказать?","*Малеб изучает документы.*$b$bДурные вести, $N. Судя по сведениям, содержащимся в этих документах, и последним действиям Синдиката, эта банда головорезов объявила войну Южнобережью.",nil,nil,nil,nil}
RUQL_QUESTS[511]={"Зашифрованное письмо","Одно из писем на столе зашифровано.","Отнесите зашифрованное письмо хранителю мудрости Диббсу в Южнобережье.","Да, $Gгосподин:госпожа;? У тебя какое-то дело ко мне?","Что это? Минуточку... Дай-ка взглянуть поближе.$B$B...$B$BХм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ.",nil,nil,nil,nil}
RUQL_QUESTS[512]={"Благородные смерти","Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы.$b$bОтправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката.$b$bНам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить.$B$BПринеси мне эти перстни.","Принесите 7 альтеракских перстней-печаток мировому судье Малебу в Южнобережье.","Как охота на сторонников Синдиката? Где их перстни?","Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников.$b$bТы хорошо послужил Альянсу, $N.",nil,nil,nil,nil}
RUQL_QUESTS[513]={"Эликсир агонии","Я уже решил, что еще один день пройдет без капли радости, но тут ты $gпринес:принесла; мне цветки Грязного Рыла.$b$bДля начала я приготовлю из них отличную смесь. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнется!$b$bВот возьми этот состав Грязного Рыла и немедленно отнеси его аптекарю Фаранеллу.","Отнесите смесь из цветков Грязного Рыла опытному аптекарю Фаранеллу в Подгород.","Видишь, я занят, |3-6($C)? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!","Тебя послал аптекарь Лидон? Что ж ты сразу не $Gсказал:сказала;!$b$bНевзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников.$b$bОн прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Темная Госпожа порадуется наступлению новой чумы.",nil,nil,nil,nil}
RUQL_QUESTS[514]={"Письмо Грозовой Вершине","У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от Пика Черной горы, то это он.","Отнесите хитро зашифрованное письмо геологу Грозовой Вершине в Стальгорн.","Тебя прислал Диббс из Южнобережья? Как поживает старый книжный червь?","А, шифровка! Да, тут я спец. Дай-ка взглянуть...",nil,nil,nil,nil}
RUQL_QUESTS[515]={"Эликсир агонии","Смесь из цветков Грязного Рыла? Гениально! Почему мне не пришло это в голову?$B$BПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.$b$bЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!","Отнесите микстуру из цветков Грязного Рыла, крепкое зелье тролльей крови, 5 чешуек нагов из клана Пронзающего Гребня и 5 глаз мурлоков из клана Рваный Плавник аптекарю Лидону в Мельницу Таррен.","Я рад, что ты $Gвернулся:вернулась;, $N. Я уж совсем заскучал. Ни единого развлечения, сижу, травлю и заражаю Ампи, а потом воскрешаю ее. И так целый день.$b$bКак прошло путешествие в Подгород? Тебе удалось зарубить по дороге человечка-другого?","У меня даже голова закружилась от возбуждения! Какой эксперимент! Ты мне очень $Gпомог:помогла;, $N. Мы будем сеять болезнь и смерть по всем этим землям!",nil,nil,nil,nil}
RUQL_QUESTS[516]={"Погибель Берена","Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $b$bК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $b$bЯ полагаюсь на твою изобретательность. Отыщи их и нанеси им сокрушительный удар.","Найдите Погибель Берена, убейте 6 чернорабочих Когтя Ворона и 6 стражей Когтя Ворона, а затем вернитесь в Гробницу к темному жрецу Алистеру.","Ты уже обнаружил их базу, $N? Время не терпит!","Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича.",nil,nil,nil,nil}
RUQL_QUESTS[517]={"Эликсир агонии","Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны.$B$BСтупай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфишки. Укради у них бочонок \"Землекопского портера\". Получив его, я устрою веселую вечеринку!","Принесите бочонок \"Землекопского портера\" аптекарю Лидону из Мельницы Таррен.","Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.$b$bНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!","Наконец-то! Теперь мы готовы действовать!",nil,nil,nil,nil}
RUQL_QUESTS[518]={"Корона Воли","Муг'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не проредить сначала ряды огров.$B$BА уж потом мы продолжим.$B$BЯсно? Отлично. Выполняй.","Убейте 10 извергов из клана Раздробленного Хребта по поручению Мелизары из Мельницы Таррен.","Я вижу, что задание все еще не выполнено, $N. Сообщить ли мне Шарлиндре о твоей непригодности?","Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег.",nil,nil,nil,nil}
RUQL_QUESTS[519]={"Корона Воли","Тарг, Навозер и Гломмус – лейтенанты Муг'Тола. Они верны ему, хотя кто там разберет, что вынуждает огров быть верными.$B$BПринеси мне их головы, $n, и нам останется отрубить башку Муг'Толу вместе с короной.","Убейте Тарга, Навозера и Гломмуса и принесите их головы Мелизаре из Мельницы Таррен.","Мне нужны их головы, а не оправдания.","...а я-то думала, что для начала огры зверски воняют.$b$bКогда ты принесешь мне голову Муг'Тола, я прикажу отнести ее вместе с этими на пики Альтерака. Неплохой памятник тем, кто идет против воли Темной Госпожи.",nil,nil,nil,nil}
RUQL_QUESTS[520]={"Корона Воли","Лейтенанты Муг'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждет тебя, учитывая... уменьшение числа его товарищей.$B$BОтыщи Муг'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта.","Убейте Муг'Тола и принесите его голову и корону Воли Мелизаре на мельницу Таррен.","Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг'Тола, или твоя. Уж поверь мне на слово.","Ты с честью $Gвыполнил:выполнила; свой долг, $N. Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта.",nil,nil,nil,nil}
RUQL_QUESTS[521]={"Корона Воли","Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже не думай воспользоваться ей в личных целях, $n. Пусть тебе послужит уроком судьба Муг'Тола.","Отнесите корону Воли Шарлиндре из Подгорода.","Да? О чем ты хочешь доложить?","Так значит, этой реликвией воспользовался огр, чтобы не исполнять волю Темной Госпожи…$b$bСтранно, когда в такой небольшой вещи заключается великая сила. Которая попала в такие неуклюжие руки. Молодец, $N. Я отнесу корону леди Сильване и доложу ей о твоих подвигах.",nil,nil,nil,nil}
RUQL_QUESTS[522]={"Контракт убийцы","Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца.","Отнесите контракт убийцы мировому судье Малебу в Южнобережье.","Я смотрю, ты тяжело дышишь! Есть, о чем доложить?","<Малеб изучает контракт.>$B$BТеперь мне понятна подоплека последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!",nil,nil,nil,nil}
RUQL_QUESTS[523]={"Смерть барона","Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон.$B$BОтыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда.","Принесите голову барона Вардуса мировому судье Малебу в Южнобережье.","Пусть барон Вардус не надеется, что Южнобережье возволит ему безнаказанно подсылать к нам своих головорезов. Мне нужна его голова!","Спасибо, $N. У меня на душе полегчало, когда ты $Gвышиб:вышибла; дух из этого злодея!",nil,nil,nil,nil}
RUQL_QUESTS[524]={"Эликсир агонии","За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.$B$BПора устроить этим фермерам вечеринку. Ох, повеселимся!$B$BПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!","Поставьте гниющий бочонок на ковер для плененных фермеров.","От ковра идет гнилостный запах.","Вы ставите гниющий бочонок на пыльный ковер.",nil,nil,nil,nil}
RUQL_QUESTS[525]={"Все больше тайн","Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.","Доставьте расшифрованное письмо мировому судье Южнобережья Малебу.","$N. Вы шли через предгорья и по горам? Какие вы принесли вести?","<Малеб читает письмо.>$B$BЭто расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом.$B$BПохоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть.",nil,nil,nil,nil}
RUQL_QUESTS[526]={"Слитки светостали","Ты $Gнашел:нашла; только один слиток светостали – этого не хватит, чтобы выковать что-нибудь стоящее.$B$BВернись и поищи еще слитки. Думается, их растащили мурлоки, разграбившие корабль.","Найдите 5 слитков светостали и вернитесь к Глорину Стальному Лбу в Болотину.","Вы нашли нужное железо?","А, ты $Gнашел:нашла; их! Теперь давай эту светосталь скуем в что-нибудь полезное?",nil,nil,nil,nil}
RUQL_QUESTS[527]={"Битва за Хилсбрад","Когда говоришь со мной, стой по стойке \"смирно\", |3-6($c).$b$bЯ нахожусь под прямым командованием Сильваны. Наша задача – сдерживать распространение чумы среди людей, покуда аптекари работают над составом новой чумы.$b$bПо нашим сведениям город Хилсбрад очень уязвим. Твое первое задание – прервать снабжение едой и прочим.$b$bОтправляйся на запад. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.","Убейте 6 хилсбрадских батраков, 6 хилсбрадских фермеров, фермеров Рея и Гетца и возвращайтесь к Дарталии которая ждет вас на мельнице Таррен.","Как Верховный палач мельницы Таррен, ты подчиняешься мне по прямому приказу Вариматраса и Темной Госпожи.$b$bМожет быть, ты относишься к этой войне с Альянсом слишком легкомысленно? В таком случае, я должен отрубить тебе голову прямо здесь и сейчас. В противном случае – отправляйся на запад, в Хилсбрад, и сражайся с людьми, как было приказано.$b$bСвободен.","Вольно, |3-6($C). Вижу, ты $Gвернулся:вернулась; из боя. Мне доложили, что ты хорошо $Gпоказал:показала; себя в Хилсбраде.",nil,nil,nil,nil}
RUQL_QUESTS[528]={"Битва за Хилсбрад","Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно.$b$bНаши ловчие смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели.$B$BПокажи им, как они заблуждаются, $n. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Темной Госпожи.$b$b$gСвободен:Свободна;!","Убейте 15 хилсбрадских крестьян и вернитесь к Дарталии на мельницу Таррен.","У тебя есть заказы, |3-6($C). Перестань бездельничать здесь, на мельнице Таррен, когда есть работа в другом месте.","Смерть все крепче сжимает костлявую руку на горле Хилсбрада. Битва идет хорошо.",nil,nil,nil,nil}
RUQL_QUESTS[529]={"Битва за Хилсбрад","Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения.$B$BУбей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье.","Убейте кузнеца Верринтана и 4 хилсбрадских учеников кузнеца.$B$BПринести партию железа Дарталии на мельницу Таррен.","Удалось ли тебе выполнить приказ, |3-6($C)? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?","Задание выполнено, |3-6($C). И, надо сказать, выполнено на славу.",nil,nil,nil,nil}
RUQL_QUESTS[530]={"Месть мужа","Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьешь Валдреда и принесешь мне его проклятые руки, я тебя награжу.$B$BПо последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гилнеас.","Убейте Валдреда Морая.$B$BПринесите его руки Роли Андреану в Подгород.","Где его руки, $N?","А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты $Gстал:стала; моим оружием.$b$bВозьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга.",nil,nil,nil,nil}
RUQL_QUESTS[531]={"Месть Вайрины","Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$b$BСкорее убери ее отсюда! Никому здесь не нужны твои страхолюдные трофеи!","Принесите голову Старины Черношкура Вайрине Быстрый Ветер в Приют странников.","Молодец, $N! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.","Спасибо, что $Gпомог:помогла; мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюбленного мальчишку, а теперь нам это удалось! Вот, возьми, ты это $Gзаслужил:заслужила;.",nil,nil,nil,nil}
RUQL_QUESTS[532]={"Битва за Хилсбрад","В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, мирового судью Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.","Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.","Какие вести ты несешь?","Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, |3-6($C).",nil,nil,nil,nil}
RUQL_QUESTS[533]={"Шпионская работа","Наконец-то до нас дошли сведения о местопребывании Гол'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда.$b$bСтупай туда, $n, и заполучи все доступные сведения.","Добудьте сведения о местонахождении Гол'дира для Круска из Мельницы Таррен.","Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол'дира все меньше и меньше...","Наконец-то мы знаем, где держат Гол'дира. В лагере неподалеку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох.",nil,nil,nil,nil}
RUQL_QUESTS[534]={"<UNUSED>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[535]={"Валлик","Гр-рр... Раненый, умирающий, но не опускающий оружия.$b$bНе сомневаюсь, ты все равно убьешь меня, но если ты принесешь мне немного южнобережского портера – вы ведь такое тоже пьете? – я расскажу тебе то, что ты хочешь знать.","Принесите кружку южнобережского портера Валлику в лагерь Синдиката.","Так что, ты $Gпринес:принесла; мне чего-нибудь выпить или $Gпришел:пришла; просто покончить со мной?","Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это все равно не понадобится.$b$bНу, слушай!",nil,nil,nil,nil}
RUQL_QUESTS[536]={"На побережье","Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!$b$bДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!$b$bЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.","Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.","Еще кружку эля, пожалуйста, последняя будто испарилась!$b$bСвет во тьме, сколько же еще мне тут торчать?$b$bОх, это ты, $N. Ты уже $Gубил:убила; тех мурлоков?","Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!",nil,nil,nil,nil}
RUQL_QUESTS[537]={"Темный совет","Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу.$B$BОтыщи Нагаза и упомянутых в письме темных магов Недремлющего Аргуса. Найди их и убей.$B$BИщи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего.$B$BЕсли повезет, ты найдешь там послов Недремлющего Аргуса.","Убейте 4 темных магов Недремлющего Аргуса.$B$BПринесите голову Нагаза мировому судье Южнобережья Малебу.","Удалось ли найти послов Недремлющего Аргуса?","$GМолодец:Умница;, $N. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату.$B$BХотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту.$B$BИли по всему миру.",nil,nil,nil,nil}
RUQL_QUESTS[538]={"Южнобережье","Доброго дня вам, $n. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.$B$BВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.$B$BЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...","Поговорите с Хранителем мудрости Диббсом в Южнобережье.",nil,"Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров...$b$bИ он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!$b$bТеперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры...",nil,nil,nil,nil}
RUQL_QUESTS[539]={"Битва за Хилсбрад","Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там.$B$BХотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник.$B$BРудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок.","Убейте штейгера Бондса и 10 хилсбрадских шахтеров и доложите о проделанной работе Дарталии, которая ждет вас на мельнице Таррен.","Тебе был дан прямой приказ атаковать Лазурную шахту. Надеюсь у тебя веская причина, по которой ты слоняешься по Мельнице Таррен, или я обезглавлю тебя за измену.","Темная Госпожа будет рада услышать, что у нее появился новый рудник, который поможет вооружить ее бойцов.",nil,nil,nil,nil}
RUQL_QUESTS[540]={"Сохранение знаний","Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси все, что можно!$B$BСтупай в руины Альтерака и поищи там фолианты, украденные ограми. Собери все, что сможешь и принеси мне. Больше всего меня интересует одна книга – \"Рука Гри'лека\". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака.","Найдите 5 фолиантов и потертую кожаную книгу, называемую \"Рука Гри'лека\", и принесите их хранителю мудрости Диббсу в Южнобережье.","Жаль, что я сам не могу поискать в руинах, но боюсь, старые кости не выдержат пути вверх по горам. А у тебя как идут поиски знаний, $N?","А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри'лека\".",nil,nil,nil,nil}
RUQL_QUESTS[541]={"Битва за Хилсбрад","Дворфы пришли на помощь людям? Проклятые мелкие твари!$B$BЧто ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях.$B$BОни построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовется Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, |3-6($c). Глава дворфов, капитан Железный Холм, должен умереть.","Отправляйтесь в Дун Гарок и убейте 8 горных пехотинцев, 4 стрелков, 2 жрецов и капитана Железный Холм. После возвращайтесь к Дарталии на мельницу Таррен.","Дун Гарок тебе не по зубам, а? А я-то думала, ты $Gдоказал:доказала; свою доблесть в Хилсбраде.$b$bЕсли ты не в силах выполнить это задание, я найду другого, кто достигнет цели. Что до тебя — не сомневаюсь, Темной Госпоже не помешают новые гробокопатели в Тирисфальских лесах.","Твои подвиги на поле битвы достойны высочайшей хвалы.",nil,nil,nil,nil}
RUQL_QUESTS[542]={"Возвращение к Милтону","Мне понадобится время на изучение \"Руки Гри'лека\", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда.$B$bВот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен.","Отнесите фолианты Альтерака Милтону Снопу в Штормград.","$N, вы вернулись! Как ваша миссия в Альтераке? Вы что-нибудь принесли?","О небо! Глазам своим не верю! Неужели они пережили падение Альтерака? И всех этих огров!$b$bСпасибо, $N. Огромное спасибо! Вы помогли нам сохранить человеческие знания, и прибавили великолепия Королевской библиотеке Штормграда.",nil,nil,nil,nil}
RUQL_QUESTS[543]={"Тиара Перенольда","Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.$B$BКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел'борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.$B$BМы надеемся, что вы отыщете тиару.","Найдите тиару Перенольда.","Приветствую, $N! Постарайтесь не наступить мне на отвороты брюк, костюмчик только что от портного.","О, чудесно. Конечно, тиару нужно почистить, но вы, $N, прямо-таки превзошли сами себя. Я велю привести тиару в порядок и немедленно помещу ее в нашу сокровищницу.$b$bПримите мою благодарность за пополнение коллекции семейных реликвий.",nil,nil,nil,nil}
RUQL_QUESTS[544]={"Взлом тюрьмы","Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрекшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что еще хуже... они украли кое-что у Темной Госпожи.$B$BЭти воры вломились в надежное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты.$B$BВоры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках.","Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянью Бездны в Мельницу Таррен.","Удалось ли найти воров? И что куда важнее, вернуть похищенное?","Ты $Gоказал:оказала; Отрекшимся огромную услугу, $N. Нам очень не хватало этих артефактов.$b$bХорошо, что Кеган и другие предатели получили по заслугам.",nil,nil,nil,nil}
RUQL_QUESTS[545]={"Даларанские патрули","Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое.$b$bМне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы.$B$bК сожалению, все окрестности патрулируют волшебники и порабощенные ими элементали.$b$bИтак, напади на них и возвращайся, когда существенно сократишь их число.","Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянью Бездны на мельницу Таррен.","Ты уже $Gпроредил:проредила; патрули Даларана вокруг их руин?","Замечательно. Теперь в руинах можно спокойно поискать артефакты, если быть осторожным.$b$bСпасибо, $N.",nil,nil,nil,nil}
RUQL_QUESTS[546]={"Сувениры смерти","Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую...$B$BПока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен.$B$BМожет, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы 30 черепов, принеси мне, и я тебе хорошо заплачу.","Страж смерти Самс из Мельницы Таррен попросил принести 30 человеческих черепов Хилсбрада.","Итак, $N возвращается? Сколько людей ты $Gубил:убила; сегодня? Надеюсь, не одну сотню!$b$bТы несешь мне черепа?","Превосходные черепа! И какие красивые! Вот тебе обещанная плата, $N!",nil,nil,nil,nil}
RUQL_QUESTS[547]={"Меч Гумберта","Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошел за дровами.$b$bВернувшись, я обнаружил, что мои вещи пропали.$B$BОчевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор.","Найдите меч стража смерти Гумберта в Дун Гароке и верните его владельцу на мельнице Таррен.","Тебе удалось добыть мой меч, $N? Если верховный палач Дарталия узнает о моей небрежности, она прикажет меня повесить вниз головой!","Ты $Gнашел:нашла; его!$b$bАх, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!",nil,nil,nil,nil}
RUQL_QUESTS[548]={"<NYI> <TXT> Подвеска Кровавого камня","Начало заданий линии Подвески Кровавого Камня...<NYI>",nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[549]={"РАЗЫСКИВАЮТСЯ: сторонники Синдиката","По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен.$B$BВсем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда.","Убейте 10 разбойников и 10 сторожей Синдиката и возвращайтесь за наградой к верховному палачу Дарталии в Мельницу Таррен.","Тебе больше нечем заняться, кроме как стоять тут передо мной, $c? В качестве Верховного палача у меня есть дела поважнее, чем пялиться на твою гниющую физиономию.","Великолепно, |3-6($C). Такими темпами мы мигом очистим эти земли от синдикатской швали.",nil,nil,nil,nil}
RUQL_QUESTS[550]={"Битва за Хилсбрад","Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).","Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.","Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?","Так это ты $Gзнаменитый:знаменитая; |3-6($c), нанесший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода.$b$bЕсли ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Темной Госпожи.$b$bХотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решен и мешает строить планы битвы. Однако ты $Gсумел:сумела; доказать, что люди могут пасть. И они падут.",nil,nil,nil,nil}
RUQL_QUESTS[551]={"Заколдованный пергамент","На этот пергамент наложено заклинание, из-за чего надписи на нем невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: $b$b$bНагаз$b$b","Отнесите заколдованный пергамент Хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.","Ого... Ты хочешь что-то мне показать? Надеюсь, какое-нибудь легендарное сокровище, найденное высоко в горах?..","Опять зашифрованные записки?$B$BХотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний.",nil,nil,nil,nil}
RUQL_QUESTS[552]={"Месть Гелькулара","Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья.$B$BНемыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу.$B$BПервым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них.","Отберите у йети жезл Гелькулара и отнесите его новобранцу Тайлванду на мельницу Таррен.","Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.","Ты $Gнашел:нашла; его! Великолепно, $N!",nil,nil,nil,nil}
RUQL_QUESTS[553]={"Месть Гелькулара","Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!","Зарядите жезл Гелькулара силой пламени Азеля, пламени Вераза и пламени Узеля.$B$BВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.","От гробницы Гелькулара исходит духовная энергия.","Из-под земли доносится глухой грохот.",nil,nil,nil,nil}
RUQL_QUESTS[554]={"Расшифровщик Грозовая Вершина","Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесешь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне.$B$BЕсли увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил.","Отнесите заколдованный пергамент геологу Грозовой Вершине в Стальгорн.","Опять мне мешают?$b$bА, на этот пергамент наложено очень тонкое, сложное заклинание. Разумеется, я смогу его распутать, но на это потребуется время. А время – деньги.$b$bМожет быть, мне просто купить его у тебя?","Мудрое решение. Все равно я не верю, что у других ученых хватит умения, чтобы перевести этот свиток. А если он окажется интересным, не бойся – я непременно пошлю за тобой.",nil,nil,nil,nil}
RUQL_QUESTS[555]={"Нежный черепаховый суп","Ты скоро поймешь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!$B$BСкажем, возьмем мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время мне не хватает ингредиентов. Я бы сам пошел к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесешь мне черепашьего мяса, я мигом сварю супчик.","Принесите 10 кусков черепашьего мяса шеф-повару Джессену в Южнобережье.","Ну как, удалось найти нужные продукты? Да, скажу тебе, бывали времена поспокойнее. Ах, если бы не было войн...","Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!",nil,nil,nil,nil}
RUQL_QUESTS[556]={"Каменные талисманы","Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы.$B$BСтупай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов.$B$BТакие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее.","Отнесите 10 истертых каменных талисманов хранителю Бел'варилу из Мельницы Таррен.","Где истертые каменные талисманы, $N? Колдун хочет раскрыть их тайны.","Отличные талисманы. Хотя, кажется, из них немного выдохлась магия, оно и к лучшему. Пусть для начала наш колдун поэкспериментирует на менее активных образцах.$b$bСпасибо, $N.",nil,nil,nil,nil}
RUQL_QUESTS[557]={"Сковывающие браслеты","Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага.$B$BУбей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен.","Принесите 4 браслета Земли хранителю Бел'варилу из Мельницы Таррен.","Здравствуй, $N. Элементали – непростые противники, но я не сомневаюсь, что ты справишься. Ты несешь мне их браслеты?","Тебе удалось их найти. Надеюсь, элементали, с которых сняты эти браслеты не очень сопротивлялись?$b$bХм... После смерти у меня атрофировалось не только сердце, но и чувство юмора заодно.$b$bЧто ж, спасибо, $N. Служа колдуну, служишь и Темной Госпоже, да.",nil,nil,nil,nil}
RUQL_QUESTS[558]={"Автограф Джайны","Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса. Когда я вырасту, я тоже хочу стать героем Альянса!$b$bТы $gзнаком:знакома; с Джайной? Ты можешь взять у нее автограф для меня? Пожалуйста! Я не знаю, как ее попросить, у нее нет времени для таких, как я... другое дело ты! Ты – $gтакой же искатель:такая же искательница; приключений, как и она! Готов поспорить, что тебе получить у нее автограф – раз плюнуть!$b$bПожалуйста!","Отправляйтесь в Терамор и постарайтесь получить автограф леди Джайны Праудмур для своего подопечного.","Когда-нибудь я тоже стану героем, как Джайна... Ну, только мальчиком-героем, конечно.","Вау! Ты $gдостал:достала; для меня автограф Леди Джайны! Огромное тебе спасибо! И... ого... она даже написала мне личное послание! Я знал, что она классная!$b$bМожет быть, однажды я сам поблагодарю её лично... когда сам стану героем Альянса!$b$bТы $gлучший:лучшая;, $N. Спасибо, что $gбыл:была; так $Gдобр:добра; ко мне.",nil,nil,nil,nil}
RUQL_QUESTS[559]={"Доказательство Фаррена","Ты не поверишь, Редпата не устроили все убитые нами мурлоки – не скромничай, ты тоже $gприложил:приложила; к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизкие мурлочьи головы и принес пред его очи!","Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья.","Ты несешь мне головы, $N?","Ох, во имя Света! С них же течет на землю какая-то дрянь.$b$bЯ к ним не притронусь! Рыбу еще можно терпеть, но если у нее вырастают ноги и она ходит взад-вперед... Я рыбы уже несколько недель не ел, и поверь мне, в Южнобережье это означает жизнь впроголодь.",nil,nil,nil,nil}
RUQL_QUESTS[560]={"Доказательство Фаррена","Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Редпату от моего имени, а?","Отнесите мешок с головами мурлоков маршалу Редпату в Южнобережье.","Приветствую тебя. Ты хочешь предложить свою помощь в поддержании порядка в Южнобережье?","Так ты $Gмальчик:девочка; на посылках у Фаррена?$b$bЕсли ты $Gпомог:помогла; ему добыть эти головы, большое тебе спасибо. Южнобережье нуждается в защитниках.",nil,nil,nil,nil}
RUQL_QUESTS[561]={"Доказательство Фаррена","Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьется результатов, пусть лично доложит о них мне.","Поговорите с лейтенантом Фарреном Оринелем из Южнобережья.",nil,"Наги, значит. Похоже, Крассен получил те же сведения, что и я... Ха! Он не сможет возвыситься благодаря мне. Позволь объяснить.",nil,nil,nil,nil}
RUQL_QUESTS[562]={"Эй, Штормград!","Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обеспокоено появлением наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение.$B$BЕсть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне, $n!","Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья.","Я уже письмо написал майору Самуэльсону в Штормград. Теперь мне нужен результат.","Разобравшись с нагами в Южнобережье, я могу не сомневаться в новом назначении. Я вернусь обратно в Штормград... И больше не увижу этот забытый Светом порт.",nil,nil,nil,nil}
RUQL_QUESTS[563]={"Новое назначение","Мне будет легко добиться, чтобы мое донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем еще в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придется попросить тебя отнести мое донесение ему... Главное, чтобы старина Редпат ничего не узнал.","Отнесите донесение Фаррена майору Самуэльсону в крепость Штормграда.","Приветствую тебя. Чем могу тебе помочь я, городской стражник Штормграда?","Что такое? А... Значит, мой внимательный ученик занялся проблемой наг Южнобережья. Спасибо, что $Gпринес:принесла; это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце.",nil,nil,nil,nil}
RUQL_QUESTS[564]={"Серьезная угроза","Ничто не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи лишили нас множества лошадок.$B$BНо я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь!$b$bТы считаешь себя героем? Тогда пойди разберись с ними!","Убейте 8 горных львов и 10 крупных горных львов по поручению Даррена Малвея из Южнобережья.","Горные львы убивают наших лошадей налево и направо, а вот ты хочешь болтать о погоде и прочем. Ты $Gдолжен:должна; пойти и найти себе настоящего героя. Больше убийств и меньше болтовни.","Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой, $N.",nil,nil,nil,nil}
RUQL_QUESTS[565]={"Плащ из меха йети","Я, великий Бартоло, сделаю для тебя знаменитый во всем Альянсе, да и во всем мире, плащ из меха йети!$b$bОбыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, $gмаленький:маленькая:r; |3-6($r)? \"Бартоло, твои плащи лучше всех!\" Да, да! Мне не раз это говорили.$B$BБартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь $gсчастливым обладателем:счастливой обладательницей; одного из моих плащей!","Принесите Бартоло Джинсетти из Южнобережья рулон шерсти, плащ жителя холмов, тонкую нить и 10 клоков меха йети.","Итак, ты $Gвернулся:вернулась; к великому Бартоло. Быть может, все материалы для плаща из меха йети собраны? Или просто хочешь постоять рядом со знаменитостью?","Пришло время для колдовской работы Бартоло! Мне не нужен ни посох волшебника, ни жезл мага. Ведь я, великий Бартоло, творю чудеса при помощи простой иглы и нити!",nil,nil,nil,nil}
RUQL_QUESTS[566]={"РАЗЫСКИВАЕТСЯ: Барон Вардус","По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрекшихся. Вардус является высокопоставленным членом преступной организации Синдикат.$b$bВ последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен.$B$BОн приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии.","Убейте барона Вардуса и принесите его голову верховному палачу Дарталии на мельницу Таррен.","А, $N. Ты не за наградой за голову барона Вардуса?","Ты отлично работаешь, $N. Барон Вардус мертв, и число главарей Синдиката стало меньше. Недолго им осталось лютовать.",nil,nil,nil,nil}
RUQL_QUESTS[567]={"Вооружены и очень опасны!","Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство ловчего смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.","Верховный палач Дарталия из Мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.","Да?","Да ты неплохой охотник за головами, |3-6($c).",nil,nil,nil,nil}
RUQL_QUESTS[568]={"Защита Гром'гола","Тром'ка, |3-6($c)!$B$BТы на удивление вовремя $gоказался:оказалась; в Гром'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают.$B$BЯ поручаю тебе сократить численность ящеров рядом с Гром'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.","Командир Аггро'гош из лагеря Гром'гол поручил вам убить 15 ящеров-кнутохвостов.","Наши попытки наладить поставки всё ещё срываются из-за местных ящеров, |3-6($c).","Ты исполнил свой долг с честью, |3-6($c).",nil,nil,nil,nil}
RUQL_QUESTS[569]={"Защита Гром'гола","Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизжа на юго-востоке от Гром'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны.$B$BЯ приказываю тебе разобраться с этими упертыми ограми.$B$BОтправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок.","Командир Аггро'гош из лагеря Гром'гол поручил вам убить 10 огров-громил и 5 огров-знахарей.","Как дела с ограми руин Мизжа, |3-6($c)?","Отлично. Ты с честью $Gпослужил:послужила; вождю.",nil,nil,nil,nil}
RUQL_QUESTS[570]={"Чары Мок'тардина","Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, $gотважный:отважная:c; |3-6($c).$B$BПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.$B$BЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.","Провозвестник Мок'тардин из лагеря Гром'гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.","Добрые ли вести ты несешь?","Ты превосходно знаешь джунгли, $N. Отличная добыча! Я возблагодарю духов за то, что они пожертвовали таких зверей на благо Орды.",nil,nil,nil,nil}
RUQL_QUESTS[571]={"Чары Мок'тардина","Следующий компонент будет нелегко найти.$B$BЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.$B$BЕго можно добыть только у старых горилл Мглистой долины. Они кормятся к востоку от Пиратской Бухты.$B$BТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.","Принесите сухожилие старой гориллы провозвестнику Мок'тардину в лагерь Гром'гола.","Была ли удача на твоей стороне, $N? Удалось ли тебе добыть сухожилие старой гориллы?","Превосходное сухожилие, $N. Твои усилия скоро окупятся.",nil,nil,nil,nil}
RUQL_QUESTS[572]={"Чары Мок'тардина","То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю.$B$BТеперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром'гола, недалеко от большой арены, есть такое племя ящеров.","Принесите 10 перьев тропических ловцов провозвестнику Мок'тардину в лагерь Гром'гол.","Сопутствовал ли тебе успех в охоте?","Великолепно. Я немедленно их подготовлю.",nil,nil,nil,nil}
RUQL_QUESTS[573]={"Чары Мок'тардина","Остается лишь одно составляющее, и я смогу наложить чары на колье.$B$BК югу отсюда, близко от западного побережья, высоко над утесами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных ученых. Все расы Азерота утверждают, что воды освящены именно для их народа.$B$BВот мое последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться.","Провозвестник Мок'тардин из лагеря Гром'гол попросил вас принести ему воду Святого источника. Кроме того, он поручил вам убить 10 наг-исследователей.","Я готов к зачаровыванию. Вы выполнили мое поручение?","Ты принес мне воду Святого источника, и я могу наложить чары на церемониальное колье.$B$BНоси его с гордостью, во имя Вождя и мощи Орды.",nil,nil,nil,nil}
RUQL_QUESTS[574]={"Особые войска","После удара по обычным партизанам Курцена тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.$B$BЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, $n.$B$BЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.","Убейте 10 коммандос и 6 охотников за головами Курцена.$B$BДоложите об этом лейтенанту Дорену из Лагеря Повстанцев.","Сержант Йохва говорит, что ты силен и отважен, |3-6($C). Докладывай!","$N. Сержант Йохва поверила в твои способности, а я поверил ей. Мы и надеяться не могли на подобный удар по силам Курцена. Я боялся, что мы, повстанцы, совсем одни, и не сможем справиться с гениальным полковником.$b$bБыть может, теперь у нас есть надежда.",nil,nil,nil,nil}
RUQL_QUESTS[575]={"Спрос и предложение","\"Лучший мастер-кожевник Южных морей и старого и нового мира.\" Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче.$B$BМои товары славятся по всему свету как наилучшие по мнению всех экспертов!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель.$B$BЧтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в Северной Тернистой долине.","Принесите 2 большие шкуры речного кроколиска Дриззлику из Пиратской Бухты.","У меня все готово, не хватает только шкур. Одно тебе скажу, не надо заставлять Ридлвокса ждать.$b$bНе стоит расстраивать главного изобретателя Союза ремонтников.","Эти шкуры отлично подойдут. Качество не слишком важно, учитывая, что они идут на внутреннюю отделку сапог, главное, чтобы носить было удобно.$b$bЕсли шкуры жестковаты, я вымочу их в тигриной крови. Вот они, секреты мастерства, да?",nil,nil,nil,nil}
RUQL_QUESTS[576]={"Смотри в оба","Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?","Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.","Эгей, $Gприятель:приятельница;! Может, я и не вижу ничего, но чую я тебя аж с другой стороны порта.$b$bГлаз бы мне не помешал. Капитан меня протащит под килем, если узнает, что моя гляделка в руках грязных пиратов Кровавого Паруса.$b$bКому нужен слепой впередсмотрящий? Я буквально жил на марсовой площадке... а теперь мне в лучшем случае поручат драить палубу.","Лопни моя селезенка! Разрази меня гром! Ты $Gнашел:нашла; мой прекрасный глаз! Проверим, годится ли он по-прежнему.$b$bХо! Я вижу, вижу!!!",nil,nil,nil,nil}
RUQL_QUESTS[577]={"Немного разнообразия не помешает","Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит.$B$B\"Что же делать, Дриззлик?\" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!$B$BПодбой все равно никто не видит, поэтому мы используем более толстую и дешевую шкуру кроколисков с озера Назферити.","Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую Бухту.","Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!$b$bОписания заманчивей не придумаешь, верно?$b$bРазве что ты $Gпринес:принесла; мне шкуры?","Мои сапоги не хуже колбасы, $N. Выглядят отлично, на вкус прекрасны. Я говорю, что внутри сверхкачественное мясо и приправы, и вы едите их с удовольствием.$b$bТак куда приятнее – и вкуснее – если не заглядывать внутрь.",nil,nil,nil,nil}
RUQL_QUESTS[578]={"Камень приливов","Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!$B$BНайди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду.$B$BНеужели Газбан в самом деле нашел Камень?..","По поручению барона Ревилгаза из Пиратской Бухты найдите остров, населенный духами Воды.","У троллей действительно были удивительные волшебные предметы, $N. И теперь, возможно, у меня есть возможность пополнить свою обширную коллекцию. Удалось ли вам найти источник слухов?","Значит, легенды не лгут! Немыслимо!$b$bТеперь надо отыскать способ одолеть проклятье Камня Приливов, если мы хотим найти его. Проклятья – дело магов. Значит, надо обратиться к одному из них.",nil,nil,nil,nil}
RUQL_QUESTS[579]={"Библиотека Штормграда",nil,nil,"Король Вариан придаёт большое значение обучению, и потому выделил средства на то, чтобы сделать копии различных фолиантов и рукописей доступными для всех. Всё просто: ты приносишь мне библиотечный талон, а я выдаю тебе копию одной из доступных книг.","Какая книга вас интересует, $N?",nil,nil,nil,nil}
RUQL_QUESTS[580]={"Потерянный грог Алкача Виски","На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.$B$BНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна \"Пупелливербос\", который мы взяли трофеем у одного пирата по пути в Штормград.$B$BВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.","Алкач Виски из Пиратской Бухты попросил вас принести ему потерянные бутылки портвейна \"Пупелливербос\".","Разрази меня гром! У меня почти кончилась выпивка! Кэп собирается поднять якоря, а старый Слим засохнет, как пустыня Танарис. А уж когда кэп узнает, что пропал его портвейн... лучше сразу за борт!","Лопни моя селезенка! Ты $Gнашел:нашла; грог кэпа!$b$bЯ по гроб жизни тебе обязан, $Gдруг:милая;.$b$bПохоже, снаружи разыгрался шторм. Пока он не пройдет, я согрею нутро грогом из одной из этих славных бутылочек...",nil,nil,nil,nil}
RUQL_QUESTS[581]={"Поиски Йеннику","Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул'Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.$B$BЯ думаю, он в руках племени Кровавого Скальпа.$B$BЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.","Принесите 9 клыков тролля из племени Кровавого Скальпа Нимбойе в лагерь Гром'гол.","|3-6($C). Докажи мне, что воины Кровавого Скальпа пали от твоей руки.$b$bГде твои трофеи?","Отличные клыки, $N. Значит, у тебя хватило сил на сражение с племенем Кровавого Скальпа.$b$bИ это очень хорошо, потому что охота далеко не закончена.",nil,nil,nil,nil}
RUQL_QUESTS[582]={"Охота за головами","Мы должны узнать, мертв ли Йеннику.$B$BУбей как можно больше охотников за головами из племени Кровавого Скальпа и забери у них сушеные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику.$B$BЕсли племя Кровавого Скальпа убило Йеннику, да падет 600-летнее проклятье на душу их предводителя, Ган'зулаха!$B$BСтупай, $n. Охотников за головами можно найти в Руинах Зуулдая и Зул'Кунды, в северной части побережья.","Принесите Нимбойе из лагеря Гром'гол 20 сушеных голов.","$N. Я боюсь за сына нашего вождя. Ты $Gпринес:принесла; мне головы? Я хочу их осмотреть.","Спасибо, $N. Я осмотрю эти головы и узнаю, пал ли бедняга Йеннику под ударом топора охотника за головами.",nil,nil,nil,nil}
RUQL_QUESTS[583]={"Добро пожаловать в джунгли","Добро пожаловать в Тернистую долину!$b$bБыть может, ты не знаешь об этом, но этот дворф – сын единственного и неповторимого Хеминга Эрнестуэя, прославленного героя Альянса и великого охотника на крупную дичь. Подобно отцу, он не слишком жалует гостей, но на твою долю выпало немало приключений, |3-6($c).$b$bСтупай, поговори с ним. Яблочко от яблоньки, как говорится, далеко не падает... наверное, он сможет научить тебя охотиться.","Поговорите с Хемингом Эрнестуэем-младшим.",nil,"Приятно познакомиться, $N. Давно в наши края не забредал |3-6($C). Я здесь с одной-единственной целью – поймать крупного и хитрого зверя. Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что $Gспособен:способна;.$b$bЯ научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер.$b$bПокажи нам свое искусство, и сможешь принять участие в большой охоте.",nil,nil,nil,nil}
RUQL_QUESTS[584]={"Головы племени Кровавого Скальпа","Я не нашел Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Черного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мертвых губ!$B$BПринеси мне головы Ган'зулаха и Неззилока Зловещего и помести их в этот котел.$B$BЭти тролли живут в глубине Руин Зул'Кунды. Принеси их головы... а уж говорить мы их заставим.","Принесите головы Ган'зулаха и Неззилока и положите их в бурлящий котел в лагере Гром'гол.","Зеленый отвар в котле бурлит.","Вы кладете в котел головы Ган'зулаха и Неззилока...",nil,nil,nil,nil}
RUQL_QUESTS[585]={"Разговор с Неззилоком","<Голова Неззилока начинает говорить.>$B$BЭто правда. Я знаю, куда увели дитя Черного Копья. Ты $gодолел:одолела; меня и $gсвязал:связала; мой дух, но я все равно не буду говорить даром!$B$BПлемя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради 3 трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрел рабов в Пустоте. Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зул'Мамве.","Принесите в лагерь Гром'гол трофей из Балиа'ма, трофей из Зиата'джаи и трофей из Зул'Мамве и положите их в бурлящий котел.","Я жду черепов...","Да. Ты $Gсослужил:сослужила; мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трех отличных слуг!$b$bТы – гордость своего клана, |3-6($c), и $Gумилостивил:умилостивила; меня.",nil,nil,nil,nil}
RUQL_QUESTS[586]={"Разговор с Ган'зулахом","<Голова Ган'зулаха начинает говорить.>$B$BБудь ты $gпроклят:проклята;! И будь прокляты твои предки!!!$B$BЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:$B$BОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!$B$BДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!","Убейте 8 охотников, 6 охотников за головами и 4 берсерков из племени Дробителей Черепов.$B$BПринесите разбитую броню Анатека к бурлящему котлу в лагере Гром'гол.","Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.$b$bХа! Ты никогда не справишься с моим заданием...","Мне не хочется верить тебе, но увы, ты несомненно $Gвыполнил:выполнила; мое задание. Теперь, когда Анатек пал, гнев мой поостыл.$b$bТвоя сила приведет тебя к великим свершениям, $N. Но однажды... Мы встретимся в Пустоте, и снова померяемся силой.$b$bЯ буду ждать тебя.",nil,nil,nil,nil}
RUQL_QUESTS[587]={"Понюшка табака","Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.$B$BПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?$B$BТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.$B$BГотов поспорить, что $gбесстрашный:бесстрашная:c; |3-6($c) вроде тебя сможет убедить их поделиться товаром, а?","Диг из Пиратской Бухты попросил принести ему 15 понюшек табаку.","Ну как, удалось найти товары, $N?","Отличная работа, $N! И я даже в море отплыть не успел! Не знаю даже, как тебя благодарить.",nil,nil,nil,nil}
RUQL_QUESTS[588]={"Судьба Йеннику","<Неззилок говорит.>$B$BТы $gсумел:сумела; угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать...$B$BЮный Йеннику навеки потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его.$B$BТы такой магией не владеешь, |3-6($c).$B$BБыть может, племя Черного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.","Поговорите с Кин'вилаем.",nil,"Занзил Отверженный??$b$bЕсли Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки.$b$bНо малая надежда лучше, чем совсем никакой.",nil,nil,nil,nil}
RUQL_QUESTS[589]={"Поющие кристаллы","Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.$B$BЯ попрошу духов джунглей помочь нам в поисках Ока разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око разума.","Принесите 3 пульсирующих синих осколка Кин'вилаю в лагерь Гром'гол.","Ты $Gпринес:принесла; осколки, $N? Без них нам не обойтись, даже когда удастся заполучить Око Разума.","Молодец, $N. Эти осколки правильной формы, и я уже слышу их голос.$b$bПока тебя не было, я говорил с духами джунглей. Теперь я знаю, где находится Око Разума…$b$b...И кто его охраняет.",nil,nil,nil,nil}
RUQL_QUESTS[590]={"Выгодная сделка","Что?$b$bЧТО?!$b$bДенег хочешь? Не должен я тебе никаких денег. $b$bПисьмо? Какое письмо? Может, еще и подеремся? Ну, $gприятель:подружка;, давай! Вот еще, деньги я должен...","Одержите победу в схватке с Кальвином Монтеччи в Похоронном Звоне.",nil,"Невероятно! Какое мастерство!$b$bА я-то думал, ты будешь легкой добычей, $N. Да, хорошенько ты меня $Gотделал:отделала;.$b$bВот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать.",nil,nil,nil,nil}
RUQL_QUESTS[591]={"Глаз разума","Глаз разума находится у огра-мага на востоке отсюда, в глубине холма Мош'Огг. Этого мага зовут Май'Зот, и я помню его с тех пор, как племя Черного Копья обитало в Тернистой долине. Он жесток, а как маг – силен.$B$BИ если у него есть Глаз разума, его магия еще опасней.$B$BВступи с бой с Май'Зотом и отними у него Глаз разума. Задание опасное, но другой надежды спасти Йеннику у нас нет.","Отнесите Глаз разума Кин'вилаю в лагерь Гром'гол.","Приветствую тебя, $N. Духи поют хвалу твоей храбрости, но о победе над Май'Зотом они молчат.$b$bНесешь ли ты мне Око?","Тебе удалось добыть Око? Твою силу должно воспевать в легендах, $N!$b$bКроме того, добывая око ты $Gодолел:одолела; Май'Зота и $Gотправил:отправила; его в Пустоту. Вот почему духи молчали о нем.$b$bХорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть.$b$bВпрочем, об этом будем беспокоиться в другой раз. А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд...",nil,nil,nil,nil}
RUQL_QUESTS[592]={"Спасение Йеннику","Я превратил Око Разума в самоцвет души. Он послужит двоякой цели: оглуши при его помощи Йеннику, а затем помести самоцвет ему на голову, чтобы поймать его душу.$B$BПотом отнеси камень Нимбойе.$B$BЙеннику живет у Занзила Отверженного, в руинах Абораза на Хрустальном взморье далекого мыса Тернистой долины.","Отнесите Нимбойе наполненный самоцвет души.","$N. Кин'вилай сказал, что послал тебя за Йеннику.$B$BЭто правда? Тебе удалось поймать его душу?","Победа! Ты $Gосвободил:освободила; Йеннику от воли Занзила и выполнил задание, которое я считал безнадежным.$B$BНаше племя будет воспевать твое имя, $N, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.",nil,nil,nil,nil}
RUQL_QUESTS[593]={"Наполнение самоцвета души",nil,nil,"Ошеломленный Йеннику стоит перед вами, его разум в другом месте...","Вы прикасаетесь к его лбу самоцветом Души. Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку.",nil,nil,nil,nil}
RUQL_QUESTS[594]={"Послание в бутылке","Записка написана красивым почерком. В ней значится:$B$BЛюбому, кто может мне помочь.$B$BПрошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях.$B$BПо ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе.$B$BМолю тебя, мой будущий спаситель, помоги мне.","Отыщите автора послания в бутылке.",nil,"Ты явился, чтобы освободить меня?",nil,nil,nil,nil}
RUQL_QUESTS[595]={"Пираты Кровавого паруса","Ты не прочь подзаработать, а, $gприятель:подружка;? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины.$B$BВсе мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там творится.","Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.",nil,"На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет.",nil,nil,nil,nil}
RUQL_QUESTS[596]={"Ожерелье кровавых костей","Меня послали в Гром'гол на помощь Нимбойе, но... У меня здесь свои дела.$B$BПлемя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага.$B$BПлемя Кровавого Скальпа живет на севере отсюда. Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей. Собери как можно больше, и я награжу тебя.","Принесите Кин'вилаю 25 ожерелий Кровавых костей в лагерь Гром'гол.","Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты $Gпринес:принесла; мне ожерелья наших врагов?","А, замечательно. Я сварю их, высосу из них силу и сотру в порошок, и дух наших врагов ослабеет!$b$bВот, $N. Возьми это в знак благодарности.",nil,nil,nil,nil}
RUQL_QUESTS[597]={"Пираты Кровавого паруса","На карте Пиратской Бухты нарисован красный крестик именно там, где вы стоите.$B$BНиже имеется подпись:$B$B\"Разбейте здесь лагерь и сидите тихо. Не нападайте, пока не получите сигнал с южного командного поста. Если заметите кого постороннего, сразу убивайте\".","Отнесите находку первому помощнику Краззу в Пиратскую Бухту.",nil,"Конечно, я помню тебя, |3-6($c). Вижу, ты уже $Gвернулся:вернулась; из разведки...",nil,nil,nil,nil}
RUQL_QUESTS[598]={"Ожерелье расколотых костей","Раз ты $gпринес:принесла; трофеи от Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.$B$BТак что начни на них охоту. Собери побольше ожерельев Расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.","Принесите 25 ожерелий Расколотых костей Кин'вилаю в лагерь Гром'гол.","Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты $Gсправился:справилась; с моим заданием?","Велика твоя сила, раз тебе удалось заполучить эти ожерелья, $N. Клан Дробителей Черепов пал под твоими ударами, как молодые ростки под тяжелыми шагами василиска!$b$bХвала твоим деяниям.",nil,nil,nil,nil}
RUQL_QUESTS[599]={"Пираты Кровавого паруса","Лопни моя селезенка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую Бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья!$B$BЗначит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу...","Сообщите о запланированном нападении Кровавого Паруса командиру флота Морскому Рогу.",nil,"Пираты Кровавого Паруса собираются напасть на Пиратскую бухту? С тем же успехом они могут сразу сброситься с Отвесных скал. И все же ты $Gоказал:оказала; моему флоту большую услугу, передав мне эти сведения. Прими благодарность Разбойников Черноводья.",nil,nil,nil,nil}
RUQL_QUESTS[600]={"Рудник Торговой Компании","Торговая Компания ведет операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне!$B$BТорговая Компания обосновалась возле Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но все равно умудряются добывать Поющие кристаллы в ближайших холмах.$B$BОтбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат.$B$BИ.. э... принеси в доказательство сами кристаллы!","Принесите Шиззи Пуззыриксу из Пиратской Бухты 10 синих Поющих кристаллов.","Ты $Gпринес:принесла; мне кристаллы?? Они мне нужны!!!$b$bТо есть... Мне нужно знать, что гнусную Торговую Компанию вскоре вытеснят из Тернистой долины. Потому что, э-э-э, нам, честным предпринимателям, надо зарабатывать на хлеб насущный!","Отлично! Чудесно! Я за них много выручу!!!$b$bТорговая Компания сунулась не в те джунгли, а? Нам всем станет лучше, если они уберутся отсюда, верно?$b$bСпасибо, $N. Ты $Gсделал:сделала; доброе дело.",nil,nil,nil,nil}
RUQL_QUESTS[601]={"Элементали воды","Элементалей воды, несомненно, призвал Газбан, гоблин-волшебник, который нашел Камень Приливов, если верить слухам. Мы знаем, что на владельца камня накладывается проклятие, которое то стирает его из реальности, то возвращает обратно в наш мир...$B$BБыть может, нам удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук.","Принесите барону Ревилгазу в Пиратскую Бухту 6 браслетов элементалей воды.","Как дела, $N?","Я не могу определить навскидку, какие из этих браслетов подойдут, но хотя бы один должен сгодиться. Отнеси их в Даларан, пусть на них посмотрит маг.$b$bНе могу же я, в самом деле, уехать из Пиратской бухты ради какого-то старого мага?$b$bНе то, чтобы я беспокоился, что кто-то попытается занять мое место и стать новым бароном. Никто не посмеет встать на пути у Ревилгаза.",nil,nil,nil,nil}
RUQL_QUESTS[602]={"Магический анализ","Насколько я знаю, магам Даларана удалось восстановить свой разрушенный город и перенести его в небо над Нордсколом, оставив позади гигантский кратер. Но некоторые маги остались здесь, и один из них обязательно найдет время посмотреть на браслеты. Насколько я знаю магов, они не устоят перед возможностью разгадать запутанную магическую головоломку.$B$BВозьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятие Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики.","Отнесите браслеты элементалей воды верховному магу Ансарему Руноплету в Даларан.","Простите, но сейчас я очень занят.","Камень Приливов? Очень интересно. Быть может, вас это удивит – несколько лет назад я написал книгу, посвященную легендам империи Гурубаши. Я знаю об этом камне довольно много.$b$bПо крайней мере, на одном из этих браслетов я вижу остатки магии, которые явно поддаются анализу.$b$bПосмотрим...",nil,nil,nil,nil}
RUQL_QUESTS[603]={"Ключ Ансарема","Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы.$B$BКак ни странно, я знаю одну очень подходящую вещь: древний кинжал, еще одну из тролльских реликвий. Только есть... небольшая проблема.$B$BЯ нашел этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую Бухту и стала пираткой.","Поговорите с Кателиной в Пиратской Бухте.",nil,"Мой кинжал? Ты издеваешься?$b$bТы хочешь услышать, как я превратилась из лучшего бойца на ножах в Пиратской бухте в посмешище для всех пиратов?$b$bЯ проиграла схватку с одним из пиратов Кровавого Паруса – они редкие мерзавцы! – и он забрал мой кинжал в качестве трофея.$b$bОдним острым языком славу бойца не поддержишь...",nil,nil,nil,nil}
RUQL_QUESTS[604]={"Пираты Кровавого Паруса","Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота.$B$BПроникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки.","Командир флота Морской Рог из Пиратской Бухты попросил вас убить 10 сорвиголов из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.","Эгей, $N. Какие вести ты несешь из южного лагеря Кровавого Паруса?","Отлично, $N. Теперь, когда их планы нам известны, это лишь вопрос времени.$b$bПодумать только, эти глупцы бросили якорь недалеко от мыса.",nil,nil,nil,nil}
RUQL_QUESTS[605]={"Осколки Поющих кристаллов","Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.$B$BЯ хочу тебя нанять.$B$BВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.$B$BГодится шкура любого василиска, но на северном побережье, южнее Зул'Кунды, они не такие свирепые.","Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.","Удалось добыть осколки? Процент с выручки получишь!","Ага! Отличные осколки, $N. То, что надо!$b$bВот твоя доля, и... с тобой приятно иметь дело.",nil,nil,nil,nil}
RUQL_QUESTS[606]={"Напугать Трусишку","Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?$B$BВо-первых, есть Филипп \"Трусишка\", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.$B$BСтупай, поохоться на старых горилл Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!","Отнесите 5 потрохов горилл Мглистой долины Филиппу \"Трусишке\" в Пиратскую Бухту.","Эй, мне не нравится, как вы на меня смотрите, $Gсударь:сударыня;.","Ох! Откуда у вас это? Нет, не говорите. Я не хочу знать!$b$bКто вас прислал? Морской волк?",nil,nil,nil,nil}
RUQL_QUESTS[607]={"Возвращение к Маккинли","Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!!$B$BЯ всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймет – не нужно применять силу!","Отнесите плату Трусишки \"Морскому волку\" Маккинли в Пиратской бухте.","Ладно, $N. Где долг Трусишки?","Хе-хе, отличная работа! И как, сильно Трусишка перетрусил, когда ты $Gпоказал:показала; ему потроха?$b$bХа! Я читаю его как раскрытую книгу! Играя с ним в карты, нельзя не выиграть!$b$bСпасибо за помощь, $N. Пришел твой черед получить плату...",nil,nil,nil,nil}
RUQL_QUESTS[608]={"Пираты Кровавого Паруса","Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!$B$BПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.$B$BХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? $n, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...","Командир флота Морской Рог из Пиратской Бухты попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.","В чём дело, $N? Нам нужно атаковать, прежде чем это сделают пираты Кровавого Паруса!","Ах, что за великий день для Разбойников Черноводья! Трижды ура тебе, $N!",nil,nil,nil,nil}
RUQL_QUESTS[609]={"Должники вуду","Список сокращается, но должники все еще остались.$B$BДалее идут Моури \"Деревянная Нога\" Вилкинс, Джон-Джон Ворон и Чаки \"Недотепа\".$B$BЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!$B$BИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.","Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки \"Морскому волку\" Маккинли в Пиратскую Бухту.","Ну что, $Gнашел:нашла; этих трех зараз? $GЗабрал:Забрала; у них ценности?","Отлично! За это я выручу кругленькую сумму, особенно за то, что спрятано внутри ноги Моури! Спасибо, $N!$b$bНадеюсь, эти трое усвоили урок: никогда не ставь на кон то, что не можешь отдать.$b$bМожет быть, они поняли это слишком поздно... Но надо было думать, с кем садишься играть.",nil,nil,nil,nil}
RUQL_QUESTS[610]={"\"Красавчик\" Дункан","Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой.$B$BЭто он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!$B$BЕсли тебе нужен мой кинжал, можешь отобрать его у \"Красавчика\" Дункана, одного из пиратов Кровавого Паруса. Я думаю, что почувствовав металл между лопаток, Дункан охотно расстанется с кинжалом.","Отберите кинжал Кателины у \"Красавчика\" Дункана.","Ты знаешь, что меня раньше никто не побеждал? Да, бывало, ранили, без этого ни одна поножовщина не обходится, но он долбанул меня по голове, я и отключилась. Пришла в себя – а кинжала нет.$b$bПо моему прозвищу легко понять, что без кинжала мне не жизнь, и мне нужен именно этот кинжал.","Тебе удалось одолеть Дункана? Значит, ты не совсем салага, как кажется с первого взгляда.$b$bПожалуй, это означает и то, что мне не стоит в ближайшее время вызывать тебя на бой!",nil,nil,nil,nil}
RUQL_QUESTS[611]={"Проклятье приливов","Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты $gспрашивал:спрашивала;. Посмотри там.$B$BТы $gвернул:вернула; мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!","Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.","Тебе удалось добыть для меня Камень Приливов, $N? Я уже приготовил для него место и купил красивую подставку.","Поразительно! Камень Приливов! Он займет достойное место в моей коллекции древних артефактов троллей. Видишь, создается впечатление, что это и есть окаменевший прилив? Великолепно!",nil,nil,nil,nil}
RUQL_QUESTS[612]={"<UNUSED>","It's a long shot, but perhaps you could try to convince Catelyn to part with her dagger? The heart of a collector, you know how it is?$b$bPerhaps if you mention that it's for me, she might be more well-disposed to sell it to me.","Return Catelyn's blade.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[613]={"Вскрыть ногу Моури","Проклятье! Этот Моури поставил на свою ногу замок, и я не могу ее открыть! Его сокровища внутри, и именно их он мне должен!$B$BМне необходим ключ, чтобы вскрыть этот замок. Моури нередко играл в кости с ограми Мош'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров.$b$bНо если так, придется убить целую толпу, чтобы его отыскать...","Принесите \"Морскому Волку\" Маккинли из Пиратской Бухты ключ Моури.","Эгей, $N! $GНашел:Нашла; ключ Моури?","Ты $Gнашел:нашла; его! Тысяча благодарностей. Ты мне так $Gпомог:помогла;!$b$bВот, возьми – ты $Gзаработал:заработала; это сполна!",nil,nil,nil,nil}
RUQL_QUESTS[614]={"Сундук капитана","Когда-то у меня был корабль, на котором я ходил до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока...$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.","Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.","Йо-хо, $N! Ты $gнашёл:нашла; Горлаша? Этот сундук был моим любимым — в нём был тайный отсек, где я хранил свои самые ценные сокровища!","Ты $gнашёл:нашла; его! О, какой счастливый день! Спасибо тебе, $N. Возвращение моего сундука немного остудило пылающую во мне ярость.$b$bНо моя месть ещё не завершена...",nil,nil,nil,nil}
RUQL_QUESTS[615]={"Капитанская сабля","После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Смоттса\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова мне надавали по шее. \"Месть Смоттса\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с \"Мести Смоттса\", который выжил в последней битве. Он поможет тебе найти великана.","Поговорите с Салагой.",nil,"Привет, привет, $N. Капитан сказал мне, что ты будешь бороться с Неголашем, да?",nil,nil,nil,nil}
RUQL_QUESTS[616]={"Остров духов","Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской Бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.$B$BЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?","Поговорите с бароном Ревилгазом в Пиратской Бухте.",nil,"Интересно. Кажется, я недавно читал книгу, в которой говорилось о чем-то в этом духе…$B$BА, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов.",nil,nil,nil,nil}
RUQL_QUESTS[617]={"Вязанка акириса","Ищешь работу, $n? Если ты не боишься трудностей, могу тебе предложить одно дельце.$B$BУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.$B$BПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.","Принесите каперу Блоудсу из Пиратской Бухты 10 вязанок акириса.","Если ты не по делу, вали отсюда, $N.","Молодец, $N. Не так уж трудно было добыть 10 стеблей акириса, а? Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь.",nil,nil,nil,nil}
RUQL_QUESTS[618]={"Бой с Неголашем","Неголаш – великан-обжора.$B$BКогда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!","Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.","Ты $Gзаполучил:заполучила; мою саблю, $N?","Ты $Gзабрал:забрала; саблю у Неголаша! Я не верил, что мне повезет, $N! Встретив тебя, моя удача вернулась, без сомнения!$B$BСпасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нем почетным гостем.",nil,nil,nil,nil}
RUQL_QUESTS[619]={"Приманка для Неголаша",nil,nil,"Это заброшенная спасательная шлюпка. На ее стороне потускневшими буквами написаны слова:$B$B'Месть Смоттса'","Вы нагружаете лодку едой и выпивкой...",nil,nil,nil,nil}
RUQL_QUESTS[620]={"Кушак с монограммой","Вдоль каймы кушака вышита монограмма \"ГС\".","Верните кушак с монограммой владельцу.",nil,"Привет. У тебя есть ко мне дело?",nil,nil,nil,nil}
RUQL_QUESTS[621]={"Тайна Занзила","Занзил Отверженный и его приспешники живут на руинах Жубуваля и Абораза на северо-востоке от Пиратской Бухты. Его изгнали из племени. Почему? Ну...$B$BЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, и она подавляет их волю и укрепляет тела.$B$BЭта смесь пригодилась бы любому, кто желает повелевать чужим разумом.$B$BПринеси мне образцы этой смеси, и уж я-то найду им применение.","Принесите Шиззи Пуззыриксу из Пиратской Бухты 12 образцов смеси Занзила.","Ты $Gпринес:принесла; мне образцы смеси Занзила?","А, отлично! Вот твоя плата.$b$bИ еще немного сверх... за молчание.",nil,nil,nil,nil}
RUQL_QUESTS[622]={"Возвращение к капралу Калебу","Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости!$b$BДа-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен.","Отнесите целый горшок Кразека капралу Калебу в Лагерь Повстанцев.","Привет, $N. $GДобрался:Добралась; до Пиратской бухты без приключений? Починил ли гоблин Кразек мой горшок??","Готово! Чудесно, я могу готовить обед! Большое спасибо, $N.$b$bНадеюсь, в Пиратской бухте с тобой ничего не случилось. Там всякое бывает... Говорят, иногда гоблины утаскивают пьяных моряков на галеры, приковывают цепями и увозят неизвестно куда...",nil,nil,nil,nil}
RUQL_QUESTS[623]={"Вязанка акириса","$n, раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить еще акириса.$B$BЯ собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?$B$BИщешь приключений? Ты знаешь, где находятся Пылевые топи? Только будь $gосторожен:осторожна;, в Тераморе может быть опасно.","Принесите вязанку акириса каперу Грою в Терамор.","Да?","Что?! Мне некогда с тобой трепаться, |3-6($c). Если ты собираешься попусту тратить мое время, лучше сразу убирайся.$b$bЧто? Тебя прислал Блоудс, да?$b$b*Капер Грой внимательно рассматривает сверток.*$b$bНеплохо, неплохо. Еще один сверток – и клиент будет счастлив.$b$bДумаю, следующий вопрос будет про деньги, а? Ну разумеется!$b$bВот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову.",nil,nil,nil,nil}
RUQL_QUESTS[624]={"Загадка Кортелло","Есть мост, изукрашен резьбою, красивый на нем узор$BК востоку от Мертвого Ветра и к югу от Красногорья$BПод ним тебя ждет подсказка ль, улика ль – как назовешь.$BИ будет на Болоте Печали лежать, пока не найдешь.","Разгадай загадку!",nil,"Намокший пергамент дает вам новую подсказку...",nil,nil,nil,nil}
RUQL_QUESTS[625]={"Загадка Кортелло","Калимдор далекий ждет тебя давно,$BГде надеждам к сроку сбыться не дано.$BТы в Степях почуешь вкус пыли на губах,$BНу а в топях пылевых – лишь печаль и страх.$BНо на юго-запад путь тебя манит,$BМрак пещеры тайну для тебя хранит.","Разгадай загадку!",nil,"Вы находите заплесневелый свиток.",nil,nil,nil,nil}
RUQL_QUESTS[626]={"Загадка Кортелло","Спеши же в славный Лордерон! Давно тебя он ждет.$BТам с мором, гибелью и тьмой сражается народ. $BПусть не страшит тебя война и битвы шум и гам – $BЗато задание свое исполнить сможешь там. $BВот берег Внутренних земель, где шумный водопад, $BТам, под водами его, тебя ждет дивный клад!","Разгадай загадку!",nil,"Вы открываете сундук и обнаруживаете...",nil,nil,nil,nil}
RUQL_QUESTS[627]={"Просьба Кразека","В Теснине Сухоусов – далеко на севере, на Нагорье Арати – есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать.$B$BЯ – знаю.$B$BЯ починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесешь их достаточно, я награжу тебя.$B$BАх, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь тебе помочь!","Принесите 4 партии бедной кровавой руды Кразеку в Пиратскую Бухту.","Привет, $N. Удалось добыть кровавые камни?","А, великолепно! Ты $Gоказал:оказала; мне большую услугу.$b$bВот твоя плата...",nil,nil,nil,nil}
RUQL_QUESTS[628]={"Эксельзиор","Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог.$B$BХотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного.","Принесите Дриззлику из Пиратской Бухты шкуру старого солоноводного кроколиска.","Я где-то читал, что солоноводные кроколиски постепенно вымирают... это повредит моему делу, а?$b$bВпрочем, надеюсь, ты $Gдобыл:добыла; мне шкуру старого солоноводного кроколиска!","Здорово! Благодаря твоей помощи я выполню этот заказ и отправлю его директору Ридлвоксу на следующем корабле в Нижнюю шахту. Быстрее, чем обещал!$b$bЯ сделал лишнюю пару, возьми ее за работу. Все за счет Дриззлика.$b$bИ помни, если нужны тебе сапоги, к Дриззлику ты поскорей прибеги!",nil,nil,nil,nil}
RUQL_QUESTS[629]={"Коварный риф","Давным-давно вода затопила древний город троллей рядом с Гибельным берегом, что на северо-западе. Мы зовем это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться.$B$BСреди руин есть древняя табличка, повествующая о древнем герое троллей, Гри'леке. Это сказание священно в племени Черного Копья, и хотя сама табличка слишком велика и ее не унесешь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре.","Принесите осколок таблички Кин'вилаю в лагерь Гром'гол.","Я жду, когда ты принесешь мне осколок таблички, $N.","Хорошо. Когда я вернусь в Оргриммар, этот осколок будет помещен в священное место. Он будет напоминать нам о силе и чести Гри'лека. Спасибо, $N. Твои деяния говорят о крепнущей дружбе с племенем Черного Копья.",nil,nil,nil,nil}
RUQL_QUESTS[630]={"Послание в бутылке","$n, ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу.$B$BЯ часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко.","Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.","Хвала предкам, кто-то пришел мне на помощь. Ты несешь мне ключ, а вместе с ним и свободу?","Ты спас меня от великого бесчестья, $N. Будь это в моей власти, я приняла бы тебя в свое племя. Пока же я могу лишь вручить тебе этот залог моей благодарности за проявленное мужество и благородство.",nil,nil,nil,nil}
RUQL_QUESTS[631]={"Мост Тандола","Я помню, как горы содрогнулись от ужаснейшего взрыва. Неслабо рвануло, скажу я тебе!$b$bНа мосту Тандола погибли лучшие из наших солдат. Длиннокос говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$b$bНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длиннокос отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$b$bПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$b$bБыть может, ты согласишься поискать нашего разведчика?","Найдите Ржавого Засова для Рага Гармасона.",nil,"Вы натыкаетесь на труп дворфа. На шлеме отчетливо видна надпись: \"Эбенезер Ржавый Засов\".",nil,nil,nil,nil}
RUQL_QUESTS[632]={"Мост Тандола","Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.$b$bРасскажите Рагу Гармасону о случившемся и передайте ему пергамент.","Принесите печальное известие Рагу Гармасону в Дун Модр в Болотину и отдайте ему пергамент, найденный возле трупа Ржавого Засова.","Есть новости о Ржавом Засове, $N?","Какой ужас... Бедный, бедный Эбенезер.",nil,nil,nil,nil}
RUQL_QUESTS[633]={"Мост Тандола","Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $Gопечалил:опечалила;, $n.$b$bНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с Нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.","Уничтожьте взрывчатку.","Умоляю, избавься от проклятой взрывчатки, пока не поздно!","Мост спасен! Ты $Gпомог:помогла; не только мне и королю Магни, но и всему народу Каз Модана!$b$bТеперь нужно продержаться до прибытия подкрепления...",nil,nil,nil,nil}
RUQL_QUESTS[634]={"Просьба о помощи","Я попрошу тебя о еще одном одолжении, |3-6($c). Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на Нагорье Арати, возле Опорного пункта.$b$bОтправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.","Найдите капитана Ниалс в Опорном пункте на Нагорье Арати.",nil,"Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечален вестью о трагедии на мосту Тандола и падении Дун Модра...$b$bНо знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город.$b$bДолг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьется гордое знамя нашего короля! Придется Длинной Косе обходиться своими силами...",nil,nil,nil,nil}
RUQL_QUESTS[635]={"Горный кристалл","Осколок пульсирует у вас в руках...$B$bВам кажется, что он молит о чем-то, пытается передать послание того, кто нуждается в вашей помощи.$b$bВам является видение – в северных горах Арати из земли торчит сияющий кристалл.$b$bВас так и тянет к этому месту.","Найдите кристалл из видения.",nil,"Кристалл пульсирует, будто в него заключена живая сила.",nil,nil,nil,nil}
RUQL_QUESTS[636]={"Легенды Земли <NYI>","В книге идет речь о принцессе элементалей, Мизраэль, и ее заточении глубоко под Нагорьем Арати.$b$bТам же говорится о тайной россыпи кристаллов на нагорье. Эти кристаллы Мизраэль – окна в темницу принцессы.$b$bЕсли отважная душа отыщет эти осколки, быть может, $gон:она; сможет поговорить с Мизраэль...","Найдите кристаллы Мизраэль.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[637]={"Письмо Салли Баллу","Промокший и потрепанный конверт разваливается в руках, и в ладонях остается письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью.$b$bПисьмо адресовано некой миссис Саре Балу из Стальгорна. Оно начинается: \"Дорогая Сара...\"","Отнесите письмо Салли Балу Саре Балу.","Похоже, на твою долю выпало немало странствий и нелегких битв, $C. Да, лихие настали времена. Что нового творится в мире?","Неужели ты $Gвидел:видела; моего Салли подо льдом? Прошу, скажи, что это не так!$B$BДай-ка я прочитаю, что он написал...",nil,nil,nil,nil}
RUQL_QUESTS[638]={"Троллебой","Торас Троллебой мертв, а Стромгард разрушен. Вол'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул'Гуруба.$b$bЗенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части Нагорья Арати, чтобы проследить за этим.","Отправляйтесь в Павший Молот и поговорите с Зенгу.",nil,"Как дела, $C? Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью ее примем.",nil,nil,nil,nil}
RUQL_QUESTS[639]={"Печать Cтрома","В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол'каларом в руке – \"убийцей троллей\", на их древнем наречии.$B$BНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.$B$BМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.$B$BПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.","Добудьте печать Строма для Зенгу в Павшем Молоте.","Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.","Отлично! Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол'калар из могилы Троллебоя.",nil,nil,nil,nil}
RUQL_QUESTS[640]={"Сломанная печать","Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда.$B$BПечать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Соберите фрагменты и принесите их Тор'гану, троллю-шаману, – он сможет восстановить целостность печати.","Добудьте у защитников Стромгарда 5 фрагментов печати, принесите их Тор'гану в Павший Молот.","Тром'ка, |3-6($C). Зенгу сообщил, что вам нужна моя помощь.","А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать.$b$bПожалуй, вам бы лучше закрыть глаза.",nil,nil,nil,nil}
RUQL_QUESTS[641]={"Печать Торадина","Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся еще для вас задания.","Принесите восстановленную печать Торадина Зенгу в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[642]={"Плененная принцесса","Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под Нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!","Соберите 12 частиц Мизраэль и принесите их к радужным осколкам в Теснине Сухоусов.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[643]={"Печать Аратора","Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всем Нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймет, как мыслят эти люди?$B$BКакова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброгласу, командиру кавалерии. Найдите его и принесите мне эту печать.","Добудьте Печать Аратора и принесите ее Зенгу в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[644]={"Печать Троллебоя","Последняя из печатей, необходимых, чтобы отпереть могилу Тораса Троллебоя, хранится у его сына. Он обитает в Стромгарде, в часовне, в том районе, что контролируется ополчением. У принца Галена хорошая охрана, да и сам он боец не промах, так что это задание может оказаться наиболее сложным.","Убейте принца Галена Троллебоя и принесите печать Троллебоя Зенгу в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[645]={"Трол'калар","Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя.$B$BОстанки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол'калар.","Достаньте Трол'калар из могилы Троллебоя в Стромгарде.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[646]={"Трол'калар","Медленно угасает свет. Меч Трол'калар, упрятанный в каменные ножны, освобожден.","Отнесите меч Трол'калар Зенгу в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[647]={"Самогон Маккрила","Ох, и хлебнул я вчера самогона! Узнай Длиннокос, что я отрубился на посту, он оторвал бы мне голову.$b$bБашка раскалывается, жуть. И в ушах гремит, будто осадные машины вокруг грохочут.$b$bОй-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном.$b$bА осталось до истечения срока действия долга всего 15 минут! Отнеси ему самогон, будь другом! И поскорее!","Отнесите самогон Маккрила мастеру-пивовару Бочкопузу в Южнобережье.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[648]={"Спасти КПХ-17/TN!","Из динамика снова слышится искаженный помехами голос гнома:$b$b\"Мне необходимо перегнать КПХ-17/TN в просторное и безопасное место, чтобы провести длительную процедуру наладки. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, к Пещерам Времени! Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полету.$b$bПроводите робота к Пещерам, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!\"","Сопроводите КПХ-17/TN в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[649]={"За медовухой","Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха!$b$bЭто напиток, балда!$b$bНа заброшенной заставе Орды хранится запас \"Медовой зыби\" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и еще пару бутылок мне лично. Поговори с Мальтоном, он тебе все расскажет.","Поговорите с Мальтоном Дрофферсом в Оргриммаре.",nil,"А, это насчет медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую \"Медовую зыбь\" можно выручить много денег... Я знаю того, кто может ее добыть. Он живет во Внутренних землях. Но вот какая штука: он того... эльф он. Высший.$B$BНо ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит.",nil,nil,nil,nil}
RUQL_QUESTS[650]={"За медовухой","Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда.$b$bГилверадин живет неподалеку от пристанища высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!","Поговорите с Гилверадином Ловчим Солнца во Внутренних землях.",nil,"А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашел средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище.$B$BВпрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя.",nil,nil,nil,nil}
RUQL_QUESTS[651]={"Связывающие камни","Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bЧтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать.","Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня.$b$bОтнесите ключи к внутреннему связывающему камню.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[652]={"Разбить краеугольный камень","Открыв замки связывающих камней, ты $gосвободил:освободила; меня от большей части моих оков, но кое-что еще удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bТы $gдолжен:должна; заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия краеугольного камня.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немножко... и моя благодарность потрясет все земные устои!","Найдите и убейте Фозрука. Принесите Жезл Порядка к краеугольному камню на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[653]={"Союзники Мизраэль","<Говорит Мизраэль.>$b$bСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$b$bНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$b$bПоговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.","Поговорите с Герриком Костохватом в Заброшенном гроте в Стальгорне.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[654]={"Полевые испытания в Танарисе","После подключения источника энергии набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо.$b$bЯ позабочусь о доставке.$B$BВсе необходимые образцы ты можешь найти в пустыне Танарис.$B$BСобрав их, доложи о выполнении главному инженеру Чепухастеру.","Добудьте приемлемые образцы тканей 8 василисков, 8 гиен и 8 скорпионов. Отнесите набор для проведения испытаний главному инженеру Чепухастеру в Прибамбасск до окончания действия источника энергии.","Ну что, все образцы $Gуспел:успела; собрать? Если не все, то помни, как только энергия закончится, все результаты пропадут и придется начать все с начала.$B$BЭй, не жди от меня сочувствия я думаю только об интересах Водной компании Прибамбасска, а если мне придется продавать источники энергии до возобновления поставок с ледяных ключей Дун Морога, то да будет так!","Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать все, что захочешь, не боясь потерять данные.",nil,nil,nil,nil}
RUQL_QUESTS[655]={"Павший Молот","Воспоминания по-прежнему ярки, как будто все было вчера... Так много лет без надежды, прикованный к этой проклятой дыре деревом и сталью. И вот наконец появился вождь: Молот Рока блещет полуночными доспехами, высоко вздымает боевой молот...$B$BКак же это подло, как непереносимо, что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...","Поговорите с Тор'ганом в Павшем Молоте.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[656]={"Призыв принцессы","Вы должны нанести поражение Мизраэль прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было великанам с самого начала заковывать ее в цепи?$B$BПотрясающая логика, да?$B$BЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэль.$B$BСделайте так – и она вновь будет поймана в ловушку.","Отправляйтесь к кристаллам Мизраэль, вызовите принцессу и победите ее.$B$BЗаберите ее мистические оковы и присоедините их к кристаллам.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[657]={"Новая чума зарождается?","<Кви начинает просматривать папку.>$B$BЭто в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го-Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело.$B$BМы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если вы не против, проводите ее к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен.","Поговорите с Кинелори на Ферме Го'Шека, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[658]={"Новая чума зарождается?","Так вас Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится.$b$bМы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны.$b$bОна любительница поболтать, но я всегда доверяю ее ощущениям, когда мы бываем в опасных местах.$b$bА вы часом не следопыт, а? Мы думаем, что гонец может относить записки в деревню Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде.","Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го'Шека.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[659]={"Новая чума зарождается?","Приветствую, $n, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.$b$bМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого встречного.$b$bЯ уверен, что тут замешана нежить, и мы ищем доказательства.$b$bДве моих спутницы, Кви и Кинелори, отправились к ферме Го'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдешь их? А то я начинаю беспокоиться.","Найдите Кви и Кинелори у фермы Го'Шека на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[660]={"Новая чума зарождается?","Ладно, $n. Если вы готовы, то и я тоже.$B$BПопробуем?","Защищайте Кинелори, пока она не вернется к Кви.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[661]={"Новая чума зарождается?","После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо ее защищали.$B$BТо, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?","Найдите Фина Оделика в Южнобережье, что в Предгорье Хилсбрада.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[662]={"Поиски на глубине","О'Брин повел корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. \"Вестник\" причалил нормально, но когда \"Девичья Блажь\" и \"Дух Серебряного бора\" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал!$B$BТе два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия.$b$bНужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!","Первый помощник Нилзликс хочет, чтобы вы достали карты и судовые журналы кораблей \"Девичья Блажь\" и \"Дух Серебряного бора\".",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[663]={"Эй, там!","Ой, кого видит Лоло! Это ж крошка-|3-6($c)! Лоло всегда начеку!$b$bДобро пожаловать в Бухту Фальдира. Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$b$bНо Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\". На дне морском они теперь!$b$bЛоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь.","Поговорите с капитаном О'Брином в бухте Фальдира, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[664]={"Затонувшие печали","Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\". Да упокоятся ребята в мире, благословенны их сердца.$B$BО'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам.$b$bВот мы плывем – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришел в себя уже здесь.$b$bЯ жажду их мерзкой холодной крови!","Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[665]={"Затонувшее сокровище","Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О'Брину разыскать пропавшее эльфийское сокровище.$b$bПочти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить ее в очки.","Проводите профессора Физзлторпа в пещеру и обратно.",nil,"Теперь очки работают превосходно! Отличная работа, $N.",nil,nil,nil,nil}
RUQL_QUESTS[666]={"Затонувшее сокровище","Сокровища так долго лежали на дне морском, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьмите эти очки Ловца сокровищ, $n, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О'Брина.$b$bЯ бы и сам поплыл туда, но... эм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.","Доктор Драксельмер в бухте Фальдира хочет, чтобы вы собрали 10 эльфийских самоцветов и вернули ему очки Ловца сокровищ, когда закончите.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[667]={"Смерть со дна морского","Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не умру.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Орудия к бою! Надо оттеснить их.$B$BГотовы, $n?","Защитите Мураша О'Брина во время атаки наг.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[668]={"Затонувшее сокровище","Не будем заставлять капитана О'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bА через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.$b$bВот, $n, отнесите все О'Брину.","Отнесите эльфийские самоцветы капитану О'Брину в бухту Фальдира, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[669]={"Затонувшее сокровище","Командир флота Морской Рог захочет сразу же услышать о нашей находке.$b$bНо, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но еще и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями.$b$bВы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую Бухту, что мы отыскали сокровища и работаем над тем, чтобы достать еще. А этот образчик отвезите ему в качестве доказательства.","Доставьте образец эльфийского самоцвета командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[670]={"Затонувшее сокровище","Слушайте, $n, у вас лицо искателя приключений. Мой флот застрял в Пиратской Бухте, пока мы не загрузимся.$b$bТам, да и не только там, творятся темные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О'Брину, пришвартовавшемуся к побережью Арати.$b$bМогу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?","Отвезите письмо Морского Рога Мурашу О'Брину в Бухту Фальдира, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[671]={"Зловещая магия","Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь. У меня возникли подозрения. Я твердо решил найти источник беспокойства и обнаружил на западе, у Северного поместья, остаточные следы призыва демона. Когда я приблизился, кровь буквально вскипела, и ярость разгорелась во мне.$b$bНа земле я заметил амулет из кровавого камня, какими пользуются, вызывая демона. Однако магическая сила найденного мной камня была уже полностью исчерпана. Мне нужен для изучения другой образец, но я не рискую возвращаться в поместье. Можете ли вы принести мне оттуда несколько амулетов?","Принесите Тор'гану в Павший Молот 10 амулетов из кровавого камня.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[672]={"Вызов духов","Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре в Калимдоре, но его ничто не трогало.$B$BИстории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретенной шаманской магии могла бы дать ему луч надежды. Попробовать стоит!$B$BМы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз ящера, и я посмотрю, что можно сделать.","Соберите 10 глаз ящеров нагорья с долгоногов и твердозубов нагорья, принесите их Тор'гану в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[673]={"Зловещая магия","У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя обладающую магической энергией реликвию, этот чернокнижник призывал в больших количествах ужасных демонов. Мы должны отнять у него этот источник энергии.$B$BНайдите чернокнижника и убейте его. Принесите мне магический объект, который найдете при нем, чем бы он ни оказался. Я предприму шаги по разрушению реликвии и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.","Добудьте сферу кровавого камня у чернокнижницы Марез Клобук и принесите ее Тор'гану в Павший Молот.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[674]={"Вызов духов","Вот, отнесите этот амулет Гор'мулю и посмотрите, пробудит ли сила ящера в нем тот боевой огонь, который некогда пылал в его крови.","Отдайте амулет из когтя ящера Гор'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[675]={"Вызов духов","*Гор'муль бросает амулет на землю.*$B$BВас Тор'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождем во время боя. Жестокий удар судьбы настиг меня...","Поговорите с Тор'ганом в Павшем Молоте, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[676]={"Да падет молот","Слабаки... Все они слабаки. А ты, |3-6($c),\n\n куда смотришь? Думаешь, $gособенный:особенная;? Проверим?$B$BНа форт Павший Молот напали враги. Если не помочь нашим, им не устоять.$B$BВпрочем, не спеши. Прежде надо испытать твое искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжелого Кулака. Когда одолеешь тамошних огров и мародеров, доложи об этом Драму Желчному в Павшем Молоте.","Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака, затем найдите Драма Желчного в Павшем Молоте на Нагорье Арати.","У меня нет времени топор наточить, не говоря уж о том, чтобы покинуть форт и заняться теми тварями, которые убивают моих братьев.$B$BПохоже, опыта тебе не хватает даже для обычного рубаки, не говоря уж о полноценном. Что тебе нужно, $N?",nil,nil,nil,nil,nil}
RUQL_QUESTS[677]={"Призыв к оружию","Тролли племени Сухокожих и огры клана Тяжелого Кулака с Нагорья Арати объединились, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьем их и покажем, что и мы здесь – у себя дома.$B$BТролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям нельзя жить.$B$BМы начнем атаковать троллей Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью.","Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей племени Сухокожих, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.","Если ты еще не $Gвыполнил:выполнила; мое задание – может быть, ты просто трус в душе и неумеха в бою.",nil,nil,nil,nil,nil}
RUQL_QUESTS[678]={"Призыв к оружию","Твоя сила очевидна, $n. Теперь посмотрим, как ты справишься с настоящим врагом.$B$BУ клана Тяжелого Кулака есть логово к юго-западу отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьезным испытанием – по крайней мере, для нас они таковым являются по сию пору.$B$BУбей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьешься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою.","Убейте 10 громил и 4 магов из клана Тяжелого Кулака, затем возвращайтесь к Драму Желчному на заставу Павшего Молота.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[679]={"Призыв к оружию","Зверю вот-вот отрубят голову... и все же для решающего удара требуется огромная сила, $n. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили свое логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости...$B$BНайди и убей вождей клана Тяжелого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель.","Убейте 7 шаманов клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака и возвращайтесь к Драму Желчному на заставу Павшего Молота.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[680]={"Настоящая угроза","Вы отлично служите моему мужу, |3-6($c),\n\n но он не знает, почему Павший Молот подвергается атакам.$b$bОр'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанес ему поражение много лет назад.$b$bМои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях.$b$bМой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари.","Убейте Ор'Калара и принесите его голову Корин Желчной на заставу Павшего Молота.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[681]={"Северное поместье","Мы ведем войну со Стромгардом и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время как силы наших врагов – растут.$b$bНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BПойдите на базу Синдиката в Северном поместье и убейте их. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.","Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.$B$BЗатем вернитесь к капитану Ниалс в Опорном пункте.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[682]={"Знаки Стромгарда","Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.","Принесите 7 знаков Стромгарда Капитану Ниалс в Опорный пункт.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[683]={"Прошение Сары Балу","$n, у меня есть к вам маленькая просьба.$b$bВозьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для $Gтакого:такой;, как ты, $Gславного героя:славной девы;.$b$bМне в моем горе сейчас трудно будет предстать перед королем. Ты понимаешь меня.","Отнесите прошение Сары Балу королю Магни Бронзобороду в Стальгорн.","Значит, вы – $N $C? Я наслышан о вашей доблестной службе Альянсу.$B$BЧто за дело привело вас ко мне ныне?","Подожите минутку, я прочту письмо...",nil,nil,nil,nil}
RUQL_QUESTS[684]={"Разыскивается: Марез Клобук","Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!","Принесите капитану Ниалс в Опорный пункт голову Марез.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[685]={"Разыскивается: Отто и лорд Соколиный Шлем","Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на Нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.","Принесите головы Отто и лорда Соколиного Шлема капитану Ниалс в Опорный пункт.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[686]={"Королевские почести","Вряд ли добрые дворфийские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель ее мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе.$b$bМне не под силу вернуть ее супруга из Круговерти Пустоты, но я могу хотя бы почтить его память.$b$bЯ намерен заказать главному каменотесу Стальгорна Мраморщику памятник в честь Салли Балу.$b$bОтправляйтесь к нему сейчас же и передайте мои слова, |3-6($c). Вы будете моим вестником.","Поговорите с главным каменотесом Мраморщиком.",nil,"Значит, вас послал лично король Магни Бронзобород?$B$BПодумать только! Стало быть, дело важное!",nil,nil,nil,nil}
RUQL_QUESTS[687]={"Тельдарин Заблудший","Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошел с ума и отверг наше учение. Перед побегом он украл cвиток Мизраэль! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях.$b$bЧтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина.","Найдите Тельдарина Заблудшего.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[688]={"Союзники Мизраэль","<Говорит Мизраэль.>$B$BСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$B$BНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$B$BПоговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать.","Поговорите с Заруком в Павшем Молоте, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[689]={"Королевские почести","Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Балу? И вы говорите, что бедный парень погиб на мосту Тандола?$b$bДа будет когда-нибудь мир в Азероте?$b$bКак бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита.","Принесите главному каменотесу Стальгорна Мраморщику 5 кусков альтеракского гранита.","$N, $N, $N! Говорите же, привезли ли вы мне достаточно альтеракского гранита, чтобы начать творить шедевр в честь Салли Баллу?","Замечательно! Лучше, чем я представить мог!$B$BА воображение у меня, между прочим...",nil,nil,nil,nil}
RUQL_QUESTS[690]={"Просьба Малина","Приветствую вас, $n. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам.$B$BВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на Нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.$B$BГород был осажден, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?","Найдите Скуэрто в Опорном пункте на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[691]={"На вес золота","Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.$B$BВот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки племени Сухокожих и нож темного охотника.$B$BНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.","Найдите 10 клыков троллей племени Сухокожих, 4 лекарских сумки племени Сухокожих и нож Темного охотника и принесите их ученику Крайтену в Опорном пункте.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[692]={"Утраченные фрагменты","Свиток Мизраэль... Свиток Мизраэль?! Нет, уверяю вас, не стоит даже думать о нем! Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда!$B$BИли... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ!$B$B...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них.$B$BНо если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток...","Принесите рваный, мятый и обожженный фрагменты свитка Тельдарину Заблудшему.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[693]={"Оружие получше кулаков","Здорово, $n.$B$BЯ выяснил, где оказалась первая вещь Трелана: Коргреш держит ее в Крепости Тяжелого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.$B$BЧтобы добраться до Крепости Тяжелого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найдите этого огра и отберите у него жезл.$B$BА за время вашего отсутствия я соображу, что нам делать со Стромгардом.","Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[694]={"Оборона Трелана","$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДобудьте один из самоцветов и принесите его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.","Найдите лазурный агат и принесите его ученику Крайтену в Опорный пункт.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[695]={"Чары ученика","Вот, $n. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать ее защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы.$B$BУдачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всем, что нужно.","Поговорите со Скуэрто в Опорном пункте, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[696]={"Атака на башню","Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров.$B$BЗащитники башни не будут ими заниматься; придется тебе свое оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!","Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[697]={"Просьба Малина","Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Крайтеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, $n, в этом-то я не сомневаюсь.$B$BДоброго пути!","Отвезите запечатанное письмо верховному магу Малину в Квартал Магов Штормграда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[698]={"Нехватка ресурсов","Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остается немного.$B$BОни любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не $gмог:могла; бы помочь?$B$BМолодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им еще год-другой подрасти.","Принесите Ток'Кару в Болотах Печали 8 сырых боков острозубых кроколисков.","Лок'тар, $C. Путешествие через болота легким не назовешь. Ты действительно отважен, раз решился на это.","Прекрасно! Свежее мясо к ужину! Спасибо, $N.$B$BНынешний вечерок будет куда приятнее прошлого – мы наедимся досыта.$B$BПускай Дар – орк на морду ужасный, зато добрый внутри.",nil,nil,nil,nil}
RUQL_QUESTS[699]={"Нехватка ресурсов","Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. $B$BИз когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию.","Принесите 6 когтей острозубого крепкохвата Ток'Кару на Болота Печали.","Добрая медовуха, костер, армия орков и запас оружия – это то, что надо! Я не жалею, что нас послали сюда охранять Каменор, но было бы неплохо однажды сделать здесь хороший бункер или хотя бы поставить башню.","Рад видеть тебя живым и здоровым, $N.$B$BЭти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше.$B$BНачну работу над твоим экземпляром как можно скорее, много времени это не займет, я уже наловчился его изготавливать.",nil,nil,nil,nil}
RUQL_QUESTS[700]={"Королевские почести","Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе.$b$bНо памятник получился весьма хорош! Думаю, король будет очень им доволен.$b$bТеперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил.","Доставьте известие королю Магни Бронзобороду.",nil,"Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен.$B$BБудем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу.",nil,nil,nil,nil}
RUQL_QUESTS[701]={"Коварство ящера","При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор'муля коварством ящера! Когда сила ящера проникнет в Гор'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!$b$bДля того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров.","Добудьте для Тор'гана 12 сердец ящера, вырвав их у плотоглотов нагорья.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[702]={"Коварство ящера","Возьмите эту сферу и используйте ее энергию, чтобы дух ящера вселился в Гор'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернется в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина.","Отдайте сферу Тор'гана Гор'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[703]={"Жареные крылышки канюка","О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах – просто слюнки текут! $B$BЯ прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть все, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!","Принесите 4 крылышка канюка Ригглфаззу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[704]={"Судьба Эгмонда","Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие \"древние погребальные урны\" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. $B$BМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне","Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[705]={"В поисках жемчуга","Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. $B$BУ меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингредиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. $B$BНадеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. $B$BДа-да, том самом Коварном рифе в Тернистой долине!","Принесите 9 синих жемчужин Ригглфаззу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[706]={"Чары яркого пламени","В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. $b$bНе буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из еще бьющегося сердца детеныша черного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесешь мне сердце, я продемонстрирую тебе свое умение. Драконов найдешь в долине Летлор.","Принесите сердце черного дракона Сигруну Рудотесу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[707]={"Вы нужны Сталекруту!","$n. Я получил отчет геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.$B$BБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.","Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[708]={"Черный ящик","Поверхность этого металлического черного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. $B$BНа днище ящика выбит какой-то символ и надпись под ним: \"Орудие #19 – Осадная бригада Стальгорна\".","Отнесите заржавевший черный ящик в оружейную Стальгорна.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[709]={"Лекарство от судьбы","О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! $B$BНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! $B$BМожет быть... $B$BИди в Ульдаман – проклятье, я все же произнес это! Найди табличку... табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! $B$BОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.","Принесите табличку Рьюн'эха Тельдарину Заблудшему.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[710]={"Изучение стихий: Камень","Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. $B$BКогда они будут закончены, то позволят вызывать еще более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. $B$BМаленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько.","Соберите 10 маленьких осколков камня и принесите Лотвилю Вериатусу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[711]={"Изучение стихий: Камень","$n, ты уже $gпроявил:проявила; себя более $gспособным:способной;, чем все мои ученики вместе взятые. $B$BТеперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и тверды, чтобы отколоть от них куски, удобные для исследования. Ты найдешь их у подножия гор к западу или юго-востоку отсюда. $B$BМожешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты $gпринес:принесла; мне.","Принесите 3 больших куска камня Лотвилю Вериатусу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[712]={"Изучение стихий: Камень","$n, мне нужно, чтобы ты $gпринес:принесла; мне еще кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. $B$BВ магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил еще и нескольких огров. $B$BПринеси-ка мне 5 браслетов, чтобы было с запасом. Мой Серво славится умением путать все реагенты и результаты исследований.","Принесите 5 браслетов Камня Лотвилю Вериатусу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[713]={"Охлаждение горячих голов","Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. $B$BЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. $B$BМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.$B$BБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в Альтераке.","Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[714]={"Гиро...чего?","$n, ты $gсправился:справилась; со своей работой выше всяких похвал.$B$B*Мысли Лотвила явно витают где-то в его экспериментах.*$B$BБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...$B$BОп-ля! Лови-лови, скорей! Да, спасибо.$B$BА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.$B$BЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.","Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[715]={"Жидкий камень","Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты $gдоказал:доказала; свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? $B$BМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. $B$BВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.","Принесите зелье простой невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[716]={"Камень – лучшая одежка!","Я знаю, каким скупым бывает Лотвил, $n, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... $B$BЯ собрал все неиспользованные камни, которые ты $gпринес:принесла;, и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. $B$BНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.","Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[717]={"Дрожь земли","Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надежно. Там обосновались черные драконы, кроме того, этим ограм удалось завладеть знаком земли – а это значит, что требуются куда более серьезные меры. $b$bДраконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака земли. Камни нужны, чтобы сломать печать на узилище. $b$bСломай печать и сделай так, чтобы драконы упокоились навек.","С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Гареку наручники Чернохлыста, цепи Гематуса и знак земли.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[718]={"Миражи","В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. $b$bВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... $b$bНе $gмог:могла; ли бы ты нам помочь?","Верните ящик с припасами Сигруну Рудотесу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[719]={"Дворф и его инструменты","Будь $gосторожен:осторожна;, $n! Повсюду шныряют дворфы Черного Железа – видимо, из клана Тенегорн. $B$BОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.$B$BРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.$B$BКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!","Найдите счастливую кирку Ржанца и верните ее геологу Ржанцу к югу от карьера Тяжелоступа.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[720]={"Предвестник надежды","<куском мела на карте нацарапаны слова>\"Ржанец, они уводят меня в Ульдаман. Пришли помощь!$B-Тяжелоступ\"","Найдите геолога Ржанца и сообщите, что Грез Тяжелоступ жив.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[721]={"Предвестник надежды","$n, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? $B$BПроклятые дворфы из Тенегорна схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! $B$BДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черное Железо!$B$BВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!","Найдите Греза Тяжелоступа в Ульдамане.",nil,"О, я так ослабел... <кашляет> Подойди ко мне, $C?$B$BТебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.<кашляет>",nil,nil,nil,nil}
RUQL_QUESTS[722]={"Амулет тайн","Тебе не занимать смелости, раз ты $gявился:явилась; за мной в Ульдаман, |3-6($c).$B$BЕсли в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. $B$BЭто Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведет их... *кашляет* прямо к свиткам, если их не остановить... Все в твоих руках, $n! Пожалуйста... верни амулет. $B$BЕсли свитки попадут к ним в лапы, Черное Железо сможет создавать еще более мощных големов. Я знаю, я это нутром чую!","Найдите амулет Тяжелоступа и верните его ему в Ульдаман.","Клан Тенегорна очень опасен! Будь $Gосторожен:осторожна;. Вы должны найти амулет.","Ха!<кхе, кхе>$B$BЯ знал, что ты справишься! <сморкается> Отличная работа, $N.<кашляет>",nil,nil,nil,nil}
RUQL_QUESTS[723]={"Клятва верности","<Тяжелоступ едва дышит и, собрав последние силы, поизносит>$B$BНайди Ржанца, $n! Передай ему мой амулет... <кашляет> Он знает, что делать. <кашляет> Он знает, я искал истоки происхождения нашего народа, <кашляет> знает и то, что целью моей жизни было остановить клан Тенегорн. Нельзя позволить, чтобы они нашли свитки... <кашляет>","Отнесите амулет Тяжелоступа геологу Ржанцу в Бесплодные земли.","Сегодня дурной день. Однако в Бесплодных землях каждый день убивает надежду.","Амулет Тяжелоступа! Если раньше в моем сердце еще теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!",nil,nil,nil,nil}
RUQL_QUESTS[724]={"Клятва верности","К кому же обратиться за советом... $B$BИсторик Карник! Конечно! $B$BОн сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. $B$BПолагаю, в Тенегорне прознали, что эти двое располагают тайными сведениями. $B$BСообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше.","Отнесите амулет Тяжелоступа историку Карнику в Стальгорне.","Так-так... Еще один путник, которому что-то нужно от дворфов...$B$BСтупай своей дорогой добрый господин у меня нет времени на праздную болтовню!","О, а вот это совсем другой разговор! Возможно, ты еще не $Gосознал:осознала; всей серьезности происходящего, ведь так?$B$BМы оплачем Тяжелоступа позже.$B$BСейчас я объясню тебе, почему этот амулет так важен.",nil,nil,nil,nil}
RUQL_QUESTS[725]={"Слухи об угрозе","$n, беги, найди советника Белграма как можно скорее. Расскажи ему, что $Gвидел:видела;, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней все как можно подробней. $B$BА я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остается только молиться.","Найдите советника Белграма и отдайте ему записку.","Слушаю тебя, $C.","А, весточка от историка Карника. Прекрасно.$B$BДля него у меня всегда найдется минутка.$B$B<Советник Белграм разворачивает записку и погружается в чтение.>",nil,nil,nil,nil}
RUQL_QUESTS[726]={"Слухи об угрозе","<Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются>$B$BЭто дурные вести... $B$BПожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Тенегорн в Бесплодных землях.","Поговорите с историком Карником.",nil,"Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю, $N!$B$BХорошо. Я знаю, что делать с Кузней Теней.$B$BИх силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор.",nil,nil,nil,nil}
RUQL_QUESTS[727]={"В Стальгорн за книгой Йагина","Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к Геррику Костохвату. Ты найдешь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.","Отнесите печать Молота Геррику Костохвату в Заброшенный грот в Стальгорн.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[728]={"В Подгород за книгой Йагина","Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к хранителю Бел'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.","Отнесите печать Молота хранителю Бел'дугуру в Подгород.","Ага, кто это у нас тут? $GНетерпеливый:Нетерпеливая; $C, чтобы взглянуть на мою коллекцию? Милости прошу!$B$BНо помни: во многом знании много печали, и преумножающий знания преумножает скорбь...","Будь $Gосторожен:осторожена;, $C. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы все возможное, чтобы уничтожить нас!$B$BТы $Gдолжен:должна; всегда сохранять бдительность, осторожность и терпение...",nil,nil,nil,nil}
RUQL_QUESTS[729]={"Рассеянный геолог","Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.$b$bНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.$b$bМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.$b$bПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!","Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[730]={"Неприятности на Темных берегах?","Приятно видеть! $c, $Gинтересующийся:интересующаяся:c; великими археологическими чудесами нашего мира!$b$bЧасто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора.$b$bМеня очень беспокоит судьба группы, которую я отправил на Темные берега. От них уже несколько недель ни слова.$b$bОтправляйся в Аубердин и попробуй узнать, где они пропадают.","Отправьтесь в Аубердин и найдите следы дворфийской изыскательской группы.",nil,"Как же здорово, что главный археолог Седой Ус прислал вас...",nil,nil,nil,nil}
RUQL_QUESTS[731]={"Рассеянный геолог","Итак, Холли... А, да, верно, ты же не Холли. А где Холли?$b$bАй, ладно, это к делу не относится. Мы должны найти эту щетку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнасе захочет узнать, чем я тут занимаюсь.$b$bСообщи мне, когда будешь $Gготов:готова;, и начнем поиски этой щетки... ну, то есть окаменелости! Мы найдем какой-нибудь документ, чтобы в Лиге остались довольны.$b$bТак что, $Gготов:готова;?","Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин.","Изыскатель жив?",nil,nil,nil,nil,nil}
RUQL_QUESTS[732]={"Дрожь земли","Сигрун сказал, что ты $gоказал:оказала; ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Крас из Кирин-Тора, чтобы прекратить беспорядки в низине Летлор. $b$bЯ не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение.$b$bШайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.","Принесите знак земли Гареку.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[733]={"Помогите кто чем может!","Да, туго нам придется, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины...$b$bВ общем, геолог очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. $b$bГлавный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!","Принесите 7 кусков металлолома Сигруну.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[734]={"Сложная задача","Пекрасно, прекрасно... $B$B*Лотвил на секунду отрывает взгляд от кандалов*$B$BСбегай-ка к Люсьену, $n. Мне нужен зубец#5. Принеси его мне.","Поговорите с Люсьеном Подай-Ключ в Бесплодных землях.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[735]={"Звезда, Рука и Сердце","Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать.$B$BЯ помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьемся успеха.$B$BМне нужны три предмета силы. Принесите их мне – и получите книгу.$B$BНазваний предметов я вам не скажу – нас могут подслушивать. Но я их вам напишу.","Доставьте предметы, перечисленные в записке Костохвата, Геррику Костохвату в Стальгорн.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[736]={"Звезда, Рука и Сердце","Тебе нужна книга Йагина? Планируешь собрать свое стадо? Ну, разумеется... и я с удовольствием помогу тебе, $gбрат:сестра;.$B$BВзамен я также попрошу тебя о помощи.$B$BМне нужны три предмета силы. Принеси их – и книга будет твоей.$B$BНазвать вслух эти предметы я не могу, но запишу их.$B$BДобудь мне все, что я укажу в списке. Если справишься с этим, значит, ты действительно $gдостоин:достойна; начать новую главу в истории нашего ордена.","Прочитайте записку Бел'дугура. Принесите перечисленные в записке предметы Бел'дугуру в Подгород.","Как продвигаются дела, $C?","Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень $Gпомог:помогла; нам.",nil,nil,nil,nil}
RUQL_QUESTS[737]={"Запретное знание","У меня есть для тебя книга, $n. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. $B$BВ этой книге содержится много секретов...$B$BОпасных секретов!","Отнесите книгу Йагина Тельдарину.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[738]={"Найти Эгмонда","Геолог Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю \"вел\", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. $B$BВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за крепостью Ангор. Думаю, стоит начать поиски там.","Найдите Эгмонда.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[739]={"Мурдалок","Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. $B$BИ здесь он умер. $B$BПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. $B$B\"Мурдалок,\" – гласит надпись.","Уничтожьте убийцу Эгмонда, Мурдалока. $B$BУбейте 12 костегрызов из племени Каменного Свода. $B$BСообщите геологу Сталекруту в Лок Модане обо всем, что произошло.","У вас есть новости о судьбе Агмонда? Вы его нашли?",nil,nil,nil,nil,nil}
RUQL_QUESTS[740]={"<UNUSED>","This quest will take players into the Searing Gorge.$B$BStay tuned...",nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[741]={"Рассеянный геолог","Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнас? Мне не хотелось бы уезжать с Темных берегов без него.$b$bВот, $n, отвези эту таинственную окаменелость главному археологу Седоусу в Дарнас.","Отвезите таинственную окаменелость главному археологу Седоусу в Дарнас.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[742]={"Большая охота","Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!","Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.",nil,"Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где юному |3-2($C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.",nil,nil,nil,nil}
RUQL_QUESTS[743]={"Соседство со стаей Неистовства Ветра","Спасибо, что $gвыбрал:выбрала; время поговорить со мной, $n. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.","Принесите 8 когтей гарпий из стаи Неистовства Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[744]={"Подготовка к церемонии","$n, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.","Добудьте 6 лазурных перьев и 6 бронзовых перьев.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[745]={"Недобрые соседи","$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.","Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[746]={"Дворфийские делишки","К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.","Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[747]={"Охота начинается","Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $b$bНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна;, – поохоться на равнинных долгоногов и принеси мяса в деревню.","Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[748]={"Отравленная вода","Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.$B$BДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.$B$BНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.","Принесите 6 лап волков прерий и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[749]={"Разграбленный караван","Несколько дней назад мы наткнулись на охраняемый караван Торговой Компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван.$B$BМы бросили их ящики с припасами, полагая, что наши факелы уничтожат все ценное, но учитывая, что возле сожженных телег видели мародеров Торговой Компании, похоже, мы ошиблись.$B$BБыть может, ты сходишь к каравану и посмотришь, что в ящиках?","Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[750]={"Охота продолжается","Любой искушенный в охоте таурен понимает, что ее смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведешь впечатление на старейшин, если принесешь им несколько шкур горных пум – они у нас очень высоко ценятся! $b$bНашим детям нужна одежда, да и шатры пора подлатать.","Принесите 10 шкур горных пум Груллу Соколиному Ветру.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[751]={"Разграбленный караван","Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой Компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг.$B$BСо стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров.","Отнесите бумаги Торговой Компании Морину Ловцу Облаков, которого можно найти неподалеку от деревни Кровавого Копыта.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[752]={"Скромная просьба","Все члены племени живут вместе в мире и гармонии. $b$bМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. $b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?","Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[753]={"Скромная просьба","В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. $b$bДумаю, ты $gдостойный:достойная:c; |3-6($c). Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. $b$bПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.","Наберите кувшин воды из колодца.$b$bОтнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[754]={"Очищение колодца Заиндевевшего Копыта","Я создал тотем для очищения Колодца Заиндевевшего Копыта. Отнеси его к колодцу и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!$B$BЗадание непростое, но кому-то придется это сделать, иначе мы не сможем набирать там воду.$B$BУдачи тебе, $n.","Очистите колодец Заиндевевшего Копыта с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.","Не откладывай, $N. Заражение Колодца Заиндевевшего Копыта необходимо убрать!",nil,nil,nil,nil,nil}
RUQL_QUESTS[755]={"Обряды Матери-Земли","Твоя готовность выполнить скромную просьбу таурена из Нараче и твое желание обрести новые знания весьма похвальны, $n. Не сомневаюсь, придет день, и тебя, |3-6($c),\n\n назовут $gодним:одной; из величайших. $b$bНо сначала ты $gдолжен:должна; пройти три обряда Матери-Земли. $b$bПервым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. $b$bОбиталище провидца сокрыто в холмах к югу от Лагеря Нараче.","Отправьтесь к провидцу Серой Пасти, который живет к югу от Лагеря Нараче.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[756]={"Тотем Громового Рога","Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придется тебе убить несколько охотников прерий и пум плоскогорья, живущих на востоке и на западе, и принести мне их когти.","Принесите 6 когтей охотников прерий и 6 когтей пум плоскогорья Муллу Громовому Рогу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[757]={"Обряд силы","Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утеса.$b$bСначала ты $gдолжен:должна; пройти обряд Силы. Чтобы выдержать это испытание, ты $gдолжен:должна; доказать свою храбрость, убивая врагов племени. $b$bВоины племени Дыбогривов из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. $b$bПокажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.","Убивайте дыбогривов в Ежевичной лощине и принесите 12 их поясов вождю Соколиному Ветру в Лагерь Нараче.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[758]={"Очищение колодца Громового Рога","Тотем готов, $n. Остается лишь провести ритуал очищения.$B$BСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.$B$BИ да пребудут с тобой духи.","Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[759]={"Тотем Буйногривых","Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых. Для этого тебе понадобятся зубы лютых хищников, могучих волков прерий. Ступай на север, поохоться на них и возвращайся.$B$BМогучие волки прерий водятся неподалеку от славного города Громового Утеса.","Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в деревню Кровавого Копыта.","$N. Несешь ли ты зубы волков?",nil,nil,nil,nil,nil}
RUQL_QUESTS[760]={"Очищение колодца Буйногривых","Духи говорят о твоих успехах в деле очищения колодцев племен Заиндевевшего Копыта и Громового Рога, $gюный:юная; $n. Тотем Буйногривых готов, и ты можешь приступить к выполнению своего последнего задания.$B$BКолодец Буйногривых расположен на севере от Громового Утеса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой!","Очистите колодец Буйногривых с помощью тотема очищения колодца Буйногривых.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[761]={"Охота на перепелятников","Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.$B$BЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. $b$bПринеси мне их перья, и прославь свой клан этой победой.$B$BПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.","Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в деревне Кровавого Копыта.","Ну как, $Gнашел:нашла; перепелятников? А где их перья?","Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты $Gпоказал:показала;, на что $Gспособен:способна;. Хорошо, что ты живешь у нас в деревне.",nil,nil,nil,nil}
RUQL_QUESTS[762]={"Посланник зла","Посол Инферний был отправлен в крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Тенегорна в Ульдамане. $B$BНам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! $B$BЗадача проста, $n! Возвращайся в Бесплодные земли и уничтожь посла Инферния. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. $B$BТеперь все в твоих руках!","Убейте посла Инферния в крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.","Время дорого, $N. Рагнарос не будет ждать, когда мы подготовимся.","$N, твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь.$B$BЯ извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Еще раз благодарю тебя.$B$BПрежде чем ты уйдешь, выполни еще одну просьбу от имени короля Бронзоборода.",nil,nil,nil,nil}
RUQL_QUESTS[763]={"Обряды Матери-Земли","Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!","Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.","Что привело тебя в мою деревню, |3-6($C)?","О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты |3-6($c) особой породы!",nil,nil,nil,nil}
RUQL_QUESTS[764]={"Торговая Компания","Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой Компании. Эти гоблины... Компания слишком быстро растет, не жди добра. Как говорят, гоблинам палец в рот не клади.$B$BМаленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок.","Убейте 14 рабочих Торговой Компании и 6 бригадиров Торговой Компании по поручению Морина Ловца Облаков из деревни Кровавого Копыта.","Торговая компания получила отказ в праве на добычу полезных ископаемых здесь, в Мулгоре, но, похоже, отказывать им — дело бесполезное. Однако мы, таурены, не привыкли юлить, и у нас есть другие способы донести свою мысль.","Думаю, такой намек невозможно не понять, а? Торговая компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.",nil,nil,nil,nil}
RUQL_QUESTS[765]={"Бригадир Шумовик","Согласно документам, которые ты $gотыскал:отыскала; в караване, Торговая Компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить.$B$BМне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой Компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли там чего полезного.","Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.","Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая компания во имя прибыли.","Ярость немного отступила при вести о гибели злодея Шумовика. Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой компании. Спасибо за помощь, $N.",nil,nil,nil,nil}
RUQL_QUESTS[766]={"Маззранач","Дедушка рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь, чтобы вылечить воспаленную рану, мне нужны части тел животных, которых непросто отыскать: сердце волка, бедро пумы, чешуя равнинного долгонога и потроха перепелятника.$B$BТоропись, время не ждет.","Принесите сердце волка прерий, бедренную кость пумы плоскогорья, чешую долгонога и потроха перепелятника Мауру Заклинателю Дождя в деревню Кровавого Копыта.","Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…$b$bТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.","А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью.$b$bНо пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…$b$bБудь $Gосторожен:осторожна; во время своих странствий.",nil,nil,nil,nil}
RUQL_QUESTS[767]={"Обряд прозрения","Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.$B$BНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.","Поговорите с Зарельманом Две Луны в деревне Кровавого Копыта.",nil,"Я предчувствовал, что ты придешь ко мне, |3-6($C). Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.",nil,nil,nil,nil}
RUQL_QUESTS[768]={"Добывание шкур","Привет тебе, $Gюноша:девица;. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.","Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.","Еще раз приветствую. Как проходит охота? У тебя есть для меня шкуры?","Ах, какая кожа! Из нее выйдут отличные товары.$B$BВот, Ахахаха. Возьми в знак благодарности...",nil,nil,nil,nil}
RUQL_QUESTS[769]={"Сумка из шкуры кодо","Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.","Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.","$GПринес:Принесла; мои припасы, $N?","Добро. Спасибо, $N. Мое сердце распирает от гордости, когда я вижу молодежь, взыскующую мастерства в кожевничестве!",nil,nil,nil,nil}
RUQL_QUESTS[770]={"Поцарапанный демоном плащ","На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Лагере Солнечного Пастбища о кончине Призрачного Воя...","Отыщите кого-нибудь, кто слышал о Призрачном Вое.",nil,"Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты $Gвырос:выросла в моих глазах, $Gюный:юная; |3-6($C). Оказывается, ты $Gпревосходный:превосходная; $Gохотник:охотница;!$B$BПозволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь мое оружие.$b$bПусть оно не знает промаха и дарует тебе славу.$b$bБудем надеяться, что дух Призрачного Воя упокоился с миром.",nil,nil,nil,nil}
RUQL_QUESTS[771]={"Обряд прозрения","Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.$b$bМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.$B$BВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.","Принесите 2 камня, лежащих у источника, и 2 янтарных семени Зарельману Две Луны в деревню Кровавого Копыта.","Когда ты принесешь мне довольно камней и янтарного семени, я сделаю для тебя воду Провидцев.","Вижу, ты $Gнаучился:научилась; собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.",nil,nil,nil,nil}
RUQL_QUESTS[772]={"Обряд прозрения","Я вручаю тебе воду Провидцев.$B$BВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.$B$BПосле этого следуй за ним навстречу своей судьбе...","Выпейте воду Провидцев перед костром племени в деревне Кровавого Копыта и следуйте за видением.",nil,"Не бойся, $N. Ты успешно $Gпрошел:прошла; Обряд прозрения.",nil,nil,nil,nil}
RUQL_QUESTS[773]={"Обряд мудрости","Чтобы завоевать признание старейшин Громового Утеса, тебе следует пройти Обряд мудрости.$B$BТы уже $gпрошел:прошла; Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение.$b$bСтупай на восток от Громового Утеса, к Красным скалам, и отыщи там дух предков.","Отправляйтесь в Красные Скалы на востоке от Громового Утеса и поговорите с духом предков.",nil,"Ты $Gприложил:приложила; много стараний, чтобы пройти обряды Матери-Земли, $N.$b$bМы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утес. Итак, я передаю тебе почетную обязанность хранить его от бед.$b$bТы $Gпрошел:прошла; Обряд мудрости, $Gюный:юная; $N. Отныне ты можешь с гордостью войти в Громовой Утес.",nil,nil,nil,nil}
RUQL_QUESTS[774]={"<UNUSED>",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[775]={"Путешествие в Громовой Утес","Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.","Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.",nil,"Привет тебе, $Gюный:юная; |3-6($C). Вижу, тебе удалось отыскать дорогу ко мне.",nil,nil,nil,nil}
RUQL_QUESTS[776]={"Обряды Матери-Земли","Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра'чеи.","Кэрн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра'чеи.","Ты уже $Gвыследил:выследила; Арра'чею?","Отлично! Добрая охота.$b$bЯ пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо.$b$bТы $Gоказал:оказала; своему народу услугу.",nil,nil,nil,nil}
RUQL_QUESTS[777]={"Сложная задача","Ну, теперь за дело! $B$BЯ буду здесь... в укрытии. $B$BЕсли хочешь, можешь присоединиться.","Принесите зубец #5 Лотвилу Вериатусу.","*Не отрывая взгляд от кандалов, Лотвил нетерпеливо протягивает руку.*$b$bНу? Давай сюда зубец!","Ага, прекрасно! Отойди-ка в сторонку и наблюдай, как вершится история!$b$b*Лотвил вновь погружается в работу.*",nil,nil,nil,nil}
RUQL_QUESTS[778]={"Сложная задача","Ха! Сделано! $B$BЛюсьен, Серво, время пришло! $B$BТы $gготов:готова; стать $gсвидетелем:свидетельницей; запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн, $n? $B$BСейчас я призову могущественного элементаля. Это величайший день для всех нас!","Победите Стража Фам'ретора и верните оковы Стихий Лотвила Лотвилу Вериатусу.","Да... Не совсем тот результат, на который я рассчитывал... Не вернешь ли ты теперь мне оковы?","Спасибо, $N! Ну и денек!$B$BНе думал я, что так получится. Хорошо, что с помощью магии мне удалось загнать тварь туда, откуда она появилась...$b$bВот, это миллионная доля моей благодарности...",nil,nil,nil,nil}
RUQL_QUESTS[779]={"Печать земли",nil,nil,"Печать Земли покоится здесь. В ней — три углублённые ниши для аметистового, опалового и алмазного рунического камня.","Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.",nil,nil,nil,nil}
RUQL_QUESTS[780]={"Боевые вепри","Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. $b$bПойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлебку для наших детишек!","Принесите 8 боков и 8 рыл боевых вепрей Груллу Соколиному Ветру.","То, что боевые вепри творят в наших землях, уже переходит всякие границы. $GСумел:Сумела; ли ты приструнить этих зверей? А бока и рыла $Gпринес:принесла;?","Прекрасно! Мы сварим отличную похлебку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком.",nil,nil,nil,nil}
RUQL_QUESTS[781]={"Нападение на Лагерь Нараче","Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!","Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.","Ты выглядишь обеспокоенным, $N. Какие вести ты $gпринёс:принесла;?","Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты $gспас:спасла; жизни многих тауренов, $N.",nil,nil,nil,nil}
RUQL_QUESTS[782]={"Разорванные союзы","От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! $B$BМы наняли То'груна и его шайку огров-наемников, чтобы они помогли нам получить знак земли – ключ, необходимый, чтобы открыть драконье узилище. Но То'грун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!","Убейте главаря То'груна и принесите знак земли Горну в Каргат.","Предательство То'груна... Неудивительно, что огры больше не в Орде. Более всего на свете я желаю их смерти и возвращения знака Земли!$B$BЕсли ты еще не расправился с их шайкой, поспеши в лагерь Бофф. Он расположен к юго-востоку от Каргата.","Теперь, когда от То'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишенные главаря, рассеются по пустыне. Так малая победа принесла с собой великую!$B$BЗнак Земли снова у нас, и мы сможем отомкнуть узилище черных драконов в долине Летлор. Мы спасем их от уготованного им вечного заключения, хотя и свершим их судьбу!",nil,nil,nil,nil}
RUQL_QUESTS[783]={"Внутренняя угроза","Надеюсь, ты $gготов:готова; к подвигам, |3-6($c), поскольку для тебя есть дело здесь, в Североземье.$B$BИ я имею в виду не мирные сельские заботы.$B$BСтража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких.$B$BЕсли ты $gготов:готова; откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной.","Поговорите с маршалом Макбрайдом.",nil,"Отлично. Еще один доброволец. В эти дни у нас много таких, как ты.$b$bНадеюсь, нам хватит бойцов.$b$bЗемлям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам. И из-за этого бандитские шайки вольготно чувствуют себя в наших землях.$b$bНам приходится воевать на много фронтов... Готовьтся к долгой войне, $N.",nil,nil,nil,nil}
RUQL_QUESTS[784]={"Бей предателей!","Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$b$bВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$b$bПокажи свою доблесть, $n. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.","Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га'Току на Колючий Холм.","Ты $Gслышал:слышала; приказ, $N. Речь идет о безопасности Дуротара! Выполняй свою задачу – либо уходи с позором.$b$bПокажи свою доблесть, выбей людей из крепости Тирагард!","Твоя отвага скоро станет известна всем, |3-6($C)! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.",nil,nil,nil,nil}
RUQL_QUESTS[785]={"Стратегический союз","Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.$b$bТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.$b$bИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.$b$bРазыщи Лара и спроси, не нужна ли ему помощь.","Разыщите Лара Ночного Клыка на западной окраине деревни Сен'джин.",nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[786]={"Предотвращение агрессии племени Колкар","Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.","Лар Ночной Клык из деревни Сен'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.","Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!","Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь.$b$bА кровопролитий в эти смутные времена и без того хватает.$b$bТы хорошо $Gпослужил:послужила; своему народу, |3-6($C).","План нападения на долину Испытаний уничтожен","План нападения на деревню Сен'джин уничтожен","План нападения на Оргриммар уничтожен",nil}
RUQL_QUESTS[787]={"Новая Орда","Тром'ка, |3-6($c)! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.$b$bОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.$b$bГорнек скажет тебе, что делать дальше.","Зайти в Логово к Горнеку.",nil,"Еще один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно. К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой.",nil,nil,nil,nil}
RUQL_QUESTS[788]={"Кабаньи клыки","Вот тебе первое поручение, чтобы ты $gнабрался:набралась; опыта и $gпоказал:показала; себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.$b$bПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.","Убейте 8 пятнистых вепрей и вернитесь в Логово к Горнеку.","Не рано ли ты $Gвернулся:вернулась;, а, $N? Надеюсь, ты не будешь уверять, будто $Gвыполнил:выполнила; все, что тебе было поручено?","Ну что ж, $N, неплохо. Но не задирай носа: грядут бои с куда более серьезными врагами.$b$bОднако ты $Gпоказал:показала; себя достойным бойцом. В следующем испытании тебе придется встретиться с более опасным противником, так что дополнительная защита не помешает.",nil,nil,nil,nil}
RUQL_QUESTS[789]={"Жала скорпидов","Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне восемь их хвостов, чтобы доказать свою воинскую доблесть.$b$bИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...$b$bНо тебе-то оно не понадобится, а?","Добудьте 8 хвостов рабочих скорпидов и принесите их в Логово Горнеку.","У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!","Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого.$B$BНу что ж, $N! Я научил тебя всему, чему мог. Ты $Gоказался:оказалась; $gхорошим:хорошей; $Gучеником:ученицей;. Я буду с интересом следить за твоей карьерой.",nil,nil,nil,nil}
RUQL_QUESTS[790]={"Саркот","$C! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.$b$bА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...","Убейте Саркота и принесите его коготь Хана'зуа.","Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…$B$BНо я хочу умереть, зная, что последний из моих врагов тоже мертв!","Да, убить его мне не удалось, но ранил я его серьезно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берет!",nil,nil,nil,nil}
RUQL_QUESTS[791]={"Больше сумок – больше добычи!","Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.$b$bЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.$b$bА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.$b$bЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.","Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне Колючего Холма.","Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.$b$bЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.$b$b\r\nНо моя должность стража открыла мне новый взгляд на вещи.","Отлично, $N! Такая сумка пригодится любому хорошему бойцу.$b$bЯ отдаю честь твоей силе и решимости умереть во имя Орды!",nil,nil,nil,nil}
RUQL_QUESTS[792]={"Злобные фамильяры","Что ж, |3-6($c), надеюсь, у нас ты многому научишься.$b$bМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!$b$bВ долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос.$b$bИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.","Убейте 8 злобных фамильяров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.","Чтобы доказать свою доблесть в битве с Пылающим Клинком, ты должен сперва победить его мерзких фамильяров. Вернись ко мне, когда сделаешь это.","Молодец, $N!$b$bДа, злобные фамильяры для злодеев из Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предрекает великие события!",nil,nil,nil,nil}
RUQL_QUESTS[793]={"Разорванные союзы","Печать земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака земли ты сможешь извлечь рунные камни и разрушить печать земли. $b$bНо будь $gосторожен:осторожна;, $n, Чернохлыст и Гематус очень опасны. Ты $gдолжен:должна; убить их и принести мне их наручники. $B$BДолина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!","С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Горну наручники Чернохлыста, цепи Гематуса и знак земли.","Немногие создания сравнятся по мощи и хитрости с драконами, и немногие драконы сравнятся по свирепости с Чернохлыстом и Гематусом.","Черные драконы вступают в союз с отступниками – орками Черной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Черной Горы.",nil,nil,nil,nil}
RUQL_QUESTS[794]={"Медальон Пылающего Клинка","С помощью ворожбы я узнала, что в глубине Грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.$b$bЭтот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.$b$bНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамилиары, с которыми тебе уже доводилось встречаться!$b$bСтупай, $n. Грот находится к северо-западу отсюда.","Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.","Ну что, $N, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?","Он у тебя! Молодец!$B$BТеперь у нас есть возможность вытеснить приспешников Пылающего Клинка из долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях.$B$BТак что эта встреча с ними была не последней.",nil,nil,nil,nil}
RUQL_QUESTS[795]={"Печать земли",nil,nil,"Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.","Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.",nil,nil,nil,nil}
