RUQL_QUESTS[8383]={"Помни Альтеракскую долину!",nil,nil,nil,"Ты – гордость Альянса, $N. Если не сдаваться и не отступать, вскоре мы одержим победу над Ордой!",nil,nil,nil,nil}
