RUQL_QUESTS[9478]={"<UNUSED>Переносной целительный источник",nil,nil,nil,nil,nil,nil,nil,nil}
RUQL_QUESTS[9479]={"<UNUSED>Славное знамя Альянса",nil,nil,nil,nil,nil,nil,nil,nil}
